INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('dd6895cf-5e0d-501d-ad04-9e2f61a79b66', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 11, 11, 'shall I not, as I have done to Samaria and her idols, so do to Jerusalem and her idols?'),
  ('8458c064-8b35-5fcd-a7b6-c077dec9a236', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 12, 12, 'Therefore it will happen that, when the Lord has performed his whole work on Mount Zion and on Jerusalem, I will punish the fruit of the willful proud heart of the king of Assyria, and the insolence of his haughty looks.'),
  ('bdbe600a-2ca5-5c3d-aa35-44f26bf662ad', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 13, 13, 'For he has said, "By the strength of my hand I have done it, and by my wisdom; for I have understanding: and I have removed the boundaries of the peoples, and have robbed their treasures. Like a valiant man I have brought down their rulers.'),
  ('ec86f951-3f3d-5182-a108-c6cb5141cf92', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 14, 14, 'My hand has found the riches of the peoples like a nest, and like one gathers eggs that are abandoned, have I gathered all the earth. There was no one who moved their wing, or that opened their mouth, or chirped."'),
  ('6a5f53eb-4428-5c30-a1cc-12d0f2801a5a', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 15, 15, 'Should an axe brag against him who chops with it? Should a saw exalt itself above him who saws with it? As if a rod should lift those who lift it up, or as if a staff should lift up someone who is not wood.'),
  ('12dc2d2f-b014-5919-aed8-800d0a3c5ad0', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 16, 16, 'Therefore the Lord, Yahweh of Armies, will send among his fat ones leanness; and under his glory a burning will be kindled like the burning of fire.'),
  ('36dcc88f-2fbf-5cf7-a271-223bef67824e', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 17, 17, 'The light of Israel will be for a fire, and his Holy One for a flame; and it will burn and devour his thorns and his briers in one day.'),
  ('5030f80d-5cb9-54d2-a791-a02f9db75784', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 18, 18, 'He will consume the glory of his forest, and of his fruitful field, both soul and body. It will be as when a standard bearer faints.'),
  ('51728d8b-1a05-533e-a8a0-4cd341197957', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 19, 19, 'The remnant of the trees of his forest shall be few, so that a child could write their number.'),
  ('56d0a387-e543-5d8b-af48-78bdb146ada1', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 20, 20, 'It will come to pass in that day that the remnant of Israel, and those who have escaped from the house of Jacob will no more again lean on him who struck them, but shall lean on Yahweh, the Holy One of Israel, in truth.'),
  ('fc4307cd-76e7-571c-a7cb-0f954f59da96', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 21, 21, 'A remnant will return, even the remnant of Jacob, to the mighty God.'),
  ('4ccfcc62-c63f-55a9-a98c-1dd24731f922', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 22, 22, 'For though your people, Israel, are like the sand of the sea, only a remnant of them will return. A destruction is determined, overflowing with righteousness.'),
  ('e9e2ab93-558e-5015-a5c6-09e4d4b10ad5', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 23, 23, 'For the Lord, Yahweh of Armies, will make a full end, and that determined, in the midst of all the earth.'),
  ('b51a674b-9763-56ff-ad9c-8398a28a7d65', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 24, 24, 'Therefore the Lord, Yahweh of Armies, says "My people who dwell in Zion, don''t be afraid of the Assyrian, though he strike you with the rod, and lift up his staff against you, as Egypt did.'),
  ('f5de495d-9e73-507a-a66c-3654bad5729d', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 25, 25, 'For yet a very little while, and the indignation against you will be accomplished, and my anger will be directed to his destruction."'),
  ('a3072b78-201c-5bee-a4ac-559688a33bd1', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 26, 26, 'Yahweh of Armies will stir up a scourge against him, as in the slaughter of Midian at the rock of Oreb. His rod will be over the sea, and he will lift it up like he did against Egypt.'),
  ('26e11068-e058-52ba-aa32-1581d285691c', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 27, 27, 'It will happen in that day, that his burden will depart from off your shoulder, and his yoke from off your neck, and the yoke shall be destroyed because of the anointing oil.'),
  ('02047718-92be-5b50-aae1-68dd15bd1e9e', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 28, 28, 'He has come to Aiath. He has passed through Migron. At Michmash he stores his baggage.'),
  ('3fa21860-3cb5-50a7-ab37-0cfc430e4e3c', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 29, 29, 'They have gone over the pass. They have taken up their lodging at Geba. Ramah trembles. Gibeah of Saul has fled.'),
  ('499b3e8b-b9c8-5dc9-a3d0-381a7a2689f9', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 30, 30, 'Cry aloud with your voice, daughter of Gallim! Listen, Laishah! You poor Anathoth!'),
  ('4f96fe43-f38b-5200-a9c8-77d88b5eaf5c', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 31, 31, 'Madmenah is a fugitive. The inhabitants of Gebim flee for safety.'),
  ('7e770d0f-be3e-5f1b-a5b6-b839e5ba4bee', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 32, 32, 'This very day he will halt at Nob. He shakes his hand at the mountain of the daughter of Zion, the hill of Jerusalem.'),
  ('d893a98e-f251-5be2-ac03-3e81edfdcd46', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 33, 33, 'Behold, the Lord, Yahweh of Armies, will lop the boughs with terror. The tall will be cut down, and the lofty will be brought low.'),
  ('00618e58-53b8-55f9-a79f-3d79d2860171', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 34, 34, 'He will cut down the thickets of the forest with iron, and Lebanon will fall by the Mighty One.'),
  ('94bd7b2d-79d0-524e-a010-3d9e732483c9', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 1, 1, 'A shoot will come out of the stock of Jesse, and a branch out of his roots will bear fruit.'),
  ('2d8fc166-d2ec-53b2-aa45-edfca4d9d929', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 2, 2, 'The Spirit of Yahweh will rest on him: the spirit of wisdom and understanding, the spirit of counsel and might, the spirit of knowledge and of the fear of Yahweh.'),
  ('61888e35-8dcf-5ad6-aa86-f8d8266a70b0', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 3, 3, 'His delight will be in the fear of Yahweh. He will not judge by the sight of his eyes, neither decide by the hearing of his ears;'),
  ('28515dbf-d355-552f-aa2a-713b6b77a034', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 4, 4, 'but with righteousness he will judge the poor, and decide with equity for the humble of the earth. He will strike the earth with the rod of his mouth; and with the breath of his lips he will kill the wicked.'),
  ('ae015398-8894-589a-a4dc-5e6edf2684f9', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 5, 5, 'Righteousness will be the belt of his waist, and faithfulness the belt of his waist.'),
  ('2ed23849-2bc6-597e-a6d8-993b03e81fae', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 6, 6, 'The wolf will live with the lamb, and the leopard will lie down with the young goat; The calf, the young lion, and the fattened calf together; and a little child will lead them.'),
  ('f761a911-2c84-5b87-ad11-ccbbcfd7c400', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 7, 7, 'The cow and the bear will graze. Their young ones will lie down together. The lion will eat straw like the ox.'),
  ('1a514cd7-5caf-5313-aa79-1c5ba68612d3', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 8, 8, 'The nursing child will play near a cobra''s hole, and the weaned child will put his hand on the viper''s den.'),
  ('274ffe77-546f-54df-a8ac-82d98156496d', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 9, 9, 'They will not hurt nor destroy in all my holy mountain; for the earth will be full of the knowledge of Yahweh, as the waters cover the sea.'),
  ('6c872ec0-7d14-5cba-ab11-7cc1974774c6', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 10, 10, 'It will happen in that day that the nations will seek the root of Jesse, who stands as a banner of the peoples; and his resting place will be glorious.'),
  ('90228ee6-c8a6-5497-a1a4-24e037a06621', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 11, 11, 'It will happen in that day that the Lord will set his hand again the second time to recover the remnant that is left of his people from Assyria, from Egypt, from Pathros, from Cush, from Elam, from Shinar, from Hamath, and from the islands of the sea.'),
  ('36d8b4ec-66d4-5da6-a21d-3fa3186ec2bd', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 12, 12, 'He will set up a banner for the nations, and will assemble the outcasts of Israel, and gather together the dispersed of Judah from the four corners of the earth.'),
  ('54440d36-d6dc-563d-a341-1a56d208a047', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 13, 13, 'The envy also of Ephraim will depart, and those who persecute Judah will be cut off. Ephraim won''t envy Judah, and Judah won''t persecute Ephraim.'),
  ('9a09310f-8e2c-5579-a7db-692b062c4441', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 14, 14, 'They will fly down on the shoulders of the Philistines on the west. Together they will plunder the children of the east. They will extend their power over Edom and Moab, and the children of Ammon will obey them.'),
  ('18cec377-1daf-5a0a-a815-61929fb5bf59', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 15, 15, 'Yahweh will utterly destroy the tongue of the Egyptian sea; and with his scorching wind he will wave his hand over the River, and will split it into seven streams, and cause men to march over in sandals.'),
  ('9a90683b-d9ee-5406-a66a-9a870360e1d8', 'cfbe8e33-868b-5e5c-aa7a-d6448df767e4', NULL, 16, 16, 'There will be a highway for the remnant that is left of his people from Assyria, like there was for Israel in the day that he came up out of the land of Egypt.'),
  ('223ff498-2a97-5db9-ac30-e904061a3649', 'f8714570-a95f-5b87-aedd-9fa8759f145f', NULL, 1, 1, 'In that day you will say, "I will give thanks to you, Yahweh; for though you were angry with me, your anger has turned away and you comfort me.'),
  ('d71a5651-4a61-52fe-a0ee-c899b0e0d6b3', 'f8714570-a95f-5b87-aedd-9fa8759f145f', NULL, 2, 2, 'Behold, God is my salvation. I will trust, and will not be afraid; for Yah, Yahweh, is my strength and song; and he has become my salvation."'),
  ('a9d93170-c3b5-58a9-a150-7a5fdfc45f8a', 'f8714570-a95f-5b87-aedd-9fa8759f145f', NULL, 3, 3, 'Therefore with joy you will draw water out of the wells of salvation.'),
  ('c1b1b0fc-801b-5ef2-a8aa-458e418b5531', 'f8714570-a95f-5b87-aedd-9fa8759f145f', NULL, 4, 4, 'In that day you will say, "Give thanks to Yahweh! Call on his name. Declare his doings among the peoples. Proclaim that his name is exalted!'),
  ('1ff1a3e7-5209-52ca-af4f-c95b3a24d9a1', 'f8714570-a95f-5b87-aedd-9fa8759f145f', NULL, 5, 5, 'Sing to Yahweh, for he has done excellent things! Let this be known in all the earth!'),
  ('35c458c7-c913-5d06-aaff-2a156b27457b', 'f8714570-a95f-5b87-aedd-9fa8759f145f', NULL, 6, 6, 'Cry aloud and shout, you inhabitant of Zion; for the Holy One of Israel is great in the midst of you!"'),
  ('d955498b-856a-52a0-a60a-1871d83006fb', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 1, 1, 'The burden of Babylon, which Isaiah the son of Amoz saw:'),
  ('f2c2cb3d-c250-5809-ac14-2ad504834d2e', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 2, 2, 'Set up a banner on the bare mountain! Lift up your voice to them! Wave your hand, that they may go into the gates of the nobles.'),
  ('6fb83125-34ac-539a-a690-2784954659a6', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 3, 3, 'I have commanded my consecrated ones; yes, I have called my mighty men for my anger, even my proudly exulting ones.'),
  ('dc8b2f9b-ca57-5490-a3bc-67a447a427e7', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 4, 4, 'The noise of a multitude is in the mountains, as of a great people; the noise of an uproar of the kingdoms of the nations gathered together! Yahweh of Armies is mustering the army for the battle.'),
  ('dbfaa5ba-172d-5e26-a091-85bbfff7631d', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 5, 5, 'They come from a far country, from the uttermost part of heaven, even Yahweh, and the weapons of his indignation, to destroy the whole land.'),
  ('5c306166-c20b-56aa-af22-ecb17314ce21', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 6, 6, 'Wail; for the day of Yahweh is at hand! It will come as destruction from the Almighty.'),
  ('45a2d50d-092a-5b54-ae43-da2682ebc5b5', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 7, 7, 'Therefore all hands will be feeble, and everyone''s heart will melt.'),
  ('44618338-1176-5906-a501-17ae703cf47e', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 8, 8, 'They will be dismayed. Pangs and sorrows will seize them. They will be in pain like a woman in labor. They will look in amazement one at another. Their faces will be faces of flame.'),
  ('c1bbd3c4-0f65-5d83-ad82-f11efbcb9437', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 9, 9, 'Behold, the day of Yahweh comes, cruel, with wrath and fierce anger; to make the land a desolation, and to destroy its sinners out of it.'),
  ('106a59b5-bab2-5626-a039-e52c8d46926a', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 10, 10, 'For the stars of the sky and its constellations will not give their light. The sun will be darkened in its going forth, and the moon will not cause its light to shine.'),
  ('9fe5f4ad-77db-520a-a5e8-03fe689001d5', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 11, 11, 'I will punish the world for their evil, and the wicked for their iniquity. I will cause the arrogance of the proud to cease, and will humble the haughtiness of the terrible.'),
  ('19e36b11-6f71-5d44-abf4-89e55420f005', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 12, 12, 'I will make people more rare than fine gold, even a person than the pure gold of Ophir.'),
  ('6a1a2ff0-543d-539e-a5f2-a3f5cab9b68a', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 13, 13, 'Therefore I will make the heavens tremble, and the earth will be shaken out of its place in the wrath of Yahweh of Armies, and in the day of his fierce anger.'),
  ('79a76281-0175-57c6-a3d0-5e97122cdfcd', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 14, 14, 'It will happen that like a hunted gazelle, and like sheep that no one gathers, they will each turn to their own people, and will each flee to their own land.'),
  ('cd03c60c-2112-59fa-af48-e6d52fd31d63', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 15, 15, 'Everyone who is found will be thrust through. Everyone who is captured will fall by the sword.'),
  ('c6076aba-61d1-50b7-a22d-b56151f84f14', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 16, 16, 'Their infants also will be dashed in pieces before their eyes. Their houses will be ransacked, and their wives raped.'),
  ('95698e4c-8909-5ba6-a15f-ed3abfdf0bce', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 17, 17, 'Behold, I will stir up the Medes against them, who will not value silver, and as for gold, they will not delight in it.'),
  ('8e5eafe2-8e18-5585-a327-f79d1f0ec3b9', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 18, 18, 'Their bows will dash the young men in pieces; and they shall have no pity on the fruit of the womb. Their eyes will not spare children.'),
  ('8ed1b111-800c-5bee-a7b0-0cbe4591a71a', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 19, 19, 'Babylon, the glory of kingdoms, the beauty of the Chaldeans'' pride, will be like when God overthrew Sodom and Gomorrah.'),
  ('ab7a8d22-0fc8-5984-a37c-ed2e6dcc725a', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 20, 20, 'It will never be inhabited, neither will it be lived in from generation to generation. The Arabian will not pitch a tent there, neither will shepherds make their flocks lie down there.'),
  ('85b946a0-7ea4-5175-aaa0-680cb92350bd', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 21, 21, 'But wild animals of the desert will lie there, and their houses will be full of jackals. Ostriches will dwell there, and wild goats will frolic there.'),
  ('a4be2a1d-04cd-5624-ac9c-6707564cba82', '66a84099-9165-5cd5-af1e-3261a486b1cf', NULL, 22, 22, 'Wolves will cry in their castles, and jackals in the pleasant palaces. Her time is near to come, and her days will not be prolonged.'),
  ('7000ebc8-292a-5db7-a568-8c69c77fc4f5', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 1, 1, 'For Yahweh will have compassion on Jacob, and will yet choose Israel, and set them in their own land. The foreigner will join himself with them, and they will unite with the house of Jacob.'),
  ('2d6e42de-55ee-5925-a426-cfbcf10301e2', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 2, 2, 'The peoples will take them, and bring them to their place. The house of Israel will possess them in Yahweh''s land for servants and for handmaids. They will take as captives those whose captives they were; and they shall rule over their oppressors.'),
  ('93a402c4-27e0-5004-ae3c-5bd56517b512', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 3, 3, 'It will happen in the day that Yahweh will give you rest from your sorrow, from your trouble, and from the hard service in which you were made to serve,'),
  ('2ce1cc23-1daa-57bf-a1ac-0f7677b00a7d', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 4, 4, 'that you will take up this parable against the king of Babylon, and say, "How the oppressor has ceased! The golden city has ceased!"'),
  ('9ddb051c-8ca5-588c-a9a4-7a4b0ebfd00d', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 5, 5, 'Yahweh has broken the staff of the wicked, the scepter of the rulers,'),
  ('38fcab05-1c3f-519c-af41-c4effbef3383', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 6, 6, 'who struck the peoples in wrath with a continual stroke, who ruled the nations in anger, with a persecution that none restrained.'),
  ('10d9cd7d-be49-515b-a0ac-4fc3ce30007a', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 7, 7, 'The whole earth is at rest, and is quiet. They break out song.'),
  ('2c52277e-2a28-523b-a08c-ae0d137cfc16', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 8, 8, 'Yes, the fir trees rejoice with you, with the cedars of Lebanon, saying, "Since you are humbled, no lumberjack has come up against us."'),
  ('da6d9766-3f32-5919-a280-504e0a952629', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 9, 9, 'Sheol from beneath has moved for you to meet you at your coming. It stirs up the dead for you, even all the rulers of the earth. It has raised up from their thrones all the kings of the nations.'),
  ('e445a2a9-5773-5726-a917-d5879e31dab7', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 10, 10, 'They all will answer and ask you, "Have you also become as weak as we are? Have you become like us?"'),
  ('f278ddaa-34a0-5ff2-a803-3698e037bafa', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 11, 11, 'Your pomp is brought down to Sheol, with the sound of your stringed instruments. Maggots are spread out under you, and worms cover you.'),
  ('54aa558f-d5a0-5df2-a1e1-15367b489493', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 12, 12, 'How you have fallen from heaven, morning star, son of the dawn! How you are cut down to the ground, who laid the nations low!'),
  ('adc97d32-31cd-55b6-a453-9156fa95fc29', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 13, 13, 'You said in your heart, "I will ascend into heaven! I will exalt my throne above the stars of God! I will sit on the mountain of assembly, in the far north!'),
  ('a912b72b-0b7d-5d7e-a111-e142dddd29a9', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 14, 14, 'I will ascend above the heights of the clouds! I will make myself like the Most High!"'),
  ('9977c374-0677-51c7-a24d-2c0afa42d57a', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 15, 15, 'Yet you shall be brought down to Sheol, to the depths of the pit.'),
  ('d90d061a-8772-5279-a2fd-50e8f5fdc482', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 16, 16, 'Those who see you will stare at you. They will ponder you, saying, "Is this the man who made the earth to tremble, who shook kingdoms;'),
  ('2f200ae7-aaae-5747-a245-d976094466af', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 17, 17, 'who made the world like a wilderness, and overthrew its cities; who didn''t release his prisoners to their home?"'),
  ('e6144c90-d4de-5712-ab6e-211ee3cc47cc', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 18, 18, 'All the kings of the nations, sleep in glory, everyone in his own house.'),
  ('4988be33-dc3b-5eed-aefa-720f95c417a5', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 19, 19, 'But you are cast away from your tomb like an abominable branch, clothed with the slain, who are thrust through with the sword, who go down to the stones of the pit; like a dead body trodden under foot.'),
  ('63662479-6ff2-564f-a946-7cce94946f5f', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 20, 20, 'You will not join them in burial, because you have destroyed your land. You have killed your people. The seed of evildoers will not be named forever.'),
  ('660b735b-53da-52e9-aaa8-a2ee19661c36', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 21, 21, 'Prepare for slaughter of his children because of the iniquity of their fathers, that they not rise up and possess the earth, and fill the surface of the world with cities.'),
  ('9b77c88f-212d-520b-aaad-a2d1ea2d71a2', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 22, 22, '"I will rise up against them," says Yahweh of Armies, "and cut off from Babylon name and remnant, and son and son''s son," says Yahweh.'),
  ('fc32a491-952d-523b-af15-9cbdbe07761d', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 23, 23, '"I will also make it a possession for the porcupine, and pools of water. I will sweep it with the broom of destruction," says Yahweh of Armies.'),
  ('7d840fb4-be4c-55ee-add3-60b0a872975d', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 24, 24, 'Yahweh of Armies has sworn, saying, "Surely, as I have thought, so shall it happen; and as I have purposed, so shall it stand:'),
  ('b0c0d1b9-0f23-57c3-a8f5-b7cd8d67f8ba', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 25, 25, 'that I will break the Assyrian in my land, and tread him under foot on my mountains. Then his yoke will leave them, and his burden leave their shoulders.'),
  ('6b50c1d7-4bbc-5869-aaaa-4dab019116bd', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 26, 26, 'This is the plan that is determined for the whole earth. This is the hand that is stretched out over all the nations.'),
  ('6b787928-5166-56a7-a4a2-9baa56718eaa', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 27, 27, 'For Yahweh of Armies has planned, and who can stop it? His hand is stretched out, and who can turn it back?"'),
  ('bf0981d7-d509-559d-a56e-9df754277263', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 28, 28, 'This burden was in the year that king Ahaz died.'),
  ('d9dca313-de30-5bf7-ae3b-8c187f8db66b', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 29, 29, 'Don''t rejoice, O Philistia, all of you, because the rod that struck you is broken; for out of the serpent''s root an adder will emerge, and his fruit will be a fiery flying serpent.'),
  ('c1bcbed0-6a64-5242-af85-3eeae3ce2bc9', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 30, 30, 'The firstborn of the poor will eat, and the needy will lie down in safety; and I will kill your root with famine, and your remnant will be killed.'),
  ('887bc079-8b7c-5104-aa05-ef6ec5b8c491', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 31, 31, 'Howl, gate! Cry, city! You are melted away, Philistia, all of you; for smoke comes out of the north, and there is no straggler in his ranks.'),
  ('6e7bc788-b2c7-59ac-a5bd-bf7d92603955', '3e334ea3-2b28-5275-ad1e-0038968f0f5e', NULL, 32, 32, 'What will they answer the messengers of the nation? That Yahweh has founded Zion, and in her the afflicted of his people will take refuge.'),
  ('f4b7300c-f9c6-543a-a856-33b47e027bbd', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 1, 1, 'The burden of Moab: for in a night, Ar of Moab is laid waste, and brought to nothing; for in a night Kir of Moab is laid waste, and brought to nothing.'),
  ('8fa8275b-ef4c-573e-a032-460193ad5c7a', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 2, 2, 'They have gone up to Bayith, and to Dibon, to the high places, to weep. Moab wails over Nebo and over Medeba. Baldness is on all of their heads. Every beard is cut off.'),
  ('1fd2e8b3-9ee2-5686-a548-f9e44bec93bc', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 3, 3, 'In their streets, they clothe themselves in sackcloth. In their streets and on their housetops, everyone wails, weeping abundantly.'),
  ('bafa95cb-da4d-528e-a80c-95f8ee0d4743', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 4, 4, 'Heshbon cries out with Elealeh. Their voice is heard even to Jahaz. Therefore the armed men of Moab cry aloud. Their souls tremble within them.'),
  ('a5013415-c8b3-5551-acee-04911fd54b47', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 5, 5, 'My heart cries out for Moab! Her nobles flee to Zoar, to Eglath Shelishiyah; for they go up by the ascent of Luhith with weeping; for in the way of Horonaim, they raise up a cry of destruction.'),
  ('387d0615-364a-52fd-afb2-61fa35590bd2', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 6, 6, 'For the waters of Nimrim will be desolate; for the grass has withered away, the tender grass fails, there is no green thing.'),
  ('1ac36ff3-0dd3-5513-a4a9-030ad4cf5412', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 7, 7, 'Therefore they will carry away the abundance they have gotten, and that which they have stored up, over the brook of the willows.'),
  ('e3c273c8-0c75-5ef5-a74b-3c2957a5ad42', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 8, 8, 'For the cry has gone around the borders of Moab; its wailing to Eglaim, and its wailing to Beer Elim.'),
  ('31b44923-af59-5ea0-adf5-b82ebbfc0905', 'a99bebc1-51f2-57f0-a9eb-ba711120e533', NULL, 9, 9, 'For the waters of Dimon are full of blood; for I will bring yet more on Dimon, a lion on those of Moab who escape, and on the remnant of the land.'),
  ('18309177-2e6c-55d4-a14b-8089e97ed815', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 1, 1, 'Send the lambs for the ruler of the land from Selah to the wilderness, to the mountain of the daughter of Zion.'),
  ('333320f1-254e-5449-a135-58350409f86f', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 2, 2, 'For it will be that as wandering birds, as a scattered nest, so will the daughters of Moab be at the fords of the Arnon.'),
  ('795587f1-e437-5a46-a924-ace4e91e4feb', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 3, 3, 'Give counsel! Execute justice! Make your shade like the night in the midst of the noonday! Hide the outcasts! Don''t betray the fugitive!'),
  ('64470e68-0e7f-5a08-a780-ee0910a1fb9e', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 4, 4, 'Let my outcasts dwell with you! As for Moab, be a hiding place for him from the face of the destroyer. For the extortioner is brought to nothing. Destruction ceases. The oppressors are consumed out of the land.'),
  ('6ffdfdc7-577e-5224-a66a-8443f5d45a35', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 5, 5, 'A throne will be established in loving kindness. One will sit on it in truth, in the tent of David, judging, seeking justice, and swift to do righteousness.'),
  ('f8e650bc-9980-5cd9-aa9c-f4b9dddd1c6d', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 6, 6, 'We have heard of the pride of Moab, that he is very proud; even of his arrogance, his pride, and his wrath. His boastings are nothing.'),
  ('51e5fcb3-d82c-5fd5-ad92-980580f51894', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 7, 7, 'Therefore Moab will wail for Moab. Everyone will wail. You will mourn for the raisin cakes of Kir Hareseth, utterly stricken.'),
  ('5875f4d4-03a8-54ab-a83d-5044915a916a', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 8, 8, 'For the fields of Heshbon languish with the vine of Sibmah. The lords of the nations have broken down its choice branches, which reached even to Jazer, which wandered into the wilderness. Its shoots were spread abroad. They passed over the sea.'),
  ('4fff285e-4d92-528f-ad0a-433d6947be70', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 9, 9, 'Therefore I will weep with the weeping of Jazer for the vine of Sibmah. I will water you with my tears, Heshbon, and Elealeh: for on your summer fruits and on your harvest the battle shout has fallen.'),
  ('21fa8f03-1e3a-5422-a163-3a4ee37e312c', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 10, 10, 'Gladness is taken away, and joy out of the fruitful field; and in the vineyards there will be no singing, neither joyful noise. Nobody will tread out wine in the presses. I have made the shouting stop.'),
  ('426a5c22-481b-5c85-a378-47605f18a3f5', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 11, 11, 'Therefore my heart sounds like a harp for Moab, and my inward parts for Kir Heres.'),
  ('e09a12bb-5071-543c-ab70-74db260eacbe', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 12, 12, 'It will happen that when Moab presents himself, when he wearies himself on the high place, and comes to his sanctuary to pray, that he will not prevail.'),
  ('80c72fc9-2849-587b-a8e2-fcfb2d8a0ab5', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 13, 13, 'This is the word that Yahweh spoke concerning Moab in time past.'),
  ('11048b98-1f4e-5faa-af89-1153a01e8bd5', '2ac5b6eb-d6a5-5401-ac48-792d648151f4', NULL, 14, 14, 'But now Yahweh has spoken, saying, "Within three years, as a worker bound by contract would count them, the glory of Moab shall be brought into contempt, with all his great multitude; and the remnant will be very small and feeble."'),
  ('9524d201-fc5a-59e7-a2fb-4d1f0c17a59f', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 1, 1, 'The burden of Damascus: "Behold, Damascus is taken away from being a city, and it will be a ruinous heap.'),
  ('b4bcde7f-9615-563d-a011-ba0ac646750f', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 2, 2, 'The cities of Aroer are forsaken. They will be for flocks, which shall lie down, and none shall make them afraid.'),
  ('0954c3f4-45c0-539d-a9fb-1b57ca544bd3', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 3, 3, 'The fortress shall cease from Ephraim, and the kingdom from Damascus, and the remnant of Syria. They will be as the glory of the children of Israel," says Yahweh of Armies.'),
  ('9c568d90-e054-5593-a0ed-e8357bc0589b', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 4, 4, '"It will happen in that day that the glory of Jacob will be made thin, and the fatness of his flesh will become lean.'),
  ('2555a860-285b-5ede-a1c3-86cb0e8a98b7', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 5, 5, 'It will be like when the harvester gathers the wheat, and his arm reaps the grain. Yes, it will be like when one gleans grain in the valley of Rephaim.'),
  ('b9649efa-ca19-5103-ae29-b1e6cbb6d0a7', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 6, 6, 'Yet gleanings will be left there, like the shaking of an olive tree, two or three olives in the top of the uppermost bough, four or five in the outermost branches of a fruitful tree," says Yahweh, the God of Israel.'),
  ('e630c7ac-550c-53ff-a3b0-6e21236e26e9', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 7, 7, 'In that day, people will look to their Maker, and their eyes will have respect for the Holy One of Israel.'),
  ('090dccc9-c855-5919-a0b2-7dde3ae62fe8', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 8, 8, 'They will not look to the altars, the work of their hands; neither shall they respect that which their fingers have made, either the Asherim, or the incense altars.'),
  ('93c03378-b340-519a-a8e5-e213da81499a', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 9, 9, 'In that day, their strong cities will be like the forsaken places in the woods and on the mountain top, which were forsaken from before the children of Israel; and it will be a desolation.'),
  ('37f1b7fe-2fac-5f0d-a68a-4ea6d9630816', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 10, 10, 'For you have forgotten the God of your salvation, and have not remembered the rock of your strength. Therefore you plant pleasant plants, and set out foreign seedlings.'),
  ('930b3266-4d41-50ea-a65c-bc94ab914e3a', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 11, 11, 'In the day of your planting, you hedge it in. In the morning, you make your seed blossom, but the harvest flees away in the day of grief and of desperate sorrow.'),
  ('dac1a597-2881-5bc6-a199-36da23604f44', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 12, 12, 'Ah, the uproar of many peoples, who roar like the roaring of the seas; and the rushing of nations, that rush like the rushing of mighty waters!'),
  ('7ad6c333-2606-5534-a9bc-3ecb96220f50', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 13, 13, 'The nations will rush like the rushing of many waters: but he will rebuke them, and they will flee far off, and will be chased like the chaff of the mountains before the wind, and like the whirling dust before the storm.'),
  ('ab41ab4d-88d1-5f3a-ad91-c75cf7c592b6', '18a32f5b-a161-528f-ac67-ec1f65349b8c', NULL, 14, 14, 'At evening, behold, terror! Before the morning, they are no more. This is the portion of those who plunder us, and the lot of those who rob us.'),
  ('5e1bbef0-b9e6-5668-aeb8-0bcdec9d1e4e', 'ba31321b-0f7d-5e90-a111-6161fc044d78', NULL, 1, 1, 'Ah, the land of the rustling of wings, which is beyond the rivers of Ethiopia;'),
  ('1ccc4b91-93ce-553a-a6f8-ef17c79502d4', 'ba31321b-0f7d-5e90-a111-6161fc044d78', NULL, 2, 2, 'that sends ambassadors by the sea, even in vessels of papyrus on the waters, saying, "Go, you swift messengers, to a nation tall and smooth, to a people awesome from their beginning onward, a nation that measures out and treads down, whose land the rivers divide!"'),
  ('a5f00873-59d9-5b01-a63a-14a35626af83', 'ba31321b-0f7d-5e90-a111-6161fc044d78', NULL, 3, 3, 'All you inhabitants of the world, and you dwellers on the earth, when a banner is lifted up on the mountains, look! When the trumpet is blown, listen!'),
  ('ed0394c4-aa42-5469-ae40-7a06d233f94b', 'ba31321b-0f7d-5e90-a111-6161fc044d78', NULL, 4, 4, 'For Yahweh said to me, "I will be still, and I will see in my dwelling place, like clear heat in sunshine, like a cloud of dew in the heat of harvest."'),
  ('60f8046b-de95-5a41-a05d-37849ea3efc8', 'ba31321b-0f7d-5e90-a111-6161fc044d78', NULL, 5, 5, 'For before the harvest, when the blossom is over, and the flower becomes a ripening grape, he will cut off the sprigs with pruning hooks, and he will cut down and take away the spreading branches.'),
  ('a3e2708b-dfd5-5dd6-afb7-88f22d97dc68', 'ba31321b-0f7d-5e90-a111-6161fc044d78', NULL, 6, 6, 'They will be left together for the ravenous birds of the mountains, and for the animals of the earth. The ravenous birds will summer on them, and all the animals of the earth will winter on them.'),
  ('79885053-b09c-51d3-aeef-9ddaa6eaca02', 'ba31321b-0f7d-5e90-a111-6161fc044d78', NULL, 7, 7, 'In that time, a present will be brought to Yahweh of Armies from a people tall and smooth, even from a people awesome from their beginning onward, a nation that measures out and treads down, whose land the rivers divide, to the place of the name of Yahweh of Armies, Mount Zion.'),
  ('ef0f473f-d36e-52e8-a998-17781ce991e2', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 1, 1, 'The burden of Egypt: "Behold, Yahweh rides on a swift cloud, and comes to Egypt. The idols of Egypt will tremble at his presence; and the heart of Egypt will melt in its midst.'),
  ('4fa008bb-32e7-5f97-a513-8a87c57a3d1e', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 2, 2, 'I will stir up the Egyptians against the Egyptians, and they will fight everyone against his brother, and everyone against his neighbor; city against city, and kingdom against kingdom.'),
  ('583bacdb-d960-5fb5-a506-4d86780e9c75', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 3, 3, 'The spirit of Egypt will fail in its midst. I will destroy its counsel. They will seek the idols, the charmers, those who have familiar spirits, and the wizards.'),
  ('5e580a18-396a-5b5e-ae6e-e9ab30d082a0', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 4, 4, 'I will give over the Egyptians into the hand of a cruel lord. A fierce king will rule over them," says the Lord, Yahweh of Armies.'),
  ('b4dbc685-ab85-5ae4-a8b2-c87faca384cb', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 5, 5, 'The waters will fail from the sea, and the river will be wasted and become dry.'),
  ('4faf29e4-758f-51ab-a0c6-37910507a56b', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 6, 6, 'The rivers will become foul. The streams of Egypt will be diminished and dried up. The reeds and flags will wither away.'),
  ('55718759-227c-56a1-a235-680dc0820325', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 7, 7, 'The meadows by the Nile, by the brink of the Nile, and all the sown fields of the Nile, will become dry, be driven away, and be no more.'),
  ('05e057b7-e9a4-599c-a632-c3d12f302ba2', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 8, 8, 'The fishermen will lament, and all those who fish in the Nile will mourn, and those who spread nets on the waters will languish.'),
  ('6bb78e85-cea8-5870-adf7-1aa51e926047', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 9, 9, 'Moreover those who work in combed flax, and those who weave white cloth, will be confounded.'),
  ('e9374a14-03fa-5970-a0f9-58123c6029e1', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 10, 10, 'The pillars will be broken in pieces. All those who work for hire will be grieved in soul.'),
  ('ae5c40ba-3383-57c7-ad29-44772f001798', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 11, 11, 'The princes of Zoan are utterly foolish. The counsel of the wisest counselors of Pharaoh has become stupid. How do you say to Pharaoh, "I am the son of the wise, the son of ancient kings?"'),
  ('ca03835a-b6d3-5148-a040-0513112c36a5', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 12, 12, 'Where then are your wise men? Let them tell you now; and let them know what Yahweh of Armies has purposed concerning Egypt.'),
  ('d8db9e6e-f4a5-5418-af49-550ca5d0aca7', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 13, 13, 'The princes of Zoan have become fools. The princes of Memphis are deceived. They have caused Egypt to go astray, who are the cornerstone of her tribes.'),
  ('4dcbf0b7-fbc3-51c1-af20-74f17d405a73', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 14, 14, 'Yahweh has mixed a spirit of perverseness in the midst of her; and they have caused Egypt to go astray in all of its works, like a drunken man staggers in his vomit.'),
  ('9a4bc6a6-918d-5c19-a58b-c8577df127e3', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 15, 15, 'Neither shall there be for Egypt any work, which head or tail, palm branch or rush, may do.'),
  ('9975da13-6e33-5af3-a4d9-c0a3555c6486', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 16, 16, 'In that day the Egyptians will be like women. They will tremble and fear because of the shaking of the hand of Yahweh of Armies, which he shakes over them.'),
  ('c8304cec-29b1-5db7-adb9-ea27eb406c69', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 17, 17, 'The land of Judah will become a terror to Egypt. Everyone to whom mention is made of it will be afraid, because of the plans of Yahweh of Armies, which he determines against it.'),
  ('9e9c4d2d-ffac-59e7-a014-41684050e1a1', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 18, 18, 'In that day, there will be five cities in the land of Egypt that speak the language of Canaan, and swear to Yahweh of Armies. One will be called "The city of destruction."'),
  ('ae22de51-ad18-5c71-aa41-dffbfe1ee894', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 19, 19, 'In that day, there will be an altar to Yahweh in the midst of the land of Egypt, and a pillar to Yahweh at its border.'),
  ('3f95f181-cda8-5e8a-a8b0-51465b05cc9d', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 20, 20, 'It will be for a sign and for a witness to Yahweh of Armies in the land of Egypt; for they will cry to Yahweh because of oppressors, and he will send them a savior and a defender, and he will deliver them.'),
  ('3ef94744-13f6-5426-a2fe-12881ee8537a', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 21, 21, 'Yahweh will be known to Egypt, and the Egyptians will know Yahweh in that day. Yes, they will worship with sacrifice and offering, and will vow a vow to Yahweh, and will perform it.'),
  ('cc73371d-ffff-5369-a94f-2a5cea4039dc', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 22, 22, 'Yahweh will strike Egypt, striking and healing. They will return to Yahweh, and he will be entreated by them, and will heal them.'),
  ('c6715d75-f8c9-5319-a6ad-a7260394d150', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 23, 23, 'In that day there will be a highway out of Egypt to Assyria, and the Assyrian shall come into Egypt, and the Egyptian into Assyria; and the Egyptians will worship with the Assyrians.'),
  ('357265fe-424e-5f06-a323-f485d35be13e', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 24, 24, 'In that day, Israel will be the third with Egypt and with Assyria, a blessing in the midst of the earth;'),
  ('51367e3d-7017-51b5-ae6c-a39a37f37105', '339a43ef-b3e3-5f18-a482-54a9c3351b5a', NULL, 25, 25, 'because Yahweh of Armies has blessed them, saying, "Blessed be Egypt my people, Assyria the work of my hands, and Israel my inheritance."'),
  ('98a98c0e-6a76-58ea-ab11-1f7ca2b4a6ba', 'dbde6eaa-c6fd-540c-af87-a083e48aac52', NULL, 1, 1, 'In the year that Tartan came to Ashdod, when Sargon the king of Assyria sent him, and he fought against Ashdod and took it;'),
  ('a486e8fe-68ca-503f-a2bf-356e105dafb5', 'dbde6eaa-c6fd-540c-af87-a083e48aac52', NULL, 2, 2, 'at that time Yahweh spoke by Isaiah the son of Amoz, saying, "Go, and loosen the sackcloth from off your waist, and take your shoes from off your feet." He did so, walking naked and barefoot.'),
  ('21272c99-98ec-5c4f-a554-1db28a665372', 'dbde6eaa-c6fd-540c-af87-a083e48aac52', NULL, 3, 3, 'Yahweh said, "As my servant Isaiah has walked naked and barefoot three years for a sign and a wonder concerning Egypt and concerning Ethiopia,'),
  ('5b61f761-ea8a-51d4-a764-1fa425d3a417', 'dbde6eaa-c6fd-540c-af87-a083e48aac52', NULL, 4, 4, 'so the king of Assyria will lead away the captives of Egypt and the exiles of Ethiopia, young and old, naked and barefoot, and with buttocks uncovered, to the shame of Egypt.'),
  ('48ad12ab-09ec-5b81-a76b-defdbdc4fa96', 'dbde6eaa-c6fd-540c-af87-a083e48aac52', NULL, 5, 5, 'They will be dismayed and confounded, because of Ethiopia their expectation, and of Egypt their glory.'),
  ('ae04453a-36ce-5e1a-a14e-3837eb94c2da', 'dbde6eaa-c6fd-540c-af87-a083e48aac52', NULL, 6, 6, 'The inhabitants of this coast land will say in that day, ''Behold, this is our expectation, where we fled for help to be delivered from the king of Assyria. And we, how will we escape?''"'),
  ('3b6ac243-65d0-56f8-a7e6-d646ce52ee0d', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 1, 1, 'The burden of the wilderness of the sea. As whirlwinds in the South sweep through, it comes from the wilderness, from an awesome land.'),
  ('049616e2-e1a3-564d-a818-4f5f68592b4c', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 2, 2, 'A grievous vision is declared to me. The treacherous man deals treacherously, and the destroyer destroys. Go up, Elam; attack! I have stopped all of Media''s sighing.'),
  ('74dd908f-73f8-5927-a10b-af80fb4a0f54', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 3, 3, 'Therefore my thighs are filled with anguish. Pains have taken hold on me, like the pains of a woman in labor. I am in so much pain that I can''t hear. I so am dismayed that I can''t see.'),
  ('66a2576b-cad5-5730-a885-f5d06314bd80', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 4, 4, 'My heart flutters. Horror has frightened me. The twilight that I desired has been turned into trembling for me.'),
  ('fc2df90f-2e1d-534d-a34f-618e44e4b227', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 5, 5, 'They prepare the table. They set the watch. They eat. They drink. Rise up, you princes, oil the shield!'),
  ('e3c7f018-68b5-52a5-aee5-cdd2dc9c4376', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 6, 6, 'For the Lord said to me, "Go, set a watchman. Let him declare what he sees.'),
  ('329964e8-96f2-5131-a9c9-06dc0d3047f5', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 7, 7, 'When he sees a troop, horsemen in pairs, a troop of donkeys, a troop of camels, he shall listen diligently with great attentiveness."'),
  ('ec9ff43b-e526-5988-a6a6-0685a04592a4', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 8, 8, 'He cried like a lion: "Lord, I stand continually on the watchtower in the daytime, and every night I stay at my post.'),
  ('8b99d4fb-85a0-5316-a038-395f56925820', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 9, 9, 'Behold, here comes a troop of men, horsemen in pairs." He answered, "Fallen, fallen is Babylon; and all the engraved images of her gods are broken to the ground.'),
  ('03d61140-6e64-5a92-a79c-1e0d9d30c0dd', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 10, 10, 'You are my threshing, and the grain of my floor!" That which I have heard from Yahweh of Armies, the God of Israel, I have declared to you.'),
  ('d71ad3a2-851d-5a09-aa11-932939bb587d', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 11, 11, 'The burden of Dumah. One calls to me out of Seir, "Watchman, what of the night? Watchman, what of the night?"'),
  ('a908856b-a831-5a40-a794-d3b4116f5e8d', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 12, 12, 'The watchman said, "The morning comes, and also the night. If you will inquire, inquire. Come back again."'),
  ('8f0eb376-1a4e-550b-a331-b407488d0405', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 13, 13, 'The burden on Arabia. In the forest in Arabia you will lodge, you caravans of Dedanites.'),
  ('690ff9de-8d00-553a-a196-cf2cf2d02dcc', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 14, 14, 'They brought water to him who was thirsty. The inhabitants of the land of Tema met the fugitives with their bread.'),
  ('220ae706-1bfa-5e37-a1aa-3062b855022f', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 15, 15, 'For they fled away from the swords, from the drawn sword, from the bent bow, and from the heat of battle.'),
  ('f2810253-2374-5a41-ab10-9cfd63de1679', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 16, 16, 'For the Lord said to me, "Within a year, as a worker bound by contract would count it, all the glory of Kedar will fail,'),
  ('2aa0451b-7ed5-5a80-a37c-96c917b0a0fe', '79ed544f-b7af-5b59-a337-ea65805f9492', NULL, 17, 17, 'and the residue of the number of the archers, the mighty men of the children of Kedar, will be few; for Yahweh, the God of Israel, has spoken it."'),
  ('5f56d6e4-3f06-5543-aeed-76b2ab6c130a', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 1, 1, 'The burden of the valley of vision. What ails you now, that you have all gone up to the housetops?'),
  ('e337d061-1999-5258-a490-6bb9c063b2b9', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 2, 2, 'You that are full of shouting, a tumultuous city, a joyous town; your slain are not slain with the sword, neither are they dead in battle.'),
  ('0f11608a-bb7b-5d41-ae38-5a4a9f20bc20', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 3, 3, 'All your rulers fled away together. They were bound by the archers. All who were found by you were bound together. They fled far away.'),
  ('94b5857d-c23c-5e33-ab80-aca87140cde8', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 4, 4, 'Therefore I said, "Look away from me. I will weep bitterly. Don''t labor to comfort me for the destruction of the daughter of my people.'),
  ('1af465cb-fe3e-5c98-af88-6b0358d40264', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 5, 5, 'For it is a day of confusion, and of treading down, and of perplexity, from the Lord, Yahweh of Armies, in the valley of vision; a breaking down of the walls, and a crying to the mountains."'),
  ('0f74d2c5-3272-583e-a9b7-16db1bd3531f', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 6, 6, 'Elam carried his quiver, with chariots of men and horsemen; and Kir uncovered the shield.'),
  ('028f5793-f6d7-5e08-ac2b-95a1b48d88d2', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 7, 7, 'It happened that your choicest valleys were full of chariots, and the horsemen set themselves in array at the gate.'),
  ('5013651f-a42e-55c9-a7dd-b336c2439e86', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 8, 8, 'He took away the covering of Judah; and you looked in that day to the armor in the house of the forest.'),
  ('0f3a1294-311c-52c5-a069-17c011b55439', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 9, 9, 'You saw the breaches of the city of David, that they were many; and you gathered together the waters of the lower pool.'),
  ('413d758c-564b-5c7d-a8ea-1ae6f98dadf0', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 10, 10, 'You numbered the houses of Jerusalem, and you broke down the houses to fortify the wall.'),
  ('fff03db2-579b-547b-ae30-12796d777e2c', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 11, 11, 'You also made a reservoir between the two walls for the water of the old pool. But you didn''t look to him who had done this, neither did you have respect for him who purposed it long ago.'),
  ('683a5ed2-2b10-549a-ad2f-2d1f67523ad8', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 12, 12, 'In that day, the Lord, Yahweh of Armies, called to weeping, and to mourning, and to baldness, and to dressing in sackcloth:'),
  ('5d05f931-e1fe-5f2a-a7fd-cabb03c33bf7', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 13, 13, 'and behold, joy and gladness, killing cattle and killing sheep, eating flesh and drinking wine: "Let us eat and drink, for tomorrow we will die."'),
  ('9059c76e-a408-567c-a2e7-9ed22b6413f0', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 14, 14, 'Yahweh of Armies revealed himself in my ears, "Surely this iniquity will not be forgiven you until you die," says the Lord, Yahweh of Armies.'),
  ('f591a94f-39b8-5d6e-aa95-44655a5bc656', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 15, 15, 'Thus says the Lord, Yahweh of Armies, "Go, get yourself to this treasurer, even to Shebna, who is over the house, and say,'),
  ('3639a45a-4b3a-5979-a638-c98774a44406', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 16, 16, '''What are you doing here? Who has you here, that you have dug out a tomb here?'' Cutting himself out a tomb on high, chiseling a habitation for himself in the rock!"'),
  ('98db00f5-0bc1-59c1-ac7b-aff253c8428e', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 17, 17, 'Behold, Yahweh will overcome you and hurl you away violently. Yes, he will grasp you firmly.'),
  ('173f031a-f668-5870-a599-880e4b758915', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 18, 18, 'He will surely wind you around and around, and throw you like a ball into a large country. There you will die, and there the chariots of your glory will be, you shame of your lord''s house.'),
  ('3e8bd77d-581b-500b-ac50-852ac2cda793', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 19, 19, 'I will thrust you from your office. You will be pulled down from your station.'),
  ('5b2e0e56-3f53-5185-a267-e9c64da51323', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 20, 20, 'It will happen in that day that I will call my servant Eliakim the son of Hilkiah,'),
  ('85331f66-a236-503c-a1d6-7646d4ece617', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 21, 21, 'and I will clothe him with your robe, and strengthen him with your belt. I will commit your government into his hand; and he will be a father to the inhabitants of Jerusalem, and to the house of Judah.'),
  ('22f497aa-0653-555c-af4e-f911455a3e90', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 22, 22, 'I will lay the key of the house of David on his shoulder. He will open, and no one will shut. He will shut, and no one will open.'),
  ('1093d13e-a603-5ec8-ab50-584cf2a0b1e9', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 23, 23, 'I will fasten him like a nail in a sure place. He will be for a throne of glory to his father''s house.'),
  ('9050fe39-557b-57b3-af02-22dabed29748', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 24, 24, 'They will hang on him all the glory of his father''s house, the offspring and the issue, every small vessel, from the cups even to all the pitchers.'),
  ('f8d5a360-39b8-5a78-a344-db39a6b1d8b8', 'b29a4c90-f48c-5660-acae-907252a49e9a', NULL, 25, 25, '"In that day," says Yahweh of Armies, "the nail that was fastened in a sure place will give way. It will be cut down, and fall. The burden that was on it will be cut off, for Yahweh has spoken it."'),
  ('0c722c74-f6a1-52b3-a0ef-ab0d0a9d4c9d', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 1, 1, 'The burden of Tyre. Howl, you ships of Tarshish! For it is laid waste, so that there is no house, no entering in. From the land of Kittim it is revealed to them.'),
  ('ee6315fc-cadb-5868-a243-9bd2c79b24ac', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 2, 2, 'Be still, you inhabitants of the coast, you whom the merchants of Sidon, that pass over the sea, have replenished.'),
  ('c75b9c14-93ab-5243-a14b-72640b2bb574', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 3, 3, 'On great waters, the seed of the Shihor, the harvest of the Nile, was her revenue. She was the market of nations.'),
  ('23fa0112-47ac-5564-a778-142ce3d287ab', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 4, 4, 'Be ashamed, Sidon; for the sea has spoken, the stronghold of the sea, saying, "I have not travailed, nor brought forth, neither have I nourished young men, nor brought up virgins."'),
  ('ee9d17f1-3352-5095-a223-4ba5dfdd7524', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 5, 5, 'When the report comes to Egypt, they will be in anguish at the report of Tyre.'),
  ('52fc84bd-067c-5689-afd2-4ae72d55cbd0', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 6, 6, 'Pass over to Tarshish! Wail, you inhabitants of the coast!'),
  ('cef0445b-b6f2-5ca0-a22e-943ce59d2d9b', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 7, 7, 'Is this your joyous city, whose antiquity is of ancient days, whose feet carried her far away to travel?'),
  ('011ea0dd-fc1d-5253-a21d-d1c9dbcb5a98', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 8, 8, 'Who has planned this against Tyre, the giver of crowns, whose merchants are princes, whose traffickers are the honorable of the earth?'),
  ('213b5ee3-8f49-5801-a515-579d52e0130f', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 9, 9, 'Yahweh of Armies has planned it, to stain the pride of all glory, to bring into contempt all the honorable of the earth.'),
  ('e86ecd3b-fade-52fb-a7fb-6b38c8cf3f30', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 10, 10, 'Pass through your land like the Nile, daughter of Tarshish. There is no restraint any more.'),
  ('f99987b8-f70a-5720-a244-d8eb8769e1d7', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 11, 11, 'He has stretched out his hand over the sea. He has shaken the kingdoms. Yahweh has ordered the destruction of Canaan''s strongholds.'),
  ('6c12c565-f8af-5250-a2c0-ba31daa704c1', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 12, 12, 'He said, "You shall rejoice no more, you oppressed virgin daughter of Sidon. Arise, pass over to Kittim. Even there you will have no rest."'),
  ('a493874b-71d1-5f66-ab91-871ee383c9f3', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 13, 13, 'Behold, the land of the Chaldeans. This people was not. The Assyrians founded it for those who dwell in the wilderness. They set up their towers. They overthrew its palaces. They made it a ruin.'),
  ('baab7844-2583-5d69-af50-0ab03f8321e0', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 14, 14, 'Howl, you ships of Tarshish, for your stronghold is laid waste!'),
  ('c87ebb75-4fe7-5e98-a190-bc076f485d0b', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 15, 15, 'It will come to pass in that day that Tyre will be forgotten seventy years, according to the days of one king. After the end of seventy years it will be to Tyre like in the song of the prostitute.'),
  ('38e6e1c7-aaee-5a1a-a010-13395da103db', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 16, 16, 'Take a harp; go about the city, you prostitute that has been forgotten. Make sweet melody. Sing many songs, that you may be remembered.'),
  ('52f6b752-8101-5c41-a469-f465c44e7c3a', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 17, 17, 'It will happen after the end of seventy years that Yahweh will visit Tyre, and she shall return to her wages, and will play the prostitute with all the kingdoms of the world on the surface of the earth.'),
  ('4ec065f4-b49f-5605-a232-75709e97fab0', 'a3e9635c-8814-5d4a-a1dc-d738bcdd9c8f', NULL, 18, 18, 'Her merchandise and her wages will be holiness to Yahweh. It will not be treasured nor laid up; for her merchandise will be for those who dwell before Yahweh, to eat sufficiently, and for durable clothing.'),
  ('b4201ba2-b490-570e-a49b-fb0bf1c8e141', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 1, 1, 'Behold, Yahweh makes the earth empty, makes it waste, turns it upside down, and scatters its inhabitants.'),
  ('dda41952-72d5-5cb3-ade8-e11f1fbb5c60', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 2, 2, 'It will be as with the people, so with the priest; as with the servant, so with his master; as with the maid, so with her mistress; as with the buyer, so with the seller; as with the creditor, so with the debtor; as with the taker of interest, so with the giver of interest.'),
  ('89459092-ef69-54b4-a3fd-e10ba2c65f04', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 3, 3, 'The earth will be utterly emptied and utterly laid waste; for Yahweh has spoken this word.'),
  ('ecf1a985-5242-5268-ae7c-58092192e131', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 4, 4, 'The earth mourns and fades away. The world languishes and fades away. The lofty people of the earth languish.'),
  ('8b57e2dc-e851-5ad0-a433-7e8dc8d500b9', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 5, 5, 'The earth also is polluted under its inhabitants, because they have transgressed the laws, violated the statutes, and broken the everlasting covenant.'),
  ('c13d4d9f-db73-5696-a9ac-8bae5ff7d092', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 6, 6, 'Therefore the curse has devoured the earth, and those who dwell therein are found guilty. Therefore the inhabitants of the earth are burned, and few men left.'),
  ('c954db0e-6c0c-582d-a429-4dece785b80b', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 7, 7, 'The new wine mourns. The vine languishes. All the merry-hearted sigh.'),
  ('767ec4a2-53db-5f1e-ab22-0fdb30f9563e', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 8, 8, 'The mirth of tambourines ceases. The sound of those who rejoice ends. The joy of the harp ceases.'),
  ('5fd73ba2-e281-5c6e-aadc-89b97c9505bc', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 9, 9, 'They will not drink wine with a song. Strong drink will be bitter to those who drink it.'),
  ('12b323f9-311f-53d8-ae8d-a38d381341a6', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 10, 10, 'The confused city is broken down. Every house is shut up, that no man may come in.'),
  ('e1e8f742-35f9-5f15-a6fd-3c7c0842341a', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 11, 11, 'There is a crying in the streets because of the wine. All joy is darkened. The mirth of the land is gone.'),
  ('9d64cb57-c15b-523c-a03e-9d61e6388365', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 12, 12, 'The city is left in desolation, and the gate is struck with destruction.'),
  ('ce1248a3-d951-5fc8-a178-0c6e196dd62c', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 13, 13, 'For it will be so in the midst of the earth among the peoples, as the shaking of an olive tree, as the gleanings when the vintage is done.'),
  ('916d52c6-8dc4-5ff8-a44e-a4cb6af79c69', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 14, 14, 'These shall lift up their voice. They will shout for the majesty of Yahweh. They cry aloud from the sea.'),
  ('f30ae7bb-e273-5f5a-a0bc-cd093e6ee429', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 15, 15, 'Therefore glorify Yahweh in the east, even the name of Yahweh, the God of Israel, in the islands of the sea!')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('5564a5d4-1485-538f-a0e6-359acd77fbb3', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 16, 16, 'From the uttermost part of the earth have we heard songs. Glory to the righteous! But I said, "I pine away! I pine away! woe is me!" The treacherous have dealt treacherously. Yes, the treacherous have dealt very treacherously.'),
  ('0323d16f-7dd7-57f0-adac-129ee389e583', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 17, 17, 'Fear, the pit, and the snare, are on you who inhabitant the earth.'),
  ('7b2bb9b1-5a32-5b39-ae96-61613cd342ba', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 18, 18, 'It will happen that he who flees from the noise of the fear will fall into the pit; and he who comes up out of the midst of the pit will be taken in the snare; for the windows on high are opened, and the foundations of the earth tremble.'),
  ('46db6699-40a3-5b81-a425-a605c32aa4eb', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 19, 19, 'The earth is utterly broken. The earth is torn apart. The earth is shaken violently.'),
  ('6f14f74e-e554-54f5-a822-e9e7b9a37355', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 20, 20, 'The earth will stagger like a drunken man, and will sway back and forth like a hammock. Its disobedience will be heavy on it, and it will fall and not rise again.'),
  ('da99371b-1290-5104-a980-de4c53654799', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 21, 21, 'It shall happen in that day that Yahweh will punish the army of the high ones on high, and the kings of the earth on the earth.'),
  ('9c5c6546-c3c2-5759-adb7-512612dc3346', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 22, 22, 'They shall be gathered together, as prisoners are gathered in the pit, and shall be shut up in the prison; and after many days shall they be visited.'),
  ('719b655d-31d9-5574-ad00-854c4da56b24', 'f9b97689-6741-584a-ab66-39efdfac70fb', NULL, 23, 23, 'Then the moon shall be confounded, and the sun ashamed; for Yahweh of Armies will reign on Mount Zion, and in Jerusalem; and before his elders will be glory.'),
  ('3b40dfe0-3171-57e1-a444-43bc4a7316da', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 1, 1, 'Yahweh, you are my God. I will exalt you! I will praise your name, for you have done wonderful things, things planned long ago, in complete faithfulness and truth.'),
  ('ee23df56-1baa-523f-ad03-f04bbed01a6a', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 2, 2, 'For you have made a city into a heap, a fortified city into a ruin, a palace of strangers to be no city. It will never be built.'),
  ('f997cc91-5631-5307-a35e-813a6cdbbdbe', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 3, 3, 'Therefore a strong people will glorify you. A city of awesome nations will fear you.'),
  ('94e55fb4-7d3f-5947-a10b-7e928a9580f4', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 4, 4, 'For you have been a stronghold to the poor, a stronghold to the needy in his distress, a refuge from the storm, a shade from the heat, when the blast of the dreaded ones is like a storm against the wall.'),
  ('33a869a2-1dbd-526c-a44c-35220101bad7', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 5, 5, 'As the heat in a dry place will you bring down the noise of strangers; as the heat by the shade of a cloud, the song of the dreaded ones will be brought low.'),
  ('626ce6d5-d18e-5b82-a614-aac529c9d33d', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 6, 6, 'In this mountain, Yahweh of Armies will make all peoples a feast of fat things, a feast of choice wines, of fat things full of marrow, of well refined choice wines.'),
  ('65d8369d-16ae-5739-af6f-91a2a9ab49da', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 7, 7, 'He will destroy in this mountain the surface of the covering that covers all peoples, and the veil that is spread over all nations.'),
  ('d6c65b95-4dfa-54bc-aa1a-edd096939578', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 8, 8, 'He has swallowed up death forever! The Lord Yahweh will wipe away tears from off all faces. He will take the reproach of his people away from off all the earth, for Yahweh has spoken it.'),
  ('e7d5697c-3ead-59d1-a35b-df879c5b9fc5', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 9, 9, 'It shall be said in that day, "Behold, this is our God! We have waited for him, and he will save us! This is Yahweh! We have waited for him. We will be glad and rejoice in his salvation!"'),
  ('bd18d493-ed90-52b5-a663-da0443e497f1', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 10, 10, 'For in this mountain the hand of Yahweh will rest. Moab will be trodden down in his place, even like straw is trodden down in the water of the dunghill.'),
  ('b8d90d8f-4d71-5c34-a843-80d345546f96', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 11, 11, 'He will spread out his hands in its midst, like one who swims spreads out hands to swim, but his pride will be humbled together with the craft of his hands.'),
  ('9d28df80-4a99-5d84-a542-03d15f1b6aaf', 'bb7b1b31-6873-5731-ab7e-a8be2e2f99ef', NULL, 12, 12, 'He has brought the high fortress of your walls down, laid low, and brought to the ground, even to the dust.'),
  ('5ddeef5a-f3ba-5bd3-ab9c-0bdac0fddb65', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 1, 1, 'In that day, this song will be sung in the land of Judah: "We have a strong city. God appoints salvation for walls and bulwarks.'),
  ('c8963107-aef2-509e-ab49-8c6656ff893b', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 2, 2, 'Open the gates, that the righteous nation may enter: the one which keeps faith.'),
  ('05282563-0921-533e-ab7c-37b45efedea1', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 3, 3, 'You will keep whoever''s mind is steadfast in perfect peace, because he trusts in you.'),
  ('7c5c1ee7-0fdb-5cbd-a563-3abaf675ca15', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 4, 4, 'Trust in Yahweh forever; for in Yah, Yahweh, is an everlasting Rock.'),
  ('16c40d98-cbd8-58b1-ad23-2fc4a644c841', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 5, 5, 'For he has brought down those who dwell on high, the lofty city. He lays it low. He lays it low even to the ground. He brings it even to the dust.'),
  ('2fa7a2a1-a6a7-587d-af35-8488b05ff72b', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 6, 6, 'The foot shall tread it down; Even the feet of the poor, and the steps of the needy."'),
  ('20560bc5-07a9-5f0d-a745-51ff34da42a7', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 7, 7, 'The way of the just is uprightness. You who are upright make the path of the righteous level.'),
  ('5bd20810-3a75-5124-aefc-1965ec14fb09', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 8, 8, 'Yes, in the way of your judgments, Yahweh, have we waited for you. Your name and your renown are the desire of our soul.'),
  ('bc4d6dbe-01e3-5508-a827-7bc3db895898', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 9, 9, 'With my soul have I desired you in the night. Yes, with my spirit within me will I seek you earnestly; for when your judgments are in the earth, the inhabitants of the world learn righteousness.'),
  ('455f4d19-0cf5-524c-aed0-ac2ecc274f5e', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 10, 10, 'Let favor be shown to the wicked, yet he will not learn righteousness. In the land of uprightness he will deal wrongfully, and will not see Yahweh''s majesty.'),
  ('6f4628cb-189d-58e0-a360-ab0f181025bb', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 11, 11, 'Yahweh, your hand is lifted up, yet they don''t see; but they will see your zeal for the people, and be disappointed. Yes, fire will consume your adversaries.'),
  ('8ab839a9-1671-5ede-a00b-aeb974e17f00', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 12, 12, 'Yahweh, you will ordain peace for us, for you have also worked all our works for us.'),
  ('b8d142d6-4be2-518b-a394-829b06f42054', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 13, 13, 'Yahweh our God, other lords besides you have had dominion over us, but by you only will we make mention of your name.'),
  ('4865848d-6485-5a0c-a4ce-3f221f9f7b30', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 14, 14, 'The dead shall not live. The deceased shall not rise. Therefore have you visited and destroyed them, and caused all memory of them to perish.'),
  ('4cee8874-00a5-558a-af15-e007cc64231a', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 15, 15, 'You have increased the nation, O Yahweh. You have increased the nation! You are glorified! You have enlarged all the borders of the land.'),
  ('6e80ba9b-8cad-5d6d-a0aa-3397ff500c0e', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 16, 16, 'Yahweh, in trouble they have visited you. They poured out a prayer when your chastening was on them.'),
  ('e1d39372-6672-5643-a9bf-976ef8aa209f', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 17, 17, 'Like as a woman with child, who draws near the time of her delivery, is in pain and cries out in her pangs; so we have been before you, Yahweh.'),
  ('fb073089-3589-531d-aed3-f4f0778e4aeb', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 18, 18, 'We have been with child. We have been in pain. We gave birth, it seems, only to wind. We have not worked any deliverance in the earth; neither have the inhabitants of the world fallen.'),
  ('e0922332-d303-5e4a-ad6f-0be26a4c9fb0', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 19, 19, 'Your dead shall live. My dead bodies shall arise. Awake and sing, you who dwell in the dust; for your dew is like the dew of herbs, and the earth will cast forth the dead.'),
  ('ddc6e8c9-2c6c-5f54-ab7a-5fda71fcad5b', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 20, 20, 'Come, my people, enter into your rooms, and shut your doors behind you. Hide yourself for a little moment, until the indignation is past.'),
  ('5201cb66-7c94-5742-a42b-10b7480f160e', '4dc7071b-3400-5670-a698-125ac2235711', NULL, 21, 21, 'For, behold, Yahweh comes forth out of his place to punish the inhabitants of the earth for their iniquity. The earth also will disclose her blood, and will no longer cover her slain.'),
  ('0cd47e9a-9149-599b-aee4-242facdfca13', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 1, 1, 'In that day, Yahweh with his hard and great and strong sword will punish leviathan, the fleeing serpent, and leviathan the twisted serpent; and he will kill the dragon that is in the sea.'),
  ('87d651af-0a24-57a5-a31b-d09ff17ece2e', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 2, 2, 'In that day, sing to her, "A pleasant vineyard!'),
  ('d8c6cfa6-bd2f-50eb-aa6f-6aef1a9b914c', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 3, 3, 'I, Yahweh, am its keeper. I will water it every moment. Lest anyone damage it, I will keep it night and day.'),
  ('a3862218-2acb-59d3-ad40-c4793ae0ab2f', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 4, 4, 'Wrath is not in me, but if I should find briers and thorns, I would do battle! I would march on them and I would burn them together.'),
  ('da0225af-dfc7-5df5-a2e4-c731f9325657', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 5, 5, 'Or else let him take hold of my strength, that he may make peace with me. Let him make peace with me."'),
  ('7659d295-3712-5d16-a1bb-545501d09551', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 6, 6, 'In days to come, Jacob will take root. Israel will blossom and bud. They will fill the surface of the world with fruit.'),
  ('c83497b2-be13-516d-a671-f26f14f2f716', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 7, 7, 'Has he struck them as he struck those who struck them? Or are they killed like those who killed them were killed?'),
  ('71aa92c5-2aa2-5847-ac4b-bfe76dc49ea3', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 8, 8, 'In measure, when you send them away, you contend with them. He has removed them with his rough blast in the day of the east wind.'),
  ('e0b19d26-dc89-574b-a196-c9ae1d5e539b', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 9, 9, 'Therefore, by this the iniquity of Jacob will be forgiven, and this is all the fruit of taking away his sin: that he makes all the stones of the altar as chalk stones that are beaten in pieces, so that the Asherim and the incense altars shall rise no more.'),
  ('7c04cbf5-9bad-5715-ae27-bd4065d957d3', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 10, 10, 'For the fortified city is solitary, a habitation deserted and forsaken, like the wilderness. The calf will feed there, and there he will lie down, and consume its branches.'),
  ('f4a2e568-8d81-5e5a-a8d1-d69bd22c04dc', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 11, 11, 'When its boughs are withered, they will be broken off. The women will come and set them on fire, for they are a people of no understanding. Therefore he who made them will not have compassion on them, and he who formed them will show them no favor.'),
  ('54ee0376-d6db-5805-a96e-bffa37f2bef9', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 12, 12, 'It will happen in that day, that Yahweh will thresh from the flowing stream of the Euphrates to the brook of Egypt; and you will be gathered one by one, children of Israel.'),
  ('31833201-ef6e-5441-a7fe-8f4035a7701d', '2beba098-06b0-5e01-a378-8707981d3f82', NULL, 13, 13, 'It will happen in that day that a great trumpet will be blown; and those who were ready to perish in the land of Assyria, and those who were outcasts in the land of Egypt, shall come; and they will worship Yahweh in the holy mountain at Jerusalem.'),
  ('6d010f1a-e7fd-5ee0-ab09-39813d70afab', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 1, 1, 'Woe to the crown of pride of the drunkards of Ephraim, and to the fading flower of his glorious beauty, which is on the head of the fertile valley of those who are overcome with wine!'),
  ('6257c807-6a5d-5e83-ad83-8ae4c4b22827', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 2, 2, 'Behold, the Lord has a mighty and strong one. Like a storm of hail, a destroying storm, and like a storm of mighty waters overflowing, he will cast them down to the earth with his hand.'),
  ('478d4150-967a-504c-a3a7-43311cca26c9', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 3, 3, 'The crown of pride of the drunkards of Ephraim will be trodden under foot.'),
  ('9bb10e52-78bc-58cd-a87a-2c04d0822693', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 4, 4, 'The fading flower of his glorious beauty, which is on the head of the fertile valley, shall be like the first-ripe fig before the summer; which someone picks and eats as soon as he sees it.'),
  ('12aaa327-3c0d-5832-ac0c-3c2de6dc4b9b', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 5, 5, 'In that day, Yahweh of Armies will become a crown of glory, and a diadem of beauty, to the residue of his people;'),
  ('2cc7b832-9396-5ceb-ac60-19eedc0734a6', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 6, 6, 'and a spirit of justice to him who sits in judgment, and strength to those who turn back the battle at the gate.'),
  ('dead84ce-5b78-593f-a4e4-aa3127a93251', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 7, 7, 'They also reel with wine, and stagger with strong drink. The priest and the prophet reel with strong drink. They are swallowed up by wine. They stagger with strong drink. They err in vision. They stumble in judgment.'),
  ('65cbc684-6a7c-5771-a15b-e43638d7d0ca', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 8, 8, 'For all tables are completely full of filthy vomit and filthiness.'),
  ('938102f5-53f2-5b0d-a3b7-93bcd46596e2', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 9, 9, 'Whom will he teach knowledge? To whom will he explain the message? Those who are weaned from the milk, and drawn from the breasts?'),
  ('c67db403-dfcf-589a-a7ba-5c0053508041', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 10, 10, 'For it is precept on precept, precept on precept; line on line, line on line; here a little, there a little.'),
  ('f8452a1e-0cc3-5058-a656-ecffe0a0dde0', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 11, 11, 'But he will speak to this nation with stammering lips and in another language;'),
  ('6175a416-93e4-5f72-aa4d-e969d9420804', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 12, 12, 'to whom he said, "This is the resting place. Give rest to weary;" and "This is the refreshing;" yet they would not hear.'),
  ('1ae47dcf-686d-5b3e-a45e-9b53ce9a3ea4', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 13, 13, 'Therefore the word of Yahweh will be to them precept on precept, precept on precept; line on line, line on line; here a little, there a little; that they may go, fall backward, be broken, be snared, and be taken.'),
  ('ff890b97-7e2f-5238-afc4-bd05834dd1cd', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 14, 14, 'Therefore hear the word of Yahweh, you scoffers, that rule this people in Jerusalem:'),
  ('96bef7e3-db5d-5185-a16a-b6b0ed5af025', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 15, 15, '"Because you have said, ''We have made a covenant with death, and with Sheol are we in agreement. When the overflowing scourge passes through, it won''t come to us; for we have made lies our refuge, and we have hidden ourselves under falsehood.''"'),
  ('72081f2c-f65e-5672-ab00-a8428149eec5', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 16, 16, 'Therefore thus says the Lord Yahweh, "Behold, I lay in Zion for a foundation a stone, a tried stone, a precious cornerstone of a sure foundation. He who believes shall not act hastily.'),
  ('22c6b971-f0e9-5493-aa74-7cfad0a875ed', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 17, 17, 'I will make justice the measuring line, and righteousness the plumb line. The hail will sweep away the refuge of lies, and the waters will overflow the hiding place.'),
  ('c720e0e9-1895-5dc0-aa8d-3e77c3f3787b', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 18, 18, 'Your covenant with death shall be annulled, and your agreement with Sheol shall not stand. When the overflowing scourge passes through, then you will be trampled down by it.'),
  ('54a87c5c-a3a3-5bbb-a1e7-19331cfe5805', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 19, 19, 'As often as it passes through, it will seize you; for morning by morning it will pass through, by day and by night; and it will be nothing but terror to understand the message."'),
  ('8d0c33a3-d276-56cf-a884-f7bb7efa1f81', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 20, 20, 'For the bed is too short to stretch out on, and the blanket is too narrow to wrap oneself in.'),
  ('b8281219-6857-5108-a435-70dd1f054fff', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 21, 21, 'For Yahweh will rise up as on Mount Perazim. He will be angry as in the valley of Gibeon; that he may do his work, his unusual work, and bring to pass his act, his extraordinary act.'),
  ('426026b7-2365-5b30-a47d-29b42e4217d7', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 22, 22, 'Now therefore don''t be scoffers, lest your bonds be made strong; for I have heard a decree of destruction from the Lord, Yahweh of Armies, on the whole earth.'),
  ('00c984f6-fe59-594e-a8e4-db2dbb57d5fd', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 23, 23, 'Give ear, and hear my voice! Listen, and hear my speech!'),
  ('e1a948ec-17b2-530b-a06d-56bc237b5f3b', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 24, 24, 'Does he who plows to sow plow continually? Does he keep turning the soil and breaking the clods?'),
  ('5bc6d9ff-6f0d-52c4-aa5a-029c7158bc8d', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 25, 25, 'When he has leveled its surface, doesn''t he plant the dill, and scatter the cumin seed, and put in the wheat in rows, the barley in the appointed place, and the spelt in its place?'),
  ('235b727c-3156-533d-abc9-328759a08d98', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 26, 26, 'For his God instructs him in right judgment, and teaches him.'),
  ('6e11271d-537c-5406-aaf7-7fcd524b2cb1', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 27, 27, 'For the dill are not threshed with a sharp instrument, neither is a cart wheel turned over the cumin; but the dill is beaten out with a stick, and the cumin with a rod.'),
  ('40027d70-3617-5a6a-a2f9-fff30c4cc9bf', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 28, 28, 'Bread flour must be ground; so he will not always be threshing it. Although he drives the wheel of his threshing cart over it, his horses don''t grind it.'),
  ('158a437b-4bc6-537a-a017-f64481bb7635', 'd5384d03-964a-5f1d-ad4c-cfe0f64084c6', NULL, 29, 29, 'This also comes forth from Yahweh of Armies, who is wonderful in counsel, and excellent in wisdom.'),
  ('22df34d2-950a-50c5-aa7a-fe2d9b71a7d1', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 1, 1, 'Woe to Ariel! Ariel, the city where David encamped! Add year to year; let the feasts come around;'),
  ('9d232a64-7d1b-52c6-a07b-e303008c24b2', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 2, 2, 'then I will distress Ariel, and there will be mourning and lamentation. She shall be to me as an altar hearth.'),
  ('59b10362-cc7d-5090-a13e-24748f9c14e9', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 3, 3, 'I will encamp against you all around you, and will lay siege against you with posted troops. I will raise siege works against you.'),
  ('fe2b6dad-7824-59b2-af6c-ea7b78858c04', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 4, 4, 'You will be brought down, and will speak out of the ground. Your speech will mumble out of the dust. Your voice will be as of one who has a familiar spirit, out of the ground, and your speech will whisper out of the dust.'),
  ('793470bd-ef10-5ae1-a2df-ffbf0452365b', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 5, 5, 'But the multitude of your foes will be like fine dust, and the multitude of the ruthless ones like chaff that blows away. Yes, it will be in an instant, suddenly.'),
  ('857379e6-ed94-56ac-a009-e87fb3d30119', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 6, 6, 'She will be visited by Yahweh of Armies with thunder, with earthquake, with great noise, with whirlwind and storm, and with the flame of a devouring fire.'),
  ('c301d509-ef21-52a7-aa9d-c20e3c58fdb0', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 7, 7, 'The multitude of all the nations that fight against Ariel, even all who fight against her and her stronghold, and who distress her, will be like a dream, a vision of the night.'),
  ('d0ea1970-f421-554e-a9c0-053fa009b135', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 8, 8, 'It will be like when a hungry man dreams, and behold, he eats; but he awakes, and his hunger isn''t satisfied; or like when a thirsty man dreams, and behold, he drinks; but he awakes, and behold, he is faint, and he is still thirsty. The multitude of all the nations that fight against Mount Zion will be like that.'),
  ('1c3a01e6-6440-50a0-aea3-c17e04f09c38', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 9, 9, 'Pause and wonder! Blind yourselves and be blind! They are drunken, but not with wine; they stagger, but not with strong drink.'),
  ('42e04754-03cf-536f-a6c8-fc230755958a', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 10, 10, 'For Yahweh has poured out on you a spirit of deep sleep, and has closed your eyes, the prophets; and he has covered your heads, the seers.'),
  ('6ded47c9-6c03-55dc-a7d0-d27bd6e82a64', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 11, 11, 'All vision has become to you like the words of a book that is sealed, which men deliver to one who is educated, saying, "Read this, please;" and he says, "I can''t, for it is sealed:"'),
  ('00b31f12-6dc6-5df6-ae32-8ac9ba5ba390', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 12, 12, 'and the book is delivered to one who is not educated, saying, "Read this, please;" and he says, "I can''t read."'),
  ('8c59bda6-d5ca-5f0d-a008-0cce2769b89b', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 13, 13, 'The Lord said, "Because this people draws near with their mouth and with their lips to honor me, but they have removed their heart far from me, and their fear of me is a commandment of men which has been taught;'),
  ('e6bb23a9-3c26-5e32-a973-55cb52605c03', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 14, 14, 'therefore, behold, I will proceed to do a marvelous work among this people, even a marvelous work and a wonder; and the wisdom of their wise men will perish, and the understanding of their prudent men will be hidden."'),
  ('184f8031-0c6b-5039-a5a4-32eabf3c5b75', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 15, 15, 'Woe to those who deeply hide their counsel from Yahweh, and whose works are in the dark, and who say, "Who sees us?" and "Who knows us?"'),
  ('33aa07e1-f7c8-566d-ac6a-b273f5d5cf07', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 16, 16, 'You turn things upside down! Should the potter be thought to be like clay; that the thing made should say about him who made it, "He didn''t make me;" or the thing formed say of him who formed it, "He has no understanding?"'),
  ('c7227ca1-059f-54f0-afaa-44ada3312bc3', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 17, 17, 'Isn''t it yet a very little while, and Lebanon will be turned into a fruitful field, and the fruitful field will be regarded as a forest?'),
  ('99dca40b-8751-52e5-af37-731578cb07b5', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 18, 18, 'In that day, the deaf will hear the words of the book, and the eyes of the blind will see out of obscurity and out of darkness.'),
  ('464873f7-7a24-58b7-a087-17a86b73f91f', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 19, 19, 'The humble also will increase their joy in Yahweh, and the poor among men will rejoice in the Holy One of Israel.'),
  ('63792a1d-27bf-5ff4-abdb-8f54798f4a7f', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 20, 20, 'For the ruthless is brought to nothing, and the scoffer ceases, and all those who are alert to do evil are cut off--'),
  ('560a09ba-065d-5f5e-a07f-55a940b8f47a', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 21, 21, 'who cause a person to be indicted by a word, and lay a snare for the arbiter in the gate, and who deprive the innocent of justice with false testimony.'),
  ('c5aff155-3731-5379-a9c4-06dc9661710c', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 22, 22, 'Therefore thus says Yahweh, who redeemed Abraham, concerning the house of Jacob: "Jacob shall no longer be ashamed, neither shall his face grow pale.'),
  ('fd1bb380-ac2f-59d8-a6dc-6186ab458f95', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 23, 23, 'But when he sees his children, the work of my hands, in the midst of him, they will sanctify my name. Yes, they will sanctify the Holy One of Jacob, and will stand in awe of the God of Israel.'),
  ('6c43e14c-c5ba-5931-a011-7a6cea3fd437', '1ca8b71c-3c5a-5200-aeb1-832e614c9195', NULL, 24, 24, 'They also who err in spirit will come to understanding, and those who grumble will receive instruction."'),
  ('7c492988-4415-5084-a509-be92d91f9abe', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 1, 1, '"Woe to the rebellious children," says Yahweh, "who take counsel, but not from me; and who make an alliance, but not with my Spirit, that they may add sin to sin,'),
  ('e62d9f5b-4b27-54af-ab18-b93699d14fba', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 2, 2, 'who set out to go down into Egypt, and have not asked my advice; to strengthen themselves in the strength of Pharaoh, and to take refuge in the shadow of Egypt!'),
  ('253ef940-af43-5df7-adaa-578d499a124b', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 3, 3, 'Therefore the strength of Pharaoh will be your shame, and the refuge in the shadow of Egypt your confusion.'),
  ('515ef27b-a419-523b-a8f6-253adfffaa59', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 4, 4, 'For their princes are at Zoan, and their ambassadors have come to Hanes.'),
  ('bb2bd8c9-df06-5b0d-a990-36781104170d', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 5, 5, 'They shall all be ashamed because of a people that can''t profit them, that are not a help nor profit, but a shame, and also a reproach."'),
  ('203725a6-9a15-51d9-a300-37c2ed30d760', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 6, 6, 'The burden of the animals of the South. Through the land of trouble and anguish, of the lioness and the lion, the viper and fiery flying serpent, they carry their riches on the shoulders of young donkeys, and their treasures on the humps of camels, to an unprofitable people.'),
  ('d4bcbff0-d9d8-5519-ae61-7a70ce57d4f1', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 7, 7, 'For Egypt helps in vain, and to no purpose; therefore have I called her Rahab who sits still.'),
  ('d8feb30f-b884-5a61-aa05-d6c40d228c26', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 8, 8, 'Now go, write it before them on a tablet, and inscribe it in a book, that it may be for the time to come forever and ever.'),
  ('6be15503-d1fa-580f-ae14-508aa67b553b', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 9, 9, 'For it is a rebellious people, lying children, children who will not hear the law of Yahweh;'),
  ('f5346659-2ad9-5d22-a37a-43ac09adc2ab', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 10, 10, 'who tell the seers, "Don''t see!" and to the prophets, "Don''t prophesy to us right things. Tell us pleasant things. Prophesy deceits.'),
  ('82c1d53b-483f-565e-a5f9-40c9d8c891f5', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 11, 11, 'Get out of the way. Turn aside from the path. Cause the Holy One of Israel to cease from before us."'),
  ('76ae12c3-1250-5724-a606-bb6a80a24384', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 12, 12, 'Therefore thus says the Holy One of Israel, "Because you despise this word, and trust in oppression and perverseness, and rely on it;'),
  ('2474cad8-0c67-5714-aa0b-49b0dc635ecc', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 13, 13, 'therefore this iniquity shall be to you like a breach ready to fall, swelling out in a high wall, whose breaking comes suddenly in an instant.'),
  ('5aee534c-4ef1-5467-aec9-bf68657686cc', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 14, 14, 'He will break it as a potter''s vessel is broken, breaking it in pieces without sparing, so that there won''t be found among the broken piece a piece good enough to take fire from the hearth, or to dip up water out of the cistern."'),
  ('b030f60c-ef9e-5baf-a4a6-f4f5b42e7726', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 15, 15, 'For thus said the Lord Yahweh, the Holy One of Israel, "You will be saved in returning and rest. Your strength will be in quietness and in confidence." You refused,'),
  ('7abb9635-9e60-50c2-a407-eb594d6374bc', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 16, 16, 'but you said, "No, for we will flee on horses;" therefore you will flee; and, "We will ride on the swift;" therefore those who pursue you will be swift.'),
  ('4484d0cf-9ee0-5e42-adfe-79eea5e9ca0e', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 17, 17, 'One thousand will flee at the threat of one. At the threat of five, you will flee until you are left like a beacon on the top of a mountain, and like a banner on a hill.'),
  ('8359bd80-ec9d-51c3-a87f-7d9b3249ae9a', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 18, 18, 'Therefore Yahweh will wait, that he may be gracious to you; and therefore he will be exalted, that he may have mercy on you, for Yahweh is a God of justice. Blessed are all those who wait for him.'),
  ('cc1fb9ab-2303-5efc-a9cb-c18ab902b0d1', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 19, 19, 'For the people will dwell in Zion at Jerusalem. You will weep no more. He will surely be gracious to you at the voice of your cry. When he hears you, he will answer you.'),
  ('9c343e6d-76b1-5bf5-aa6b-d537c7b1a520', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 20, 20, 'Though the Lord may give you the bread of adversity and the water of affliction, yet your teachers won''t be hidden anymore, but your eyes will see your teachers;'),
  ('3f616d3c-efe8-5643-a659-af00e4eefa6d', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 21, 21, 'and when you turn to the right hand, and when you turn to the left, your ears will hear a voice behind you, saying, "This is the way. Walk in it."'),
  ('0d29fcef-bb81-5cdc-afbb-157544bfbc34', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 22, 22, 'You shall defile the overlaying of your engraved images of silver, and the plating of your molten images of gold. You shall cast them away as an unclean thing. You shall tell it, "Go away!"'),
  ('a72dcfce-06f0-5fc3-aa48-39936d7f90c2', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 23, 23, 'He will give the rain for your seed, with which you will sow the ground; and bread of the increase of the ground will be rich and plentiful. In that day, your livestock will feed in large pastures.'),
  ('00133f3e-5d0b-57de-a6d4-228ceddb20ae', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 24, 24, 'The oxen likewise and the young donkeys that till the ground will eat savory provender, which has been winnowed with the shovel and with the fork.'),
  ('ccf40c07-e8d9-5de7-a483-99a4355517f0', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 25, 25, 'There shall be brooks and streams of water on every lofty mountain and on every high hill in the day of the great slaughter, when the towers fall.'),
  ('95c951a1-e9d7-5faf-acf4-9c78dff9e4c7', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 26, 26, 'Moreover the light of the moon will be like the light of the sun, and the light of the sun will be seven times brighter, like the light of seven days, in the day that Yahweh binds up the fracture of his people, and heals the wound they were struck with.'),
  ('72746a2c-8675-5a73-ae5f-122d0136eb95', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 27, 27, 'Behold, the name of Yahweh comes from far away, burning with his anger, and in thick rising smoke. His lips are full of indignation, and his tongue is as a devouring fire.'),
  ('aadfaa3f-f8c5-5918-ae4f-4287edb18e02', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 28, 28, 'His breath is as an overflowing stream that reaches even to the neck, to sift the nations with the sieve of destruction; and a bridle that leads to ruin will be in the jaws of the peoples.'),
  ('88d87b66-a2bf-5e9e-af02-8e9ec30dce7b', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 29, 29, 'You will have a song, as in the night when a holy feast is kept; and gladness of heart, as when one goes with a flute to come to Yahweh''s mountain, to Israel''s Rock.'),
  ('043afd38-ee8f-59f9-a2fb-1ac8fe053209', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 30, 30, 'Yahweh will cause his glorious voice to be heard, and will show the descent of his arm, with the indignation of his anger, and the flame of a devouring fire, with a blast, storm, and hailstones.'),
  ('13100417-2bd3-5a9f-adf3-1e5516177b23', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 31, 31, 'For through the voice of Yahweh the Assyrian will be dismayed. He will strike him with his rod.'),
  ('0fc45988-8574-5307-a848-5acbadea7623', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 32, 32, 'Every stroke of the rod of punishment, which Yahweh will lay on him, will be with the sound of tambourines and harps. He will fight with them in battles, brandishing weapons.'),
  ('d61964af-adb6-5e5c-a92d-8bbd30116c7c', 'c08c97e9-a91d-5792-ab85-4c30c001c532', NULL, 33, 33, 'For his burning place has long been ready. Yes, for the king it is prepared. He has made its pyre deep and large with fire and much wood. Yahweh''s breath, like a stream of sulfur, kindles it.'),
  ('c5e92122-0c9f-53cb-a086-5af408cb8979', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 1, 1, 'Woe to those who go down to Egypt for help, and rely on horses, and trust in chariots because they are many, and in horsemen because they are very strong, but they don''t look to the Holy One of Israel, and they don''t seek Yahweh!'),
  ('927780d4-9193-57a7-ad78-ced77a19a257', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 2, 2, 'Yet he also is wise, and will bring disaster, and will not call back his words, but will arise against the house of the evildoers, and against the help of those who work iniquity.'),
  ('f6e6ae37-4508-57c5-a6a0-86ade112f374', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 3, 3, 'Now the Egyptians are men, and not God; and their horses flesh, and not spirit. When Yahweh stretches out his hand, both he who helps shall stumble, and he who is helped shall fall, and they all shall be consumed together.'),
  ('0cdcb15e-2cb2-5aab-a0b2-ca8d851a4a99', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 4, 4, 'For thus says Yahweh to me, "As the lion and the young lion growling over his prey, if a multitude of shepherds is called together against him, will not be dismayed at their voice, nor abase himself for the noise of them, so Yahweh of Armies will come down to fight on Mount Zion and on its heights.'),
  ('881356f4-0a0c-5cfc-af0a-dec0fe4589d0', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 5, 5, 'As birds hovering, so Yahweh of Armies will protect Jerusalem. He will protect and deliver it. He will pass over and preserve it."'),
  ('2786ddbc-877e-5949-a891-1e16808c53c2', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 6, 6, 'Return to him from whom you have deeply revolted, children of Israel.'),
  ('8547062c-c404-502d-a5fa-f18bb1c33ad0', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 7, 7, 'For in that day everyone shall cast away his idols of silver and his idols of gold--sin which your own hands have made for you.'),
  ('b06fdbed-9a2e-5e95-adaf-844125e076af', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 8, 8, '"The Assyrian will fall by the sword, not of man; and the sword, not of mankind, shall devour him. He will flee from the sword, and his young men will become subject to forced labor.'),
  ('39d1b066-2007-50b1-a1c9-0b0ca12de7db', '34cc3389-a379-5bef-a8dd-ab996f4a4984', NULL, 9, 9, 'His rock will pass away by reason of terror, and his princes will be afraid of the banner," says Yahweh, whose fire is in Zion, and his furnace in Jerusalem.'),
  ('60bdc0d8-fd97-5f65-a923-db71866f9a19', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 1, 1, 'Behold, a king shall reign in righteousness, and princes shall rule in justice.'),
  ('a0d853ab-fb82-5076-a9fa-f861234521bc', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 2, 2, 'A man shall be as a hiding place from the wind, and a covert from the storm, as streams of water in a dry place, as the shade of a large rock in a weary land.'),
  ('493e4779-7811-5dc3-a6e3-5273ad47dae1', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 3, 3, 'The eyes of those who see will not be dim, and the ears of those who hear will listen.'),
  ('4bc0f800-19a3-5a83-abd9-bd5641f7104c', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 4, 4, 'The heart of the rash will understand knowledge, and the tongue of the stammerers will be ready to speak plainly.'),
  ('73c5e997-10ff-532a-a892-d8b0bf71b91d', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 5, 5, 'The fool will no longer be called noble, nor the scoundrel be highly respected.'),
  ('ab94bb77-5179-5e14-a1a8-259e7cfa7025', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 6, 6, 'For the fool will speak folly, and his heart will work iniquity, to practice profanity, and to utter error against Yahweh, To make empty the soul of the hungry, and to cause the drink of the thirsty to fail.'),
  ('9ef2d726-bcca-5eab-a7e1-2c62c4c27f91', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 7, 7, 'The ways of the scoundrel are evil. He devises wicked devices to destroy the humble with lying words, even when the needy speaks right.'),
  ('99051bd9-f568-5843-a167-30a5a5c83ccd', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 8, 8, 'But the noble devises noble things; and he will continue in noble things.'),
  ('f0d86d7a-0983-5e7f-af0c-fe16a07a5460', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 9, 9, 'Rise up, you women who are at ease! Hear my voice! You careless daughters, give ear to my speech!'),
  ('e2acab56-d567-5b87-a700-6166d37c97d5', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 10, 10, 'For days beyond a year you will be troubled, you careless women; for the vintage shall fail. The harvest won''t come.'),
  ('8a7c2fb1-07bd-5bf9-a522-abf6b99595bc', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 11, 11, 'Tremble, you women who are at ease! Be troubled, you careless ones! Strip yourselves, make yourselves naked, and put sackcloth on your waist.'),
  ('4a927382-2f15-5d86-a1d0-5f8ff668cb7f', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 12, 12, 'Beat your breasts for the pleasant fields, for the fruitful vine.'),
  ('3a05ecea-04cb-5091-adb5-ca1861e7ad1d', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 13, 13, 'Thorns and briars will come up on my people''s land; yes, on all the houses of joy in the joyous city.'),
  ('a85507c3-ebaf-59a4-a1ed-7e28e5c4d11a', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 14, 14, 'For the palace will be forsaken. The populous city will be deserted. The hill and the watchtower will be for dens forever, a delight for wild donkeys, a pasture of flocks;'),
  ('0e06136a-d0c3-5af6-a501-e2af543cdb43', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 15, 15, 'Until the Spirit is poured on us from on high, and the wilderness becomes a fruitful field, and the fruitful field is considered a forest.'),
  ('183db3bf-02a8-56fe-acca-88d17bb10852', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 16, 16, 'Then justice will dwell in the wilderness; and righteousness will remain in the fruitful field.'),
  ('bd7c525d-7d89-54e3-ae07-1069d00d1583', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 17, 17, 'The work of righteousness will be peace; and the effect of righteousness, quietness and confidence forever.'),
  ('293af906-59fe-5bef-ade3-84684206485b', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 18, 18, 'My people will live in a peaceful habitation, in safe dwellings, and in quiet resting places.'),
  ('894b3fc3-2da5-57fe-ab1b-a28d5d2295bc', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 19, 19, 'Though hail flattens the forest, and the city is leveled completely.'),
  ('d6580ff7-7b27-54be-a130-efd392e6e411', '1bdcd944-dcf9-5a23-ad55-aa2e0f6808ae', NULL, 20, 20, 'Blessed are you who sow beside all waters, who send out the feet of the ox and the donkey.'),
  ('383da527-c243-592a-a913-336a53427b52', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 1, 1, 'Woe to you who destroy, but you weren''t destroyed; and who betray, but nobody betrayed you! When you have finished destroying, you will be destroyed; and when you have made an end of betrayal, you will be betrayed.'),
  ('f4747a2b-cbba-56fe-a5c7-010747701f16', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 2, 2, 'Yahweh, be gracious to us. We have waited for you. Be our strength every morning, our salvation also in the time of trouble.'),
  ('1c82f8e2-a35b-5394-aa7d-76bd756792b2', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 3, 3, 'At the noise of the thunder, the peoples have fled. When you lift yourself up, the nations are scattered.'),
  ('d9425eca-7633-5171-af4d-4e8a7d773482', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 4, 4, 'Your spoil will be gathered as the caterpillar gathers. Men will leap on it as locusts leap.'),
  ('c3b758f9-7586-5e5b-a88b-585dfb7e9875', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 5, 5, 'Yahweh is exalted, for he dwells on high. He has filled Zion with justice and righteousness.'),
  ('909bd54c-3b88-5e13-a9e0-72fcdd815a49', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 6, 6, 'There will be stability in your times, abundance of salvation, wisdom, and knowledge. The fear of Yahweh is your treasure.'),
  ('9cb52810-1e77-50f0-a887-95f397c8b31d', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 7, 7, 'Behold, their valiant ones cry outside; the ambassadors of peace weep bitterly.'),
  ('a53f4657-82f3-586d-aee8-331ceb86485e', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 8, 8, 'The highways are desolate. The traveling man ceases. The covenant is broken. He has despised the cities. He doesn''t respect man.'),
  ('eecfc08f-c3ba-59ae-a646-8da09b686ff1', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 9, 9, 'The land mourns and languishes. Lebanon is confounded and withers away. Sharon is like a desert, and Bashan and Carmel are stripped bare.'),
  ('380b1e8e-bcc7-5bf3-a2eb-15a5b7bdd6bb', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 10, 10, '"Now I will arise," says Yahweh; "Now I will lift myself up. Now I will be exalted.'),
  ('9f2f0c5f-1507-54e2-ac0d-b09d0e6bff7a', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 11, 11, 'You will conceive chaff. You will bring forth stubble. Your breath is a fire that will devour you.'),
  ('0d61f121-d071-50eb-af22-e53ec569fced', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 12, 12, 'The peoples will be like the burning of lime, like thorns that are cut down and burned in the fire.'),
  ('502fdc0b-8da6-5e26-ade3-290674c57831', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 13, 13, 'Hear, you who are far off, what I have done; and, you who are near, acknowledge my might."'),
  ('9124460a-8420-5a2c-ad2a-e6599c74e261', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 14, 14, 'The sinners in Zion are afraid. Trembling has seized the godless ones. Who among us can live with the devouring fire? Who among us can live with everlasting burning?'),
  ('6371704d-0235-51ab-a345-c987330045fe', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 15, 15, 'He who walks righteously, and speaks blamelessly; He who despises the gain of oppressions, who gestures with his hands, refusing to take a bribe, who stops his ears from hearing of blood, and shuts his eyes from looking at evil--'),
  ('eae1c69e-07a3-5016-a51d-4d4356abf23b', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 16, 16, 'he will dwell on high. His place of defense will be the fortress of rocks. His bread will be supplied. His waters will be sure.'),
  ('2877980e-2378-59ac-a534-0bd86fc5aab4', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 17, 17, 'Your eyes will see the king in his beauty. They will see a distant land.'),
  ('ccf48003-accc-5755-afe1-05097769a52a', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 18, 18, 'Your heart will meditate on the terror. Where is he who counted? Where is he who weighed? Where is he who counted the towers?'),
  ('92b9806a-c77d-5791-af57-9943010843c8', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 19, 19, 'You will no longer see the fierce people, a people of a deep speech that you can''t comprehend, with a strange language that you can''t understand.'),
  ('0375bb50-d9c8-5391-a24a-f036c26954ef', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 20, 20, 'Look at Zion, the city of our appointed festivals. Your eyes will see Jerusalem, a quiet habitation, a tent that won''t be removed. Its stakes will never be plucked up, nor will any of its cords be broken.'),
  ('fbbebe17-0062-575b-aab5-18cc50c1fdce', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 21, 21, 'But there Yahweh will be with us in majesty, a place of broad rivers and streams, in which no galley with oars will go, neither will any gallant ship pass by there.'),
  ('f5e960a5-2ddd-598f-a164-4aee874d669f', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 22, 22, 'For Yahweh is our judge. Yahweh is our lawgiver. Yahweh is our king. He will save us.'),
  ('3dd7a172-a336-52de-a948-719ecbe423e6', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 23, 23, 'Your rigging is untied. They couldn''t strengthen the foot of their mast. They couldn''t spread the sail. Then the prey of a great spoil was divided. The lame took the prey.'),
  ('1b54b276-3caf-5a53-a83e-cb052dfe0983', 'dca5ce52-cfca-5745-ad72-a4b958c4ba68', NULL, 24, 24, 'The inhabitant won''t say, "I am sick." The people who dwell therein will be forgiven their iniquity.'),
  ('610eb372-2a15-5766-ac2a-bc75f561b92e', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 1, 1, 'Come near, you nations, to hear! Listen, you peoples. Let the earth and all it contains hear; the world, and everything that comes from it.'),
  ('da6728ea-c7ef-5901-a678-f7f6bfbd9e75', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 2, 2, 'For Yahweh is enraged against all the nations, and angry with all their armies. He has utterly destroyed them. He has given them over for slaughter.'),
  ('7dd5cb2b-af23-55d1-ae88-e41b58d500e4', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 3, 3, 'Their slain will also be cast out, and the stench of their dead bodies will come up; and the mountains will melt in their blood.'),
  ('dd3213aa-743c-523a-ac52-1936de32309b', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 4, 4, 'All of the army of the sky will be dissolved. The sky will be rolled up like a scroll, and all its armies will fade away, as a leaf fades from off a vine or a fig tree.'),
  ('699ffb86-d1be-50d7-a5ec-5f3abd72f456', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 5, 5, 'For my sword has drunk its fill in the sky. Behold, it will come down on Edom, and on the people of my curse, for judgment.'),
  ('f57cf5ee-bf16-5c97-adf5-ab473a353f46', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 6, 6, 'Yahweh''s sword is filled with blood. It is covered with fat, with the blood of lambs and goats, with the fat of the kidneys of rams; for Yahweh has a sacrifice in Bozrah, And a great slaughter in the land of Edom.'),
  ('20b88e8d-62c2-5e1a-a2dc-2d9aadc4d901', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 7, 7, 'The wild oxen will come down with them, and the young bulls with the mighty bulls; and their land will be drunken with blood, and their dust made greasy with fat.'),
  ('fc1e4b5c-9b52-5fb8-ad70-99f476c6ca03', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 8, 8, 'For Yahweh has a day of vengeance, a year of recompense for the cause of Zion.'),
  ('2bc11d0e-5ee2-5f0d-a44e-ed1e0945263a', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 9, 9, 'Its streams will be turned into pitch, its dust into sulfur, And its land will become burning pitch.'),
  ('3c5de082-a2fa-5e6d-a2e8-7462b103c6dc', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 10, 10, 'It won''t be quenched night nor day. Its smoke will go up forever. From generation to generation, it will lie waste. No one will pass through it forever and ever.'),
  ('c3443468-0812-5d4c-a23f-a7851cf82c7b', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 11, 11, 'But the pelican and the porcupine will possess it. The owl and the raven will dwell in it. He will stretch the line of confusion over it, and the plumb line of emptiness.'),
  ('828b4dfb-324b-545a-a66b-06fef128f4a7', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 12, 12, 'They shall call its nobles to the kingdom, but none shall be there; and all its princes shall be nothing.'),
  ('db8b93af-5c45-5b3c-ad55-e025a4388620', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 13, 13, 'Thorns will come up in its palaces, nettles and thistles in its fortresses; and it will be a habitation of jackals, a court for ostriches.'),
  ('e6354439-0da3-5358-a2c0-c9f741621587', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 14, 14, 'The wild animals of the desert will meet with the wolves, and the wild goat will cry to his fellow. Yes, the night creature shall settle there, and shall find herself a place of rest.'),
  ('f806831c-41ce-55b2-ad44-6c7b8092d217', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 15, 15, 'The arrow snake will make her nest there, and lay, hatch, and gather under her shade. Yes, the kites will be gathered there, every one with her mate.'),
  ('f4e8fa0a-2298-5676-ab77-467a0ae2b3af', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 16, 16, 'Search in the book of Yahweh, and read: not one of these will be missing. none will lack her mate. For my mouth has commanded, and his Spirit has gathered them.'),
  ('2b6e7e44-906c-545d-aa15-eba68d6a1cd6', 'b6df8478-0501-553c-a07f-8d1d733bdf12', NULL, 17, 17, 'He has cast the lot for them, and his hand has divided it to them with a measuring line. They shall possess it forever. From generation to generation they will dwell in it.'),
  ('52f71893-3c8b-50df-a3aa-2b8cf5d8f85c', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 1, 1, 'The wilderness and the dry land will be glad. The desert will rejoice and blossom like a rose.'),
  ('ff3e9579-9235-5c05-aa8f-954a407cfd6e', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 2, 2, 'It will blossom abundantly, and rejoice even with joy and singing. Lebanon''s glory Lebanon will be given to it, the excellence of Carmel and Sharon. They will see Yahweh''s glory, the excellence of our God.'),
  ('ce45ffb8-d299-5ab7-ae37-228acc0d5dc3', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 3, 3, 'Strengthen the weak hands, and make firm the feeble knees.'),
  ('9bec0127-e376-52a2-a9e7-7382ccb9b21b', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 4, 4, 'Tell those who have a fearful heart, "Be strong. Don''t be afraid. Behold, your God will come with vengeance, God''s retribution. He will come and save you.'),
  ('b88508fc-f11e-55db-acc1-d4530dee1aea', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 5, 5, 'Then the eyes of the blind will be opened, and the ears of the deaf will be unstopped.'),
  ('cc9b6319-67f7-54d1-ac1d-2d3dfc01c85a', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 6, 6, 'Then the lame man will leap like a deer, and the tongue of the mute will sing; for waters will break out in the wilderness, and streams in the desert.'),
  ('76447e81-65a3-5e56-a509-02b5861d8e64', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 7, 7, 'The burning sand will become a pool, and the thirsty ground springs of water. Grass with reeds and rushes will be in the habitation of jackals, where they lay.'),
  ('e6b36718-0249-55da-a6b8-bb521dc8dc79', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 8, 8, 'A highway will be there, a road, and it will be called The Holy Way. The unclean shall not pass over it, but it will be for those who walk in the Way. Wicked fools will not go there.'),
  ('356400a2-8c67-572c-aa64-86b633140fce', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 9, 9, 'No lion will be there, nor will any ravenous animal go up on it. They will not be found there; but the redeemed will walk there.'),
  ('7278e77d-61e5-5b47-a5a2-8c68adaa2758', '90266be5-6a0a-5f2f-af72-51884d50be59', NULL, 10, 10, 'The Yahweh''s ransomed ones will return, and come with singing to Zion; and everlasting joy will be on their heads. They will obtain gladness and joy, and sorrow and sighing will flee away."'),
  ('ff07a15b-f898-53e6-ab83-c10f48f6c564', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 1, 1, 'Now it happened in the fourteenth year of king Hezekiah, that Sennacherib king of Assyria attacked all of the fortified cities of Judah, and captured them.'),
  ('b0fa7326-70d3-54fb-a9a3-bb839d141484', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 2, 2, 'The king of Assyria sent Rabshakeh from Lachish to Jerusalem to king Hezekiah with a large army. He stood by the aqueduct from the upper pool in the fuller''s field highway.'),
  ('7769b28c-06ee-5fbe-ab98-7fca26990b6c', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 3, 3, 'Then Eliakim the son of Hilkiah, who was over the household, and Shebna the scribe, and Joah, the son of Asaph, the recorder came out to him.'),
  ('eb257d83-9e9c-5e7d-a5ac-ce32d190e936', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 4, 4, 'Rabshakeh said to them, "Now tell Hezekiah, ''Thus says the great king, the king of Assyria, "What confidence is this in which you trust?'),
  ('48cb17c3-8aa5-53da-ae24-a13d55bcf579', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 5, 5, 'I say that your counsel and strength for the war are only vain words. Now in whom do you trust, that you have rebelled against me?'),
  ('323b2893-680b-515d-abdb-b73144cba310', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 6, 6, 'Behold, you trust in the staff of this bruised reed, even in Egypt, which if a man leans on it, it will go into his hand and pierce it. So is Pharaoh king of Egypt to all who trust in him.'),
  ('8101cccc-f19f-5c85-a852-d0f94fcb94ed', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 7, 7, 'But if you tell me, ''We trust in Yahweh our God,'' isn''t that he whose high places and whose altars Hezekiah has taken away, and has said to Judah and to Jerusalem, ''You shall worship before this altar?''"'),
  ('8c489eec-b91f-5957-a4fb-f52986b4f3a5', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 8, 8, 'Now therefore, please make a pledge to my master the king of Assyria, and I will give you two thousand horses, if you are able on your part to set riders on them.'),
  ('27479acd-bffa-532e-ad62-819091def3ee', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 9, 9, 'How then can you turn away the face of one captain of the least of my master''s servants, and put your trust on Egypt for chariots and for horsemen?'),
  ('4b88cf84-1a96-5062-a0a3-486256981a62', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 10, 10, 'Have I come up now without Yahweh against this land to destroy it? Yahweh said to me, "Go up against this land, and destroy it."''"'),
  ('e078f0af-2261-54c0-a49d-2049d1e5dbb4', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 11, 11, 'Then Eliakim, Shebna and Joah said to Rabshakeh, "Please speak to your servants in Aramaic, for we understand it; and don''t speak to us in the Jews'' language in the hearing of the people who are on the wall."'),
  ('98bc68a6-a19c-53c0-a92d-3ffae32ca66c', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 12, 12, 'But Rabshakeh said, "Has my master sent me only to your master and to you, to speak these words, and not to the men who sit on the wall, who will eat their own dung and drink their own urine with you?"'),
  ('4e837a89-2618-5dad-a5c6-f116e7113c93', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 13, 13, 'Then Rabshakeh stood, and called out with a loud voice in the Jews'' language, and said, "Hear the words of the great king, the king of Assyria!'),
  ('ee95320a-606d-5746-afea-a97f254c5e10', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 14, 14, 'Thus says the king, ''Don''t let Hezekiah deceive you; for he will not be able to deliver you.'),
  ('93f0e04a-a21d-57eb-ae9f-4977ab132b67', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 15, 15, 'Don''t let Hezekiah make you trust in Yahweh, saying, "Yahweh will surely deliver us. This city won''t be given into the hand of the king of Assyria."'''),
  ('269e1f01-e255-5c29-ac87-d0bc268492ee', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 16, 16, 'Don''t listen to Hezekiah, for thus says the king of Assyria, ''Make your peace with me, and come out to me; and each of you eat from his vine, and each one from his fig tree, and each one of you drink the waters of his own cistern;'),
  ('10b6ebef-78d0-5ece-af84-bae50e2115fb', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 17, 17, 'until I come and take you away to a land like your own land, a land of grain and new wine, a land of bread and vineyards.'),
  ('f165b982-bb15-53bc-a194-4a22af844aec', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 18, 18, 'Beware lest Hezekiah persuade you, saying, "Yahweh will deliver us." Have any of the gods of the nations delivered their lands from the hand of the king of Assyria?'),
  ('098cdd21-3906-5a21-a3b0-d80c6dd296c1', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 19, 19, 'Where are the gods of Hamath and Arpad? Where are the gods of Sepharvaim? Have they delivered Samaria from my hand?'),
  ('66318fa9-5c24-5d43-a457-cca5e367a5a2', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 20, 20, 'Who are they among all the gods of these countries that have delivered their country out of my hand, that Yahweh should deliver Jerusalem out of my hand?''"'),
  ('5a3d2f64-d1e6-540d-a428-a59f4023ecfb', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 21, 21, 'But they remained silent, and said nothing in reply, for the king''s commandment was, "Don''t answer him."'),
  ('290ecad5-cb2e-5846-ac7d-5e011a42f589', '34235adb-f8bd-5418-a7a9-76f785609ddd', NULL, 22, 22, 'Then Eliakim the son of Hilkiah, who was over the household, and Shebna the scribe, and Joah, the son of Asaph, the recorder, came to Hezekiah with their clothes torn, and told him the words of Rabshakeh.'),
  ('f5df951f-bc4d-596d-a437-3bd2acb0235d', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 1, 1, 'It happened, when king Hezekiah heard it, that he tore his clothes, covered himself with sackcloth, and went into Yahweh''s house.'),
  ('39f136fc-5ad2-5ea7-a953-b29cd7e3123d', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 2, 2, 'He sent Eliakim, who was over the household, and Shebna the scribe, and the elders of the priests, covered with sackcloth, to Isaiah the prophet, the son of Amoz.'),
  ('fe92965d-cb5c-5dfb-a5db-ccf79f09c041', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 3, 3, 'They said to him, "Thus says Hezekiah, ''This day is a day of trouble, and of rebuke, and of rejection; for the children have come to the birth, and there is no strength to bring forth.'),
  ('46effd5b-33b0-5f1d-abfb-04d75cea0317', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 4, 4, 'It may be Yahweh your God will hear the words of Rabshakeh, whom the king of Assyria his master has sent to defy the living God, and will rebuke the words which Yahweh your God has heard. Therefore lift up your prayer for the remnant that is left.''"'),
  ('4c8ce6ec-8a25-53ce-a2e0-36227995d776', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 5, 5, 'So the servants of king Hezekiah came to Isaiah.'),
  ('36f47d85-a896-5097-a2d3-056ca587169f', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 6, 6, 'Isaiah said to them, "Tell your master, ''Thus says Yahweh, "Don''t be afraid of the words that you have heard, with which the servants of the king of Assyria have blasphemed me.'),
  ('6c10957f-b5f9-5bb6-a2a3-c1d8cf23450c', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 7, 7, 'Behold, I will put a spirit in him and he will hear news, and will return to his own land. I will cause him to fall by the sword in his own land."''"'),
  ('c64704ac-5ba6-5673-a5bb-3b4788dfa718', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 8, 8, 'So Rabshakeh returned, and found the king of Assyria warring against Libnah, for he had heard that he was departed from Lachish.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c2edbc4f-7eb9-58ca-a921-ad89a48af7c5', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 9, 9, 'He heard news concerning Tirhakah king of Ethiopia, "He has come out to fight against you." When he heard it, he sent messengers to Hezekiah, saying,'),
  ('7e640708-7e5a-5d81-a1d9-64e13e9099bb', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 10, 10, '"Thus you shall speak to Hezekiah king of Judah, saying, ''Don''t let your God in whom you trust deceive you, saying, "Jerusalem won''t be given into the hand of the king of Assyria."'),
  ('0ba6fb93-a731-55db-a901-4705db0e5b74', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 11, 11, 'Behold, you have heard what the kings of Assyria have done to all lands, by destroying them utterly. Shall you be delivered?'),
  ('bb4196bd-0fee-5004-ab43-c96647baf4c1', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 12, 12, 'Have the gods of the nations delivered them, which my fathers have destroyed, Gozan, Haran, Rezeph, and the children of Eden who were in Telassar?'),
  ('4e9e210a-8b1e-597e-af48-5a4c85f429bb', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 13, 13, 'Where is the king of Hamath, and the king of Arpad, and the king of the city of Sepharvaim, of Hena, and Ivvah?''"'),
  ('4c33435d-7b08-5c89-aa84-302c2f6bf4c7', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 14, 14, 'Hezekiah received the letter from the hand of the messengers and read it. Then Hezekiah went up to Yahweh''s house, and spread it before Yahweh.'),
  ('64992014-ba2f-56ce-a218-0a650b6c110c', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 15, 15, 'Hezekiah prayed to Yahweh, saying,'),
  ('663446cb-e6a8-5532-a8e3-f87b706b963d', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 16, 16, '"Yahweh of Armies, the God of Israel, who is enthroned among the cherubim, you are the God, even you alone, of all the kingdoms of the earth. You have made heaven and earth.'),
  ('368cd8d4-306e-5880-a44a-cb2bcd82efc4', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 17, 17, 'Turn your ear, Yahweh, and hear. Open your eyes, Yahweh, and behold. Hear all of the words of Sennacherib, who has sent to defy the living God.'),
  ('83925290-41f6-5d26-a8a8-68bad42bc4ae', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 18, 18, 'Truly, Yahweh, the kings of Assyria have destroyed all the countries and their land,'),
  ('0feefee1-67c4-53d5-a67a-0284607e130a', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 19, 19, 'and have cast their gods into the fire; for they were no gods, but the work of men''s hands, wood and stone; therefore they have destroyed them.'),
  ('cd055df2-42a5-5fe4-a7dc-f05a838aa7f1', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 20, 20, 'Now therefore, Yahweh our God, save us from his hand, that all the kingdoms of the earth may know that you are Yahweh, even you only."'),
  ('b559d810-5a88-5951-ae1d-6f5ff3bb4985', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 21, 21, 'Then Isaiah the son of Amoz sent to Hezekiah, saying, "Thus says Yahweh, the God of Israel, ''Because you have prayed to me against Sennacherib king of Assyria,'),
  ('6abbb120-a0fd-5a72-a6c4-7bdbf7737c3f', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 22, 22, 'this is the word which Yahweh has spoken concerning him. The virgin daughter of Zion has despised you and ridiculed you. The daughter of Jerusalem has shaken her head at you.'),
  ('f86e9148-b01a-5e84-aeff-f3feb4caf207', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 23, 23, 'Whom have you defied and blasphemed? Against whom have you exalted your voice and lifted up your eyes on high? Against the Holy One of Israel.'),
  ('e96dc101-9980-53c0-ae79-e01355fd3ddb', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 24, 24, 'By your servants, have you defied the Lord, and have said, "With the multitude of my chariots I have come up to the height of the mountains, to the innermost parts of Lebanon. I will cut down its tall cedars and its choice fir trees. I will enter into its farthest height, the forest of its fruitful field.'),
  ('765a2ab1-46b4-57ad-a141-ee89e2245dde', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 25, 25, 'I have dug and drunk water, and with the sole of my feet I will dry up all the rivers of Egypt."'),
  ('bbba1251-4117-5025-ad5e-53989c0ddde4', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 26, 26, 'Have you not heard how I have done it long ago, and formed it in ancient times? Now I have brought it to pass, that it should be yours to destroy fortified cities, turning them into ruinous heaps.'),
  ('19dc1269-5c42-586a-ac29-364e11996519', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 27, 27, 'Therefore their inhabitants had little power. They were dismayed and confounded. They were like the grass of the field, and like the green herb, like the grass on the housetops, and like a field before its crop has grown.'),
  ('292d8042-4eb2-5781-aa78-52956947d7f4', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 28, 28, 'But I know your sitting down, your going out, your coming in, and your raging against me.'),
  ('dc3787b5-2f04-5b17-a84a-1e7cdd10ea5b', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 29, 29, 'Because of your raging against me, and because your arrogance has come up into my ears, therefore will I put my hook in your nose and my bridle in your lips, and I will turn you back by the way by which you came.'),
  ('04ed782a-b039-52d1-a0aa-543aa358cadf', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 30, 30, 'This shall be the sign to you. You will eat this year that which grows of itself, and in the second year that which springs from the same; and in the third year sow and reap and plant vineyards, and eat their fruit.'),
  ('0bf4c967-eab1-52ad-a0f9-baf21538adf1', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 31, 31, 'The remnant that is escaped of the house of Judah will again take root downward, and bear fruit upward.'),
  ('51f04e8d-e5b4-5cfd-a97d-2342ef2670c4', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 32, 32, 'For out of Jerusalem a remnant will go forth, and survivors will escape from Mount Zion. The zeal of Yahweh of Armies will perform this.'''),
  ('7031fcd1-8697-51f5-a169-dcf695d7589c', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 33, 33, 'Therefore thus says Yahweh concerning the king of Assyria, ''He will not come to this city, nor shoot an arrow there, neither will he come before it with shield, nor cast up a mound against it.'),
  ('4cd55b94-5752-51ed-a9d1-7da07722677c', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 34, 34, 'By the way that he came, by the same he shall return, and he shall not come to this city,'' says Yahweh.'),
  ('8bba1f06-8c5e-5e9a-aa11-1d213606d5b7', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 35, 35, '''For I will defend this city to save it, for my own sake, and for my servant David''s sake.''"'),
  ('a9d7c743-1e77-531e-ab92-e819f895439f', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 36, 36, 'The angel of Yahweh went out and struck one hundred and eighty-five thousand men in the camp of the Assyrians. When men arose early in the morning, behold, these were all dead bodies.'),
  ('4dd2c350-7281-505e-a026-ad76117d49a9', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 37, 37, 'So Sennacherib king of Assyria departed, went away, returned to Nineveh, and stayed there.'),
  ('7376295d-bbd9-54e1-a6f4-e4c56197ab98', 'eb316cf6-a52a-5f66-a749-2a339d6b3617', NULL, 38, 38, 'It happened, as he was worshipping in the house of Nisroch his god, that Adrammelech and Sharezer his sons struck him with the sword; and they escaped into the land of Ararat. Esar Haddon his son reigned in his place.'),
  ('064d6f92-2e6b-51d8-a0ae-62fb74308746', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 1, 1, 'In those days was Hezekiah sick and near death. Isaiah the prophet, the son of Amoz, came to him, and said to him, "Thus says Yahweh, ''Set your house in order, for you will die, and not live.''"'),
  ('59dca468-1870-5657-a51d-969c6eb2084b', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 2, 2, 'Then Hezekiah turned his face to the wall and prayed to Yahweh,'),
  ('3d803a15-2c6c-5207-a743-82443256159f', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 3, 3, 'and said, "Remember now, Yahweh, I beg you, how I have walked before you in truth and with a perfect heart, and have done that which is good in your sight." Hezekiah wept bitterly.'),
  ('e27ee001-c3dd-5d87-a1ee-7bd7b51932a5', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 4, 4, 'Then the word of Yahweh came to Isaiah, saying,'),
  ('a960e36b-c867-5dc4-a0bf-903d6d70122d', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 5, 5, '"Go, and tell Hezekiah, ''Thus says Yahweh, the God of David your father, "I have heard your prayer. I have seen your tears. Behold, I will add fifteen years to your life.'),
  ('f81e958e-294e-56e3-aad5-c9bc90e15166', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 6, 6, 'I will deliver you and this city out of the hand of the king of Assyria, and I will defend this city.'),
  ('d12ca224-ef89-5fc0-ad05-e399736a66fa', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 7, 7, 'This shall be the sign to you from Yahweh, that Yahweh will do this thing that he has spoken.'),
  ('d67426fb-645a-5a18-a616-e7ec2d9a6dce', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 8, 8, 'Behold, I will cause the shadow on the sundial, which has gone down on the sundial of Ahaz with the sun, to return backward ten steps. So the sun returned ten steps on the sundial on which it had gone down."''"'),
  ('b743bc92-68a4-58b7-a600-0630cea93b88', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 9, 9, 'The writing of Hezekiah king of Judah, when he had been sick, and had recovered of his sickness.'),
  ('2d03a438-62fb-56a4-ad7b-519b77c0468b', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 10, 10, 'I said, "In the middle of my life I go into the gates of Sheol. I am deprived of the residue of my years."'),
  ('9785a23c-61f5-5506-aa0d-730c005d1c9a', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 11, 11, 'I said, "I won''t see Yah, Yah in the land of the living. I will see man no more with the inhabitants of the world.'),
  ('83caafd8-dfa9-503c-aed1-be95d092fef2', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 12, 12, 'My dwelling is removed, and is carried away from me like a shepherd''s tent. I have rolled up, like a weaver, my life. He will cut me off from the loom. From day even to night you will make an end of me.'),
  ('0e611e8b-67cb-5588-aaf3-efe1876331c8', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 13, 13, 'I waited patiently until morning. He breaks all my bones like a lion. From day even to night you will make an end of me.'),
  ('7151b637-3e6d-5a13-a531-4732c0cbf400', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 14, 14, 'I chattered like a swallow or a crane. I moaned like a dove. My eyes weaken looking upward. Lord, I am oppressed. Be my security."'),
  ('fbb39668-6bf2-54ef-a243-23f44c2e1420', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 15, 15, 'What will I say? He has both spoken to me, and himself has done it. I will walk carefully all my years because of the anguish of my soul.'),
  ('e43ab0e7-7fa0-5891-ae85-f7b52966f7e4', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 16, 16, 'Lord, men live by these things; and my spirit finds life in all of them: you restore me, and cause me to live.'),
  ('24e0a171-6bd5-5f13-a5af-9fa49200bb31', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 17, 17, 'Behold, for peace I had great anguish, but you have in love for my soul delivered it from the pit of corruption; for you have cast all my sins behind your back.'),
  ('f6b09e78-6cfc-5ec8-ad55-7659f18b1c0c', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 18, 18, 'For Sheol can''t praise you. Death can''t celebrate you. Those who go down into the pit can''t hope for your truth.'),
  ('77579909-ca6c-5130-a449-d9405bfbb3e1', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 19, 19, 'The living, the living, he shall praise you, as I do this day. The father shall make known your truth to the children.'),
  ('7b2a8b28-4800-53e8-aa70-5870430cc560', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 20, 20, 'Yahweh will save me. Therefore we will sing my songs with stringed instruments all the days of our life in the house of Yahweh.'),
  ('bbbb0e17-5363-5d8d-a260-a7087a1c68cc', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 21, 21, 'Now Isaiah had said, "Let them take a cake of figs, and lay it for a poultice on the boil, and he shall recover."'),
  ('caa2ff0c-ae0f-512d-adde-3b912ba1e241', 'baa3874c-f7ed-5165-a2e8-90f65406ae5f', NULL, 22, 22, 'Hezekiah also had said, "What is the sign that I will go up to the house of Yahweh?"'),
  ('a8661a30-5877-5e2c-af21-ccfd910408d5', 'fc31cc7c-4d20-556f-aa94-3f2c50184f4b', NULL, 1, 1, 'At that time, Merodach Baladan the son of Baladan, king of Babylon, sent letters and a present to Hezekiah; for he heard that he had been sick, and had recovered.'),
  ('819723e8-6cf3-5bfb-a256-6aa76cf92ff1', 'fc31cc7c-4d20-556f-aa94-3f2c50184f4b', NULL, 2, 2, 'Hezekiah was pleased with them, and showed them the house of his precious things, the silver, and the gold, the spices, and the precious oil, and all the house of his armor, and all that was found in his treasures. There was nothing in his house, nor in all his dominion, that Hezekiah didn''t show them.'),
  ('c2862d4a-22e7-5299-aa36-8a64a34d8299', 'fc31cc7c-4d20-556f-aa94-3f2c50184f4b', NULL, 3, 3, 'Then Isaiah the prophet came to king Hezekiah, and asked him, "What did these men say? Where did they come from to you?" Hezekiah said, "They have come from a country far from me, even from Babylon."'),
  ('fc4fcad6-de67-52a5-a5e4-7869e0ca1ac4', 'fc31cc7c-4d20-556f-aa94-3f2c50184f4b', NULL, 4, 4, 'Then he asked, "What have they seen in your house?" Hezekiah answered, "They have seen all that is in my house. There is nothing among my treasures that I have not shown them."'),
  ('622b233c-c682-597c-a918-b839e8ef3e4e', 'fc31cc7c-4d20-556f-aa94-3f2c50184f4b', NULL, 5, 5, 'Then Isaiah said to Hezekiah, "Hear the word of Yahweh of Armies:'),
  ('ac4eb8ac-4c92-56f0-a8b0-1fee5b3ce0dd', 'fc31cc7c-4d20-556f-aa94-3f2c50184f4b', NULL, 6, 6, '''Behold, the days are coming when all that is in your house, and that which your fathers have stored up until this day, will be carried to Babylon. Nothing will be left,'' says Yahweh.'),
  ('500aed1f-c351-5c4d-abf9-ac739332155f', 'fc31cc7c-4d20-556f-aa94-3f2c50184f4b', NULL, 7, 7, '''They will take away your sons who will issue from you, whom you shall father, and they will be eunuchs in the king of Babylon''s palace.''"'),
  ('c323d152-ef41-514b-aba1-182752c99af1', 'fc31cc7c-4d20-556f-aa94-3f2c50184f4b', NULL, 8, 8, 'Then Hezekiah said to Isaiah, "Yahweh''s word which you have spoken is good." He said moreover, "For there will be peace and truth in my days."'),
  ('63e66b76-c98f-5b4f-a659-7a89238e948d', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 1, 1, '"Comfort, comfort my people," says your God.'),
  ('d24878db-67ab-58f0-ad1e-98369a3a4f1b', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 2, 2, '"Speak comfortably to Jerusalem; and call out to her that her warfare is accomplished, that her iniquity is pardoned, that she has received of Yahweh''s hand double for all her sins."'),
  ('898cab7d-fc68-5ea6-a57c-5a9e783c1d8d', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 3, 3, 'The voice of one who calls out, "Prepare the way of Yahweh in the wilderness! Make a level highway in the desert for our God.'),
  ('793abce9-0c6e-55e4-a5c6-410f24fa8ec3', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 4, 4, 'Every valley shall be exalted, and every mountain and hill shall be made low. The uneven shall be made level, and the rough places a plain.'),
  ('608e1ee9-bd7e-597f-ac2f-1955729c58ea', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 5, 5, 'The glory of Yahweh shall be revealed, and all flesh shall see it together; for the mouth of Yahweh has spoken it."'),
  ('ea0f712f-24df-51d2-aed3-e2fe088e32c9', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 6, 6, 'The voice of one saying, "Cry!" One said, "What shall I cry?" "All flesh is like grass, and all its glory is like the flower of the field.'),
  ('5a596282-1621-55a0-a7f2-393a543f9307', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 7, 7, 'The grass withers, the flower fades, because Yahweh''s breath blows on it. Surely the people are like grass.'),
  ('59be7044-279e-51a4-a2d6-222390b80181', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 8, 8, 'The grass withers, the flower fades; but the word of our God stands forever."'),
  ('5fe308ec-a075-51f0-a75d-1f984cb17444', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 9, 9, 'You who tell good news to Zion, go up on a high mountain. You who tell good news to Jerusalem, lift up your voice with strength. Lift it up. Don''t be afraid. Say to the cities of Judah, "Behold, your God!"'),
  ('1ee27501-50ef-5c7b-a79d-cf594d74f2f8', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 10, 10, 'Behold, the Lord Yahweh will come as a mighty one, and his arm will rule for him. Behold, his reward is with him, and his recompense before him.'),
  ('d5f0edd5-be63-5d77-a46c-f53e3d083b3e', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 11, 11, 'He will feed his flock like a shepherd. He will gather the lambs in his arm, and carry them in his bosom. He will gently lead those who have their young.'),
  ('3339d963-2d63-50e5-a838-56d885daa5de', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 12, 12, 'Who has measured the waters in the hollow of his hand, and marked off the sky with his span, and calculated the dust of the earth in a measure, and weighed the mountains in scales, and the hills in a balance?'),
  ('29dfcd27-d211-5f8a-af61-833a04ed9f2a', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 13, 13, 'Who has directed the Spirit of Yahweh, or has taught him as his counselor?'),
  ('f1d4558d-ddda-53d4-a7f3-0e44ba2432e3', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 14, 14, 'Who did he take counsel with, and who instructed him, and taught him in the path of justice, and taught him knowledge, and showed him the way of understanding?'),
  ('025504a9-c44c-5708-aa1f-de08b90f5bd3', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 15, 15, 'Behold, the nations are like a drop in a bucket, and are regarded as a speck of dust on a balance. Behold, he lifts up the islands like a very little thing.'),
  ('7b91579e-95af-5ac4-a41c-dfdfc3a8d4a3', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 16, 16, 'Lebanon is not sufficient to burn, nor its animals sufficient for a burnt offering.'),
  ('54e4c3c1-cf22-5105-a403-c9de186eaea3', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 17, 17, 'All the nations are like nothing before him. They are regarded by him as less than nothing, and vanity.'),
  ('f7ce0848-7da5-52b5-a155-af72377835ea', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 18, 18, 'To whom then will you liken God? Or what likeness will you compare to him?'),
  ('f68f98ec-d5d9-5eb6-a2e8-f97f7d9ae8f3', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 19, 19, 'A workman has cast an image, and the goldsmith overlays it with gold, and casts silver chains for it.'),
  ('18aa9b11-7039-564f-a816-6312ee119f10', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 20, 20, 'He who is too impoverished for such an offering chooses a tree that will not rot. He seeks a skillful workman to set up an engraved image for him that will not be moved.'),
  ('de450e62-64a0-57f3-acf3-eef1405c203a', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 21, 21, 'Haven''t you known? Haven''t you heard, yet? Haven''t you been told from the beginning? Haven''t you understood from the foundations of the earth?'),
  ('2b3944a5-0b91-593c-a26a-ee6066fe1e6d', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 22, 22, 'It is he who sits above the circle of the earth, and its inhabitants are like grasshoppers; who stretches out the heavens like a curtain, and spreads them out like a tent to dwell in;'),
  ('8434331f-e39b-53a1-ab8b-f426eef1d924', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 23, 23, 'who brings princes to nothing; who makes the judges of the earth like meaningless.'),
  ('975094af-304c-5d90-acb0-3c721b96eaff', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 24, 24, 'They are planted scarcely. They are sown scarcely. Their stock has scarcely taken root in the ground. He merely blows on them, and they wither, and the whirlwind takes them away as stubble.'),
  ('6c64d087-0b14-5b6f-a79a-d5974e06bb4a', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 25, 25, '"To whom then will you liken me? Who is my equal?" says the Holy One.'),
  ('34830755-5c3a-5065-ab36-cd26e7c80f71', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 26, 26, 'Lift up your eyes on high, and see who has created these, who brings out their army by number. He calls them all by name. by the greatness of his might, and because he is strong in power, Not one is lacking.'),
  ('a7b2739a-c648-5e36-a440-edccf55932ce', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 27, 27, 'Why do you say, Jacob, and speak, Israel, "My way is hidden from Yahweh, and the justice due me is disregarded by my God?"'),
  ('444737ef-aacf-555c-a030-929b6542facc', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 28, 28, 'Haven''t you known? Haven''t you heard? The everlasting God, Yahweh, The Creator of the ends of the earth, doesn''t faint. He isn''t weary. His understanding is unsearchable.'),
  ('1671e9a1-f99e-56b8-a13c-47ee8440f818', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 29, 29, 'He gives power to the weak. He increases the strength of him who has no might.'),
  ('3ab4200f-8938-53a5-a781-3872d760f233', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 30, 30, 'Even the youths faint and get weary, and the young men utterly fall;'),
  ('337a0ca9-6c1d-5454-a137-3f9d18234748', 'd55cde3c-acb3-5ddb-a973-62826a52fc8a', NULL, 31, 31, 'But those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.'),
  ('11ca202c-1508-56b0-afa5-d949bfc665f5', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 1, 1, '"Keep silent before me, islands, and let the peoples renew their strength. Let them come near, then let them speak. Let''s meet together for judgment.'),
  ('ef27ca31-b073-5f0d-a58f-d0311d02dd99', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 2, 2, 'Who has raised up one from the east? Who called him to his foot in righteousness? He hands over nations to him, and makes him rule over kings. He gives them like the dust to his sword, like the driven stubble to his bow.'),
  ('da5c1760-9eff-5751-ab72-05f8e7d06744', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 3, 3, 'He pursues them, and passes by safely, Even by a way that he had not gone with his feet.'),
  ('690b069b-b7a1-5d93-abc7-1ccfd8468d9c', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 4, 4, 'Who has worked and done it, calling the generations from the beginning? I, Yahweh, the first, and with the last, I am he."'),
  ('958857ff-5172-5c4c-a622-9aa6a50179a7', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 5, 5, 'The islands have seen, and fear. The ends of the earth tremble. They approach, and come.'),
  ('a1665b72-98d8-5ffa-af1a-c8c79b10a737', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 6, 6, 'Everyone helps his neighbor. They say to their brothers, "Be strong!"'),
  ('1b185788-7349-578e-aab5-8beb11de6f4c', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 7, 7, 'So the carpenter encourages the goldsmith. He who smoothes with the hammer encourages him who strikes the anvil, saying of the soldering, "It is good;" and he fastens it with nails, that it might not totter.'),
  ('02c86373-c187-5048-a071-f18ad19ab6f4', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 8, 8, '"But you, Israel, my servant, Jacob whom I have chosen, the seed of Abraham my friend,'),
  ('ede669e8-e050-5e0b-a919-fccfb644e5ee', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 9, 9, 'You whom I have taken hold of from the ends of the earth, and called from its corners, and said to you, ''You are my servant, I have chosen you and not cast you away;'''),
  ('09f38e92-3b48-5c39-a35c-a9ed71707a6a', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 10, 10, 'Don''t you be afraid, for I am with you. Don''t be dismayed, for I am your God. I will strengthen you. Yes, I will help you. Yes, I will uphold you with the right hand of my righteousness.'),
  ('26ac7067-38f5-514b-a5af-0550b16445d1', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 11, 11, 'Behold, all those who are incensed against you will be disappointed and confounded. Those who strive with you will be like nothing, and shall perish.'),
  ('e09fbfd0-a250-5b8d-aea3-c0585448ac9f', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 12, 12, 'You will seek them, and won''t find them, even those who contend with you. Those who war against you will be as nothing, as a non-existent thing.'),
  ('30848d0b-0fd9-5e7b-a4c1-ee2eb890348e', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 13, 13, 'For I, Yahweh your God, will hold your right hand, saying to you, ''Don''t be afraid. I will help you.'''),
  ('e62775b2-5377-5e9b-a056-18b9f00f0dfb', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 14, 14, 'Don''t be afraid, you worm Jacob, and you men of Israel. I will help you," says Yahweh, "and your Redeemer is the Holy One of Israel.'),
  ('098a1f14-3053-5db8-a75a-ece403a1a57d', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 15, 15, 'Behold, I have made you into a new sharp threshing instrument with teeth. You will thresh the mountains, and beat them small, and will make the hills like chaff.'),
  ('8766a37d-8a20-57c0-a087-debad0fef891', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 16, 16, 'You will winnow them, and the wind will carry them away, and the whirlwind will scatter them. You will rejoice in Yahweh. You will glory in the Holy One of Israel.'),
  ('81f7ded2-efab-5219-a581-6842badda164', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 17, 17, 'The poor and needy seek water, and there is none. Their tongue fails for thirst. I, Yahweh, will answer them. I, the God of Israel, will not forsake them.'),
  ('72d5622d-a3c5-506c-a209-f66c82e30893', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 18, 18, 'I will open rivers on the bare heights, and springs in the midst of the valleys. I will make the wilderness a pool of water, and the dry land springs of water.'),
  ('545d842b-3584-5876-a235-d90886bf27aa', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 19, 19, 'I will put cedar, acacia, myrtle, and oil trees in the wilderness. I will set fir trees, pine, and box trees together in the desert;'),
  ('60a19fd1-edf4-5f83-a767-5e8072795a41', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 20, 20, 'that they may see, know, consider, and understand together, that the hand of Yahweh has done this, and the Holy One of Israel has created it.'),
  ('4608140c-79b5-571f-ab26-32cdbf572eef', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 21, 21, 'Produce your cause," says Yahweh. "Bring forth your strong reasons," says the King of Jacob.'),
  ('f0f8dced-1737-5de9-aaf4-c73f85442ff8', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 22, 22, '"Let them announce, and declare to us what shall happen. Declare the former things, what they are, that we may consider them, and know the latter end of them; or show us things to come.'),
  ('dc406040-820f-5bfb-a696-253963bf2fd4', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 23, 23, 'Declare the things that are to come hereafter, that we may know that you are gods. Yes, do good, or do evil, that we may be dismayed, and see it together.'),
  ('0cdc4165-1d83-5f11-a4c9-dd70fda02b27', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 24, 24, 'Behold, you are of nothing, and your work is of nothing. He who chooses you is an abomination.'),
  ('ee2783f6-7a8e-5ef9-a68f-d8ad657b0ce3', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 25, 25, '"I have raised up one from the north, and he has come; from the rising of the sun, one who calls on my name; and he shall come on rulers as on mortar, and as the potter treads clay.'),
  ('a2d6b4cd-0f17-59f8-aece-0262b2707792', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 26, 26, 'Who has declared it from the beginning, that we may know? And before, that we may say, ''He is right?'' Surely, there is no one who declares. Surely, there is no one who shows. Surely, there is no one who hears your words.'),
  ('59e382b6-4edd-5abf-a2b1-14f4637bd6fa', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 27, 27, 'I am the first to say to Zion, ''Behold, look at them;'' and I will give one who brings good news to Jerusalem.'),
  ('66f59cca-de3f-5f7a-ad34-919a3983be53', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 28, 28, 'When I look, there is no man; even among them there is no counselor who, when I ask of them, can answer a word.'),
  ('b872a0b1-c862-58e2-a1f5-902c22f20ff1', '0db961ac-befe-5813-a8bd-5136cb5a9836', NULL, 29, 29, 'Behold, all of them, their works are vanity and nothing. Their molten images are wind and confusion.'),
  ('4ce6368a-07cb-55c9-a73d-39281c1977bd', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 1, 1, '"Behold, my servant, whom I uphold; my chosen, in whom my soul delights-- I have put my Spirit on him. He will bring justice to the nations.'),
  ('6115b7f3-4ca5-52a1-aaf9-44ea126aa525', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 2, 2, 'He will not shout, nor raise his voice, nor cause it to be heard in the street.'),
  ('622dea2a-505f-5c02-a7d6-98552468f91c', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 3, 3, 'He won''t break a bruised reed. He won''t quench a dimly burning wick. He will faithfully bring justice.'),
  ('3d1ea67e-0209-5939-a220-e8b02c23b5e2', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 4, 4, 'He will not fail nor be discouraged, until he has set justice in the earth, and the islands will wait for his law."'),
  ('d61c60d8-064b-5be0-accf-5f5fd99296f1', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 5, 5, 'Thus says God Yahweh, he who created the heavens and stretched them out, he who spread out the earth and that which comes out of it, he who gives breath to its people and spirit to those who walk in it.'),
  ('6e481e11-eb34-5e65-a60c-2d39779887c1', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 6, 6, '"I, Yahweh, have called you in righteousness, and will hold your hand, and will keep you, and make you a covenant for the people, as a light for the nations;'),
  ('476604a8-4baf-5f07-a782-68bd56f76030', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 7, 7, 'to open the blind eyes, to bring the prisoners out of the dungeon, and those who sit in darkness out of the prison.'),
  ('2048767a-8b00-594a-a3f9-8e9cf7c3f474', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 8, 8, '"I am Yahweh. That is my name. I will not give my glory to another, nor my praise to engraved images.'),
  ('dcf1ffa5-9aef-577c-a70f-b805c115c262', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 9, 9, 'Behold, the former things have happened, and I declare new things. I tell you about them before they come up."'),
  ('a9dcf865-ec90-5a85-ae02-14edc6b12422', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 10, 10, 'Sing to Yahweh a new song, and his praise from the end of the earth, you who go down to the sea, and all that is therein, the islands and their inhabitants.'),
  ('6d175e84-f5a1-59fd-a7c2-7d43230c0051', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 11, 11, 'Let the wilderness and its cities raise their voices, with the villages that Kedar inhabits. Let the inhabitants of Sela sing. Let them shout from the top of the mountains!'),
  ('3d07c56b-cb53-508c-ad48-680b6faa7261', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 12, 12, 'Let them give glory to Yahweh, and declare his praise in the islands.'),
  ('3de31e79-c536-50c6-afc5-4171953c0921', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 13, 13, 'Yahweh will go out like a mighty man. He will stir up zeal like a man of war. He will raise a war cry. Yes, he will shout aloud. He will triumph over his enemies.'),
  ('8a7d9298-4e3a-5376-a17d-c826390f2c95', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 14, 14, '"I have been silent a long time. I have been quiet and restrained myself. Now I will cry out like a travailing woman. I will both gasp and pant.'),
  ('82c743ab-43de-5cb8-a88e-f7ddd0de5619', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 15, 15, 'I will destroy mountains and hills, and dry up all their herbs. I will make the rivers islands, and will dry up the pools.'),
  ('fe9528ac-23df-5e01-a7ad-0ee9428d0011', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 16, 16, 'I will bring the blind by a way that they don''t know. I will lead them in paths that they don''t know. I will make darkness light before them, and crooked places straight. I will do these things, and I will not forsake them.'),
  ('092561b5-9966-5833-ab04-4a3d6c441454', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 17, 17, '"Those who trust in engraved images, who tell molten images, ''You are our gods'' will be turned back. They will be utterly disappointed.'),
  ('a88f10b9-a901-56f7-a661-869aaa325310', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 18, 18, '"Hear, you deaf, and look, you blind, that you may see.'),
  ('d586cd81-e1d6-53b3-a3ae-938a253b9da0', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 19, 19, 'Who is blind, but my servant? Or who is as deaf as my messenger whom I send? Who is as blind as he who is at peace, and as blind as Yahweh''s servant?'),
  ('ecd55f2d-e7bb-59c2-a573-1991d8553a29', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 20, 20, 'You see many things, but don''t observe. His ears are open, but he doesn''t listen.'),
  ('3e406664-05db-54d5-a26e-1e51dffce9cc', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 21, 21, 'It pleased Yahweh, for his righteousness'' sake, to magnify the law, and make it honorable.'),
  ('7fea315a-0112-524f-a01a-44588369f430', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 22, 22, 'But this is a robbed and plundered people. All of them are snared in holes, and they are hidden in prisons. They have become a prey, and no one delivers; and a spoil, and no one says, ''Restore them!'''),
  ('2977dacb-fe49-5092-a77b-527230dc3674', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 23, 23, 'Who is there among you who will give ear to this? Who will listen and hear for the time to come?'),
  ('6cd5d4fe-5362-5e6d-a1ab-0470580bead4', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 24, 24, 'Who gave Jacob as plunder, and Israel to the robbers? Didn''t Yahweh, he against whom we have sinned? For they would not walk in his ways, and they disobeyed his law.'),
  ('a55bf722-c4d9-50b3-a675-ea2df5ba7a4e', '90835c46-494e-56a0-abeb-3cfbd2d8d621', NULL, 25, 25, 'Therefore he poured the fierceness of his anger on him, and the strength of battle; and it set him on fire all around, but he didn''t know; and it burned him, but he didn''t take it to heart."'),
  ('fcc04e5e-76d4-5b1f-aa6a-d3c2348b7146', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 1, 1, 'But now thus says Yahweh who created you, Jacob, and he who formed you, Israel: "Don''t be afraid, for I have redeemed you. I have called you by your name. You are mine.'),
  ('437f997d-182b-57dd-aca1-912104e90ef0', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 2, 2, 'When you pass through the waters, I will be with you; and through the rivers, they will not overflow you. When you walk through the fire, you will not be burned, and flame will not scorch you.'),
  ('8c7bc2a0-2dd8-56ec-aa26-0d434b940dcb', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 3, 3, 'For I am Yahweh your God, the Holy One of Israel, your Savior. I have given Egypt as your ransom, Ethiopia and Seba in your place.'),
  ('380fc373-bace-5a6a-a8c0-a5285b6dc9e6', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 4, 4, 'Since you have been precious and honored in my sight, and I have loved you; therefore I will give people in your place, and nations instead of your life.'),
  ('81959a31-fa76-5176-a966-d1f4f3da5ae1', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 5, 5, 'Don''t be afraid; for I am with you. I will bring your seed from the east, and gather you from the west.'),
  ('2c6ced21-91e6-5284-acf2-544d91391462', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 6, 6, 'I will tell the north, ''Give them up!'' and tell the south, ''Don''t hold them back! Bring my sons from far, and my daughters from the ends of the earth--'),
  ('08ef0393-b4fe-5e19-a167-9b0edcdc1841', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 7, 7, 'everyone who is called by my name, and whom I have created for my glory, whom I have formed, yes, whom I have made.''"'),
  ('a7fb7bf0-fe18-5d3e-ac86-01e6e618e67e', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 8, 8, 'Bring out the blind people who have eyes, and the deaf who have ears.'),
  ('5732d72d-7d33-542b-afa4-c7a2f3d035cb', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 9, 9, 'Let all the nations be gathered together, and let the peoples be assembled. Who among them can declare this, and show us former things? Let them bring their witnesses, that they may be justified; or let them hear, and say, "That is true."'),
  ('c01310ab-c1dc-5216-aaf7-d24bb5e8cfaf', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 10, 10, '"You are my witnesses," says Yahweh, "With my servant whom I have chosen; that you may know and believe me, and understand that I am he. Before me there was no God formed, neither will there be after me.'),
  ('c02409ac-987c-5464-a3f5-3506bd8c6240', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 11, 11, 'I myself am Yahweh; and besides me there is no savior.'),
  ('575fe0b9-eec2-537e-a109-36270682ab6d', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 12, 12, 'I have declared, I have saved, and I have shown; and there was no strange god among you. Therefore you are my witnesses," says Yahweh, "and I am God.'),
  ('9c5d5246-73e5-5f1a-a19e-794a6c61f272', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 13, 13, 'Yes, since the day was I am he; and there is no one who can deliver out of my hand. I will work, and who can hinder it?"'),
  ('7c9e016a-87e2-5127-a2a7-fb630c85d841', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 14, 14, 'Thus says Yahweh, your Redeemer, the Holy One of Israel: "For your sake, I have sent to Babylon, and I will bring all of them down as fugitives, even the Chaldeans, in the ships of their rejoicing.'),
  ('60e49265-5e1b-5035-aa9b-0bdff70cc50b', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 15, 15, 'I am Yahweh, your Holy One, the Creator of Israel, your King."'),
  ('bddb11f3-8aec-5c08-a1e5-67d5d5627f37', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 16, 16, 'Thus says Yahweh, who makes a way in the sea, and a path in the mighty waters;'),
  ('44920dff-d715-53ff-a46b-4d5d8bb2115b', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 17, 17, 'who brings forth the chariot and horse, the army and the mighty man (they lie down together, they shall not rise; they are extinct, they are quenched like a wick):'),
  ('00dbe6f8-7d6d-54a4-a06a-549470b603e9', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 18, 18, '"Don''t remember the former things, and don''t consider the things of old.'),
  ('dc33085a-3f98-52d9-ad20-f57e4ff1ce37', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 19, 19, 'Behold, I will do a new thing. It springs forth now. Don''t you know it? I will even make a way in the wilderness, and rivers in the desert.'),
  ('d3350dc7-683b-5e6b-a3e1-46ffbffadfdf', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 20, 20, 'The animals of the field shall honor me, the jackals and the ostriches; because I give water in the wilderness and rivers in the desert, to give drink to my people, my chosen,'),
  ('615589e4-47eb-583d-aab0-b11208c64770', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 21, 21, 'the people which I formed for myself, that they might set forth my praise.'),
  ('c490ce91-9f3a-5197-aa65-331cf31f0f9c', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 22, 22, 'Yet you have not called on me, Jacob; but you have been weary of me, Israel.'),
  ('31afb155-2207-5c8f-a206-3b23511adaeb', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 23, 23, 'You have not brought me of your sheep for burnt offerings; neither have you honored me with your sacrifices. I have not burdened you with offerings, nor wearied you with frankincense.'),
  ('8f2434c2-0a91-55b2-ae63-f1a9b5bb04a1', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 24, 24, 'You have bought me no sweet cane with money, nor have you filled me with the fat of your sacrifices; but you have burdened me with your sins. You have wearied me with your iniquities.'),
  ('0738e1b7-70aa-5e69-ab96-ccef1a057ff3', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 25, 25, 'I, even I, am he who blots out your transgressions for my own sake; and I will not remember your sins.'),
  ('09bc8bbb-114b-5ee0-a8e0-30aa10bfe935', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 26, 26, 'Put me in remembrance. Let us plead together. Set forth your case, that you may be justified.'),
  ('611a8c7c-2cbf-5795-aac8-54285040fa21', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 27, 27, 'Your first father sinned, and your teachers have transgressed against me.'),
  ('84d46270-6b0e-535a-a4ef-0423d6fbe09d', '7274116a-9ff6-5c51-a4e7-92d520d09e40', NULL, 28, 28, 'Therefore I will profane the princes of the sanctuary; and I will make Jacob a curse, and Israel an insult."'),
  ('a5c718a8-a3db-5993-a896-d90adf64d869', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 1, 1, 'Yet listen now, Jacob my servant, and Israel, whom I have chosen.'),
  ('a60eab38-5d1c-5ce9-a9a2-5bba98c3a9e1', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 2, 2, 'This is what Yahweh who made you, and formed you from the womb, who will help you says: "Don''t be afraid, Jacob my servant; and you, Jeshurun, whom I have chosen.'),
  ('fdac2315-b92c-5027-a802-d9fc34d1e056', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 3, 3, 'For I will pour water on him who is thirsty, and streams on the dry ground. I will pour my Spirit on your seed, and my blessing on your offspring:'),
  ('f9aad955-4d6b-51ce-a753-da510933617d', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 4, 4, 'and they will spring up among the grass, as willows by the watercourses.'),
  ('e9043bec-2f9e-5173-a1fc-51f428926c26', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 5, 5, 'One will say, ''I am Yahweh''s;'' and another will be called by the name of Jacob; and another will write with his hand ''to Yahweh,'' and honor the name of Israel."'),
  ('29a4a1a6-556d-55bd-afde-c31873b2206c', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 6, 6, 'This is what Yahweh, the King of Israel, and his Redeemer, Yahweh of Armies, says: "I am the first, and I am the last; and besides me there is no God.'),
  ('bc60ae8d-825e-58d3-a1ca-d4eb9a6ca58c', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 7, 7, 'Who is like me? Who will call, and will declare it, and set it in order for me, since I established the ancient people? Let them declare the things that are coming, and that will happen.'),
  ('be8f2867-fedd-5e5d-a26a-2ed862865044', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 8, 8, 'Don''t fear, neither be afraid. Haven''t I declared it to you long ago, and shown it? You are my witnesses. Is there a God besides me? Indeed, there is not. I don''t know any other Rock."'),
  ('616de0e1-6f1e-546c-a9bb-c8632a18bcfa', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 9, 9, 'Everyone who makes an engraved image is vain. The things that they delight in will not profit. Their own witnesses don''t see, nor know, that they may be disappointed.'),
  ('007eb18c-fa9a-58bd-acc7-7a17d2458dc1', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 10, 10, 'Who has fashioned a god, or molds an image that is profitable for nothing?'),
  ('30fa5e5d-8f04-5a7c-ad47-356e8ac6beea', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 11, 11, 'Behold, all his fellows will be disappointed; and the workmen are mere men. Let them all be gathered together. Let them stand up. They will fear. They will be put to shame together.'),
  ('d7c3e272-4afe-5401-a2ab-1e9313b79dd9', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 12, 12, 'The blacksmith takes an axe, works in the coals, fashions it with hammers, and works it with his strong arm. He is hungry, and his strength fails; he drinks no water, and is faint.'),
  ('8b9414a5-d063-5462-af33-10c8956a93b3', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 13, 13, 'The carpenter stretches out a line. He marks it out with a pencil. He shapes it with planes. He marks it out with compasses, and shapes it like the figure of a man, with the beauty of a man, to reside in a house.'),
  ('b398a1bb-8ad1-5840-a10d-7b633755cb6c', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 14, 14, 'He cuts down cedars for himself, and takes the cypress and the oak, and strengthens for himself one among the trees of the forest. He plants a fir tree, and the rain nourishes it.'),
  ('24919042-8d20-5b0f-afb5-9f6c17eea8e9', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 15, 15, 'Then it will be for a man to burn; and he takes some of it, and warms himself. Yes, he burns it, and bakes bread. Yes, he makes a god, and worships it; he makes it an engraved image, and falls down to it.'),
  ('2ff58f21-cfca-5833-a6b8-ee260b0104a0', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 16, 16, 'He burns part of it in the fire. With part of it, he eats meat. He roasts a roast, and is satisfied. Yes, he warms himself, and says, "Aha! I am warm. I have seen the fire."'),
  ('1de99f5d-31b9-5876-a503-3bf4e1fe6346', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 17, 17, 'The rest of it he makes into a god, even his engraved image. He bows down to it and worships, and prays to it, and says, "Deliver me; for you are my god!"'),
  ('c0d66ed2-7c4d-5ea2-a1c2-0cb20aa4f9c8', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 18, 18, 'They don''t know, neither do they consider: for he has shut their eyes, that they can''t see; and their hearts, that they can''t understand.'),
  ('297392d1-a9dd-5bbb-a4a6-6133bffea727', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 19, 19, 'No one thinks, neither is there knowledge nor understanding to say, "I have burned part of it in the fire. Yes, I have also baked bread on its coals. I have roasted meat and eaten it. Shall I make the rest of it into an abomination? Shall I bow down to a tree trunk?"'),
  ('16e565c2-a4f6-5007-a6bf-6cddcf359a64', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 20, 20, 'He feeds on ashes. A deceived heart has turned him aside; and he can''t deliver his soul, nor say, "Isn''t there a lie in my right hand?"'),
  ('427725bf-7326-53c2-aedd-33c4e5cfba61', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 21, 21, 'Remember these things, Jacob and Israel; for you are my servant. I have formed you. You are my servant. Israel, you will not be forgotten by me.'),
  ('616f8667-d130-5b61-a6e8-e935bad1b75b', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 22, 22, 'I have blotted out, as a thick cloud, your transgressions, and, as a cloud, your sins. Return to me, for I have redeemed you.'),
  ('4e914025-125c-5865-aaa5-70e99ad8138a', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 23, 23, 'Sing, you heavens, for Yahweh has done it! Shout, you lower parts of the earth! Break out into singing, you mountains, O forest, all of your trees, for Yahweh has redeemed Jacob, and will glorify himself in Israel.'),
  ('9c44891a-bafe-5283-a879-6beea32854a6', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 24, 24, 'Thus says Yahweh, your Redeemer, and he who formed you from the womb: "I am Yahweh, who makes all things; who alone stretches out the heavens; who spreads out the earth by myself;'),
  ('b7c926f6-64a1-552e-ac63-89a0c256b93c', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 25, 25, 'who frustrates the signs of the liars, and makes diviners mad; who turns wise men backward, and makes their knowledge foolish;'),
  ('208dbd40-3e8c-5536-a144-e55fc39f73c9', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 26, 26, 'who confirms the word of his servant, and performs the counsel of his messengers; who says of Jerusalem, ''She will be inhabited;'' and of the cities of Judah, ''They will be built,'' and ''I will raise up its waste places;'''),
  ('b9ee7d99-6e11-52e5-a9c6-e7a073ca200a', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 27, 27, 'who says to the deep, ''Be dry,'' and ''I will dry up your rivers;'''),
  ('ffaf5932-bcbc-5c4c-a7fb-e1b013c2fc74', '65f3739b-21e6-57cd-a16f-e39cd49b5cfb', NULL, 28, 28, 'Who says of Cyrus, ''He is my shepherd, and shall perform all my pleasure,'' even saying of Jerusalem, ''She will be built;'' and of the temple, ''Your foundation will be laid.''"'),
  ('c36d8b8b-74ed-5a8a-ae9b-155f137ab821', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 1, 1, 'Thus says Yahweh to his anointed, to Cyrus, whose right hand I have held, to subdue nations before him, and strip kings of their armor; to open the doors before him, and the gates shall not be shut:'),
  ('b7ca4068-2913-5b5b-a378-352a9dd1d4d9', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 2, 2, '"I will go before you, and make the rough places smooth. I will break the doors of brass in pieces, and cut apart the bars of iron.'),
  ('a4106c93-0773-5977-a1dc-2bd5b85f6015', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 3, 3, 'I will give you the treasures of darkness, and hidden riches of secret places, that you may know that it is I, Yahweh, who call you by your name, even the God of Israel.'),
  ('ac1feefa-6a8f-5ffc-a8fa-5464cb1a216f', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 4, 4, 'For Jacob my servant''s sake, and Israel my chosen, I have called you by your name. I have surnamed you, though you have not known me.'),
  ('bf36a27c-72f2-58d6-aba4-dcc79b748ba1', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 5, 5, 'I am Yahweh, and there is none else. Besides me, there is no God. I will strengthen you, though you have not known me;'),
  ('59bf2b24-b291-5cb0-a7eb-b42a2b08da28', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 6, 6, 'that they may know from the rising of the sun, and from the west, that there is none besides me. I am Yahweh, and there is no one else.'),
  ('8db5f6a9-e541-586e-acf4-7a7707239b7e', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 7, 7, 'I form the light, and create darkness. I make peace, and create calamity. I am Yahweh, who does all these things.'),
  ('72e92923-d9d3-5c58-a08d-768b2fca7098', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 8, 8, 'Distil, you heavens, from above, and let the skies pour down righteousness. Let the earth open, that it may bring forth salvation, and let it cause righteousness to spring up with it. I, Yahweh, have created it.'),
  ('875e9098-c741-5fab-a4b5-d0569b29b603', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 9, 9, 'Woe to him who strives with his Maker-- a clay pot among the clay pots of the earth! Shall the clay ask him who fashions it, ''What are you making?'' or your work, ''He has no hands?'''),
  ('1dd1184a-9fa0-5a98-a181-72b2574b1a68', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 10, 10, 'Woe to him who says to a father, ''What have you become the father of?'' or to a mother, ''To what have you given birth?''"'),
  ('e537df80-83a1-5305-ab5d-804e6e394e0c', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 11, 11, 'Thus says Yahweh, the Holy One of Israel, and his Maker: "You ask me about the things that are to come, concerning my sons, and you command me concerning the work of my hands!'),
  ('ae40b0fe-cc0f-54b3-a88c-8b0c7772ddeb', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 12, 12, 'I have made the earth, and created man on it. I, even my hands, have stretched out the heavens; and I have commanded all their army.'),
  ('4b1335df-9a2f-5314-af42-1e7b76ff4a01', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 13, 13, 'I have raised him up in righteousness, and I will make straight all his ways. He shall build my city, and he shall let my exiles go free, not for price nor reward," says Yahweh of Armies.'),
  ('24dbbc31-47cb-5b1d-ab40-4edc54af5065', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 14, 14, 'Thus says Yahweh: "The labor of Egypt, and the merchandise of Ethiopia, and the Sabeans, men of stature, shall come over to you, and they shall be yours. They will go after you. They shall come over in chains; and they will bow down to you. They will make supplication to you: ''Surely God is in you; and there is none else. There is no other god.'),
  ('1652db03-6e67-525c-a9eb-5eb557d6118f', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 15, 15, 'Most certainly you are a God who hidden yourself, God of Israel, the Savior.''"'),
  ('1ae554c8-66ef-50bb-a354-cfae89eef09e', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 16, 16, 'They will be disappointed, yes, confounded, all of them. Those who are makers of idols will go into confusion together.'),
  ('71d57560-e41c-5c9b-a279-1ef204430ac2', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 17, 17, 'Israel will be saved by Yahweh with an everlasting salvation. You will not be disappointed nor confounded to ages everlasting.'),
  ('9324b9ec-edab-5988-ad1c-30aebb248960', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 18, 18, 'For thus says Yahweh who created the heavens, the God who formed the earth and made it, who established it and didn''t create it a waste, who formed it to be inhabited: "I am Yahweh; and there is no other.'),
  ('1210a336-fe98-5e1f-a59b-dd2656604938', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 19, 19, 'I have not spoken in secret, in a place of the land of darkness. I didn''t say to the seed of Jacob, ''Seek me in vain.'' I, Yahweh, speak righteousness. I declare things that are right.'),
  ('970f883c-a940-530b-a47d-52307e57bd1b', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 20, 20, '"Assemble yourselves and come. Draw near together, you who have escaped from the nations. Those have no knowledge who carry the wood of their engraved image, and pray to a god that can''t save.'),
  ('bf659a95-f3f9-53d2-a346-09f926b64b60', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 21, 21, 'Declare and present it. Yes, let them take counsel together. Who has shown this from ancient time? Who has declared it of old? Haven''t I, Yahweh? There is no other God besides me, a just God and a Savior; There is no one besides me.'),
  ('04cb7111-45bb-53f2-aeae-2d7fb84e6986', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 22, 22, '"Look to me, and be saved, all the ends of the earth; for I am God, and there is no other.'),
  ('031f0575-4e92-5407-a80d-9123be63af28', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 23, 23, 'I have sworn by myself, the word has gone out of my mouth in righteousness, and will not return, that to me every knee shall bow, every tongue shall take an oath.'),
  ('ca6622a6-5df5-50e9-add3-09041686425a', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 24, 24, 'They will say of me, ''There is righteousness and strength only in Yahweh.''" Even to him shall men come; and all those who were incensed against him shall be disappointed.'),
  ('40e11def-6b40-5b9c-ab4d-bee172696b76', '4d37ed54-3b71-58b3-ab0e-20d497871e13', NULL, 25, 25, 'In Yahweh shall all the seed of Israel be justified, and shall glory.'),
  ('eb118ebb-1ada-5eb0-a79f-e2f5c24f8176', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 1, 1, 'Bel bows down, Nebo stoops; their idols are on the animals, and on the livestock: the things that you carried about are made a load, a burden to the weary [animal].'),
  ('a8788ae2-8961-530b-af8a-c9adbb5c662e', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 2, 2, 'They stoop, they bow down together; they could not deliver the burden, but themselves are gone into captivity.'),
  ('244df09a-f4a6-5bf6-a847-0c006efdcedd', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 3, 3, '"Listen to me, house of Jacob, and all the remnant of the house of Israel, that have been borne [by me] from their birth, that have been carried from the womb;'),
  ('d857f753-03b1-5bd7-ad6a-e52e726f0e34', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 4, 4, 'and even to old age I am he, and even to gray hairs will I carry you. I have made, and I will bear; yes, I will carry, and will deliver.'),
  ('227803ed-10eb-5a6f-a8d6-362ecad80ddf', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 5, 5, '"To whom will you liken me, and make me equal, and compare me, that we may be like?'),
  ('7f318296-6114-5f1d-a636-1df81e3a7dba', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 6, 6, 'Some pour out gold from the bag, and weigh silver in the balance. They hire a goldsmith, and he makes it a god. They fall down--yes, they worship.'),
  ('4a93b9ef-4116-59c0-a633-20377749374d', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 7, 7, 'They bear it on the shoulder, they carry it, and set it in its place, and it stands, from its place it shall not move: yes, one may cry to it, yet it can not answer, nor save him out of his trouble.'),
  ('4bfa19ce-c3b6-5102-addf-cda91e18a444', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 8, 8, '"Remember this, and show yourselves men; bring it again to mind, you transgressors.'),
  ('a652df93-15ed-5ba3-adf6-be9e7be2b750', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 9, 9, 'Remember the former things of old: for I am God, and there is none else; [I am] God, and there is none like me;'),
  ('11cf30e7-f1d8-54fa-a45f-51d8af232e91', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 10, 10, 'declaring the end from the beginning, and from ancient times things that are not [yet] done; saying, My counsel shall stand, and I will do all my pleasure;'),
  ('04ca2f51-6ca6-5b21-a705-16465e3814a6', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 11, 11, 'calling a ravenous bird from the east, the man of my counsel from a far country; yes, I have spoken, I will also bring it to pass; I have purposed, I will also do it.'),
  ('afb2d289-1014-5e17-a625-33b0e380935a', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 12, 12, 'Listen to me, you stout-hearted, who are far from righteousness:'),
  ('d8a31c0c-b009-5fbf-ab22-e6021a12bb86', '2634f306-82ba-50f3-a819-cf0229195c76', NULL, 13, 13, 'I bring near my righteousness, it shall not be far off, and my salvation shall not wait; and I will place salvation in Zion for Israel my glory.'),
  ('39e43f85-8635-5b3b-a76d-278e7ce4065d', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 1, 1, '"Come down, and sit in the dust, virgin daughter of Babylon; sit on the ground without a throne, daughter of the Chaldeans: for you shall no more be called tender and delicate.'),
  ('92589520-76ec-5ec1-a83c-1f99533e4aaf', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 2, 2, 'Take the millstones, and grind meal; remove your veil, strip off the train, uncover the leg, pass through the rivers.'),
  ('df3d8233-2fb7-55be-a252-e229449b6f8b', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 3, 3, 'Your nakedness shall be uncovered, yes, your shame shall be seen: I will take vengeance, and will spare no man."'),
  ('aa5d0afa-329e-58c1-a3e5-62d7129286a7', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 4, 4, 'Our Redeemer, Yahweh of Armies is his name, the Holy One of Israel.'),
  ('bbbf5159-b22e-5423-a827-e250842f0d19', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 5, 5, '"Sit in silence, and go into darkness, daughter of the Chaldeans; for you shall no more be called the mistress of kingdoms.'),
  ('a22e8fee-3877-5f07-a0ea-58569cb507bf', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 6, 6, 'I was angry with my people, I profaned my inheritance, and gave them into your hand: you showed them no mercy; on the aged you have very heavily laid your yoke.'),
  ('510e82b9-060c-5677-a5fc-5871563a58fa', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 7, 7, 'You said, I shall be mistress forever; so that you did not lay these things to your heart, neither did remember the latter end of it.'),
  ('390654e9-7e8e-5b7e-a2fe-57fcc0750c8d', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 8, 8, '"Now therefore hear this, you who are given to pleasures, who sit securely, who say in your heart, I am, and there is none else besides me; I shall not sit as a widow, neither shall I know the loss of children:'),
  ('4833cfab-6f53-52b4-ae43-e986215aecbd', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 9, 9, 'but these two things shall come to you in a moment in one day, the loss of children, and widowhood; in their full measure shall they come on you, in the multitude of your sorceries, and the great abundance of your enchantments.'),
  ('c33a65cc-38c1-5f82-ac69-1496e7fab423', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 10, 10, 'For you have trusted in your wickedness; you have said, No one sees me; your wisdom and your knowledge, it has perverted you, and you have said in your heart, I am, and there is none else besides me.'),
  ('b4de9462-1bb5-5aa3-a44f-e1d45e9b5caf', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 11, 11, 'Therefore evil will come on you; you won''t know when it dawns: and mischief will fall on you; you will not be able to put it away: and desolation shall come on you suddenly, which you don''t know.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b5e4e11a-bf71-542b-adad-4819cd4b643f', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 12, 12, '"Stand now with your enchantments, and with the multitude of your sorceries, in which you have labored from your youth; if so be you shall be able to profit, if so be you may prevail.'),
  ('9440061e-6516-5175-a6c4-db02481534d4', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 13, 13, 'You are wearied in the multitude of your counsels: let now the astrologers, the stargazers, the monthly prognosticators, stand up, and save you from the things that shall come on you.'),
  ('684705d4-ac6e-5c68-a311-7dc005c32ca1', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 14, 14, 'Behold, they shall be as stubble; the fire shall burn them; they shall not deliver themselves from the power of the flame: it shall not be a coal to warm at, nor a fire to sit before.'),
  ('19728e8d-abf1-5c1d-a68d-f715a828b078', '48af4c4d-03c5-5ede-a569-b7dd6d02e430', NULL, 15, 15, 'Thus shall the things be to you in which you have labored: those who have trafficked with you from your youth shall wander everyone to his quarter; there shall be none to save you.'),
  ('08e75a86-71c1-5cc7-a87c-15e271b11f1a', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 1, 1, '"Hear this, house of Jacob, you who are called by the name of Israel, and have come forth out of the waters of Judah; who swear by the name of Yahweh, and make mention of the God of Israel, but not in truth, nor in righteousness'),
  ('7e43e051-667a-54a4-a9a3-2cd493380e12', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 2, 2, '(for they call themselves of the holy city, and stay themselves on the God of Israel; Yahweh of Armies is his name):'),
  ('cf4499de-8255-597a-a1cd-4818bd133760', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 3, 3, 'I have declared the former things from of old; yes, they went forth out of my mouth, and I showed them: suddenly I did them, and they happened.'),
  ('49e4d2d4-c55d-5a1b-a59c-003cd172d632', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 4, 4, 'Because I knew that you are obstinate, and your neck is an iron sinew, and your brow brass;'),
  ('35a82ceb-f754-51d8-aeaf-27633e3a2185', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 5, 5, 'therefore I have declared it to you from of old; before it came to pass I showed it to you; lest you should say, ''My idol has done them, and my engraved image, and my molten image, has commanded them.'''),
  ('ecc2685c-810d-57a7-a99c-712ec9367fad', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 6, 6, 'You have heard it; see all this; and you, will you not declare it? "I have shown you new things from this time, even hidden things, which you have not known.'),
  ('b1d00bb7-18b0-5acc-a4bd-12e36bcf15fe', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 7, 7, 'They are created now, and not from of old; and before this day you didn''t hear them; lest you should say, ''Behold, I knew them.'''),
  ('f63e2f75-6ecd-52b0-a8b2-ef8cd90aea5f', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 8, 8, 'Yes, you didn''t hear; yes, you didn''t know; yes, from of old your ear was not opened: for I knew that you did deal very treacherously, and was called a transgressor from the womb.'),
  ('3566a42c-920a-52a7-afa6-180730dd8488', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 9, 9, 'For my name''s sake will I defer my anger, and for my praise will I refrain for you, that I not cut you off.'),
  ('04b9e014-d340-5a87-aacc-df3a5991173f', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 10, 10, 'Behold, I have refined you, but not as silver; I have chosen you in the furnace of affliction.'),
  ('9a0aef69-8568-5d66-a142-8e2ddab51424', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 11, 11, 'For my own sake, for my own sake, will I do it; for how should [my name] be profaned? and my glory I will not give to another.'),
  ('ec7cb833-4e05-51d5-a70f-5101483ae34d', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 12, 12, '"Listen to me, O Jacob, and Israel my called: I am he; I am the first, I also am the last.'),
  ('67af0690-954f-5048-af3b-25c772739dae', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 13, 13, 'Yes, my hand has laid the foundation of the earth, and my right hand has spread out the heavens: when I call to them, they stand up together.'),
  ('cb1680a3-7cef-54e7-ad4f-5e896ae2e786', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 14, 14, '"Assemble yourselves, all you, and hear; who among them has declared these things? He whom Yahweh loves shall perform his pleasure on Babylon, and his arm [shall be on] the Chaldeans.'),
  ('5781cb04-62f6-5b1d-a533-35818145a03b', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 15, 15, 'I, even I, have spoken; yes, I have called him; I have brought him, and he shall make his way prosperous.'),
  ('da048a23-24f5-548d-a775-de8260843204', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 16, 16, '"Come near to me and hear this: "From the beginning I have not spoken in secret; from the time that it was, there am I." Now the Lord Yahweh has sent me, with his Spirit.'),
  ('d2ebdc98-ac2b-52df-a813-cc143154cd39', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 17, 17, 'Thus says Yahweh, your Redeemer, the Holy One of Israel: I am Yahweh your God, who teaches you to profit, who leads you by the way that you should go.'),
  ('f6678676-7044-5783-afb1-2e1b580ead07', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 18, 18, 'Oh that you had listened to my commandments! then your peace would have been like a river, and your righteousness like the waves of the sea:'),
  ('574c9e4c-d3de-507f-a429-6dceb9f022e1', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 19, 19, 'your seed also had been as the sand, and the offspring of your body like its grains: his name would not be cut off nor destroyed from before me.'),
  ('02f5a748-3d2e-574b-aca6-dda23da0e2a2', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 20, 20, 'Go forth from Babylon, flee from the Chaldeans; with a voice of singing declare, tell this, utter it even to the end of the earth: say, Yahweh has redeemed his servant Jacob.'),
  ('28f04403-91af-578c-af6b-c0a2df0dac23', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 21, 21, 'They didn''t thirst when he led them through the deserts; he caused the waters to flow out of the rock for them; he split the rock also, and the waters gushed out.'),
  ('fada2328-5be1-5616-a04f-1bf3eb69cac2', '17cf1b71-c3f6-5104-a078-0f9d823a2383', NULL, 22, 22, '"There is no peace," says Yahweh, "for the wicked."'),
  ('8873943d-924b-5cd2-ac53-e7a2afe5fd79', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 1, 1, 'Listen, islands, to me; and listen, you peoples, from far: Yahweh has called me from the womb; from the bowels of my mother has he made mention of my name:'),
  ('3558175c-ae81-51d9-a31e-8e73837c79d5', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 2, 2, 'and he has made my mouth like a sharp sword; in the shadow of his hand, he has hidden me: and he has made me a polished shaft; in his quiver has he kept me close:'),
  ('5d942dd9-4247-5fa5-a718-aec71cf97c50', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 3, 3, 'and he said to me, "You are my servant; Israel, in whom I will be glorified."'),
  ('702d6402-4c3b-531f-ad8b-1ed0b0aff5cd', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 4, 4, 'But I said, "I have labored in vain, I have spent my strength for nothing and vanity; yet surely the justice [due] to me is with Yahweh, and my reward with my God."'),
  ('6b73edcc-192d-57d8-a616-dc9175bfe4c5', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 5, 5, 'Now says Yahweh who formed me from the womb to be his servant, to bring Jacob again to him, and that Israel be gathered to him (for I am honorable in the eyes of Yahweh, and my God is become my strength);'),
  ('b72b9500-b92d-55b3-adc6-5ca1aa0bef10', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 6, 6, 'yes, he says, "It is too light a thing that you should be my servant to raise up the tribes of Jacob, and to restore the preserved of Israel: I will also give you for a light to the nations, that you may be my salvation to the end of the earth."'),
  ('c4023a8e-2feb-50c1-ae71-bb369e653249', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 7, 7, 'Thus says Yahweh, the Redeemer of Israel, [and] his Holy One, to him whom man despises, to him whom the nation abhors, to a servant of rulers: "Kings shall see and arise; princes, and they shall worship; because of Yahweh who is faithful, [even] the Holy One of Israel, who has chosen you."'),
  ('e1d09f0d-8f7c-50a0-aaeb-0a3d12306212', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 8, 8, 'Thus says Yahweh, "In an acceptable time have I answered you, and in a day of salvation have I helped you; and I will preserve you, and give you for a covenant of the people, to raise up the land, to make them inherit the desolate heritage:'),
  ('793b612b-6405-5f94-ab21-444ad72158b8', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 9, 9, 'saying to those who are bound, ''Come out!''; to those who are in darkness, ''Show yourselves!'' "They shall feed in the ways, and on all bare heights shall be their pasture.'),
  ('28440962-6e74-5306-a2e8-97481ab172ca', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 10, 10, 'They shall not hunger nor thirst; neither shall the heat nor sun strike them: for he who has mercy on them will lead them, even by springs of water he will guide them.'),
  ('b3cb0c5e-6a25-582b-a0f9-24c115aca3e0', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 11, 11, 'I will make all my mountains a way, and my highways shall be exalted.'),
  ('a8c51d54-581e-5010-a01d-8210861e98fc', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 12, 12, 'Behold, these shall come from far; and behold, these from the north and from the west; and these from the land of Sinim."'),
  ('51826827-0d06-5c28-a44d-0a792b3eff54', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 13, 13, 'Sing, heavens; and be joyful, earth; and break forth into singing, mountains: for Yahweh has comforted his people, and will have compassion on his afflicted.'),
  ('bbcbebc5-2b02-5f5d-ab5e-a1aeb2fd204b', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 14, 14, 'But Zion said, "Yahweh has forsaken me, and the Lord has forgotten me."'),
  ('6743a662-4f27-596f-a2c6-163465f16d6a', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 15, 15, '"Can a woman forget her nursing child, that she should not have compassion on the son of her womb? Yes, these may forget, yet I will not forget you!'),
  ('c0701810-3ad9-5d35-a10b-4c5aad7a499c', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 16, 16, 'Behold, I have engraved you on the palms of my hands; your walls are continually before me.'),
  ('40c72606-3905-5408-a52a-679a7c9b2490', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 17, 17, 'Your children make haste; your destroyers and those who made you waste shall go forth from you.'),
  ('325d8a97-81fd-5246-a044-ad84dedf4e9d', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 18, 18, 'Lift up your eyes all around, and see: all these gather themselves together, and come to you. As I live," says Yahweh, "you shall surely clothe yourself with them all as with an ornament, and dress yourself with them, like a bride.'),
  ('e8772230-7b80-5ee4-a07b-3b0fc48b05fb', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 19, 19, '"For, as for your waste and your desolate places, and your land that has been destroyed, surely now you shall be too small for the inhabitants, and those who swallowed you up shall be far away.'),
  ('8430dcf6-6fe0-5c7c-a5fa-710daae49c68', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 20, 20, 'The children of your bereavement shall yet say in your ears, The place is too small for me; give place to me that I may dwell.'),
  ('7036f64e-ccdb-5857-a847-3ba6831079e4', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 21, 21, 'Then you will say in your heart, ''Who has conceived these for me, since I have been bereaved of my children, and am solitary, an exile, and wandering back and forth? Who has brought up these? Behold, I was left alone; these, where were they?''"'),
  ('c0643619-2cdc-5e2b-a32f-8b32b126ac7e', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 22, 22, 'Thus says the Lord Yahweh, "Behold, I will lift up my hand to the nations, and set up my banner to the peoples; and they shall bring your sons in their bosom, and your daughters shall be carried on their shoulders.'),
  ('5fbc2362-63aa-5501-a89a-7618a52b0bd2', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 23, 23, 'Kings shall be your nursing fathers, and their queens your nursing mothers: they shall bow down to you with their faces to the earth, and lick the dust of your feet; and you shall know that I am Yahweh; and those who wait for me shall not be disappointed."'),
  ('01ae741f-432d-5f57-a693-08bacb083e20', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 24, 24, 'Shall the prey be taken from the mighty, or the lawful captives be delivered?'),
  ('466d6622-62f0-560d-ad90-194cf21d5df7', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 25, 25, 'But thus says Yahweh, "Even the captives of the mighty shall be taken away, and the prey of the terrible shall be delivered; for I will contend with him who contends with you, and I will save your children.'),
  ('68ffe6b9-1915-5f9d-af51-a9daeefcde1f', 'df51a549-7760-50da-ad8b-b39d2022f1e5', NULL, 26, 26, 'I will feed those who oppress you with their own flesh; and they shall be drunken with their own blood, as with sweet wine: and all flesh shall know that I, Yahweh, am your Savior, and your Redeemer, the Mighty One of Jacob."'),
  ('7628db1c-6cfb-5f0b-a439-1c2edfdab8c7', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 1, 1, 'Thus says Yahweh, "Where is the bill of your mother''s divorce, with which I have put her away? or which of my creditors is it to whom I have sold you? Behold, for your iniquities were you sold, and for your transgressions was your mother put away.'),
  ('f3d5120a-120e-52fe-ab56-25f452575ee8', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 2, 2, 'Why, when I came, was there no man? when I called, was there none to answer? Is my hand shortened at all, that it can''t redeem? or have I no power to deliver? Behold, at my rebuke I dry up the sea, I make the rivers a wilderness: their fish stink, because there is no water, and die for thirst.'),
  ('37e84bb0-6084-5cf4-abb4-b874c086ee42', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 3, 3, 'I clothe the heavens with blackness, and I make sackcloth their covering."'),
  ('6015cd9e-57c0-5a24-a435-e45d002450a9', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 4, 4, 'The Lord Yahweh has given me the tongue of those who are taught, that I may know how to sustain with words him who is weary: he wakens morning by morning, he wakens my ear to hear as those who are taught.'),
  ('34bb7840-4e3c-5989-aa20-f53d480b9555', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 5, 5, 'The Lord Yahweh has opened my ear, and I was not rebellious, neither turned away backward.'),
  ('f90ef6d5-f6ba-5d28-a21d-ace97ee1dfa8', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 6, 6, 'I gave my back to the strikers, and my cheeks to those who plucked off the hair; I didn''t hide my face from shame and spitting.'),
  ('51a8802a-6326-5ce0-af3f-34d24a69585f', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 7, 7, 'For the Lord Yahweh will help me; therefore I have not been confounded: therefore have I set my face like a flint, and I know that I shall not be disappointed.'),
  ('c34e1c6a-cf75-5cc8-a1e3-db7f43ad22f3', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 8, 8, 'He is near who justifies me; who will bring charges against me? Let us stand up together: who is my adversary? Let him come near to me.'),
  ('901e71ea-3bc5-5ceb-ad35-930eaa799609', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 9, 9, 'Behold, the Lord Yahweh will help me; who is he who shall condemn me? Behold, all they shall wax old as a garment, the moth shall eat them up.'),
  ('dbe744fa-8676-5dd2-ae1c-7608bcef3f54', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 10, 10, 'Who is among you who fears Yahweh, who obeys the voice of his servant? He who walks in darkness, and has no light, let him trust in the name of Yahweh, and rely on his God.'),
  ('31445e53-860c-5bb9-a98c-b3f2757b33f6', 'a5be3cd1-43a7-5fd7-a739-11c96d93fdd6', NULL, 11, 11, 'Behold, all you who kindle a fire, who adorn yourselves with torches around yourselves; walk in the flame of your fire, and among the brands that you have kindled. You shall have this of my hand; you shall lie down in sorrow.'),
  ('552ab6f2-2aec-5ee0-ab6f-cb3cba72d57c', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 1, 1, '"Listen to me, you who follow after righteousness, you who seek Yahweh: look to the rock you were cut from, and to the hold of the pit you were dug from.'),
  ('2676461a-8e6a-5121-acbe-01d5ef6291d4', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 2, 2, 'Look to Abraham your father, and to Sarah who bore you; for when he was but one I called him, and I blessed him, and made him many.'),
  ('c5e7529f-90ba-5f58-a386-a0f42d1c7b83', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 3, 3, 'For Yahweh has comforted Zion; he has comforted all her waste places, and has made her wilderness like Eden, and her desert like the garden of Yahweh; joy and gladness shall be found therein, thanksgiving, and the voice of melody.'),
  ('380859d9-53f0-5938-a411-6aa5789445f1', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 4, 4, '"Attend to me, my people; and give ear to me, my nation: for a law shall go forth from me, and I will establish my justice for a light of the peoples.'),
  ('ecc67627-7501-5b85-ac43-27dcdf7ad715', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 5, 5, 'My righteousness is near, my salvation is gone forth, and my arms shall judge the peoples; the islands shall wait for me, and on my arm shall they trust.'),
  ('f1e873b5-28f4-5a3b-a88f-54330fa9f35b', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 6, 6, 'Lift up your eyes to the heavens, and look on the earth beneath; for the heavens shall vanish away like smoke, and the earth shall wax old like a garment; and those who dwell therein shall die in the same way: but my salvation shall be forever, and my righteousness shall not be abolished.'),
  ('f29a57eb-6116-5a75-a21e-62c929418715', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 7, 7, '"Listen to me, you who know righteousness, the people in whose heart is my law; don''t fear the reproach of men, neither be dismayed at their insults.'),
  ('8169850c-a5a8-5553-a51b-e7eaa77a2395', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 8, 8, 'For the moth shall eat them up like a garment, and the worm shall eat them like wool; but my righteousness shall be forever, and my salvation to all generations."'),
  ('b95cc9b9-dbc8-576b-a215-f35773a98932', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 9, 9, 'Awake, awake, put on strength, arm of Yahweh; awake, as in the days of old, the generations of ancient times. Isn''t it you who cut Rahab in pieces, who pierced the monster?'),
  ('85ee6a99-7327-5bac-aacc-8acd2ff97a1b', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 10, 10, 'Isn''t it you who dried up the sea, the waters of the great deep; who made the depths of the sea a way for the redeemed to pass over?'),
  ('e403b42e-af7e-5401-a951-b666a564a888', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 11, 11, 'The ransomed of Yahweh shall return, and come with singing to Zion; and everlasting joy shall be on their heads: they shall obtain gladness and joy; [and] sorrow and sighing shall flee away.'),
  ('0d60aea4-3e3b-5805-af9c-84c69266105e', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 12, 12, '"I, even I, am he who comforts you: who are you, that you are afraid of man who shall die, and of the son of man who shall be made as grass;'),
  ('c2f645b8-29c3-5e07-a48d-83472f5b9568', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 13, 13, 'and have forgotten Yahweh your Maker, who stretched forth the heavens, and laid the foundations of the earth; and fear continually all the day because of the fury of the oppressor, when he makes ready to destroy? and where is the fury of the oppressor?'),
  ('2cb5dd0e-774f-5c7f-afb3-9ce3392c5c1f', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 14, 14, 'The captive exile shall speedily be freed; and he shall not die [and go down] into the pit, neither shall his bread fail.'),
  ('c85b9ffa-8ffc-54d2-a0a3-9e617a329aa0', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 15, 15, 'For I am Yahweh your God, who stirs up the sea, so that its waves roar: Yahweh of Armies is his name.'),
  ('95c6d8e1-0744-5342-afb6-9bbef8d67077', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 16, 16, 'I have put my words in your mouth, and have covered you in the shadow of my hand, that I may plant the heavens, and lay the foundations of the earth, and tell Zion, ''You are my people.''"'),
  ('f8132d46-d74d-5207-a4e1-fefe160de65d', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 17, 17, 'Awake, awake, stand up, Jerusalem, that have drunk at the hand of Yahweh the cup of his wrath; you have drunken the bowl of the cup of staggering, and drained it.'),
  ('137e67b0-242d-54eb-a5e2-8bec08ed121c', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 18, 18, 'There is none to guide her among all the sons whom she has brought forth; neither is there any who takes her by the hand among all the sons who she has brought up.'),
  ('a7b30a4f-bc41-5e96-a4b1-e4372e157826', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 19, 19, 'These two things have happened to you. Who will bemoan you? Desolation and destruction, and the famine and the sword; how shall I comfort you?'),
  ('1b182053-26e3-5973-a2d4-7e161cdc0718', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 20, 20, 'Your sons have fainted, they lie at the head of all the streets, as an antelope in a net; they are full of the wrath of Yahweh, the rebuke of your God.'),
  ('5f3d8140-1591-5d6d-accf-0651917cc5b4', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 21, 21, 'Therefore hear now this, you afflicted, and drunken, but not with wine:'),
  ('f1ad9139-def5-50aa-a658-79e3995cf63d', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 22, 22, 'Thus says your Lord Yahweh, and your God who pleads the cause of his people, "Behold, I have taken out of your hand the cup of staggering, even the bowl of the cup of my wrath; you shall no more drink it again:'),
  ('c25da56d-c471-59da-a86f-8e3d77233315', 'e71cd222-1cc4-5b74-a008-41e8b3434fc5', NULL, 23, 23, 'and I will put it into the hand of those who afflict you, who have said to your soul, ''Bow down, that we may walk over you;'' and you have laid your back as the ground, and as the street, to those who walk over."'),
  ('0e435aeb-18bd-5a05-a3fd-45a5e803875c', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 1, 1, 'Awake, awake, put on your strength, Zion; put on your beautiful garments, Jerusalem, the holy city: for henceforth there shall no more come into you the uncircumcised and the unclean.'),
  ('cd5007f2-54c4-5182-aae4-07dad4b222fa', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 2, 2, 'Shake yourself from the dust; arise, sit [on your throne], Jerusalem: release yourself from the bonds of your neck, captive daughter of Zion.'),
  ('7561b001-a452-5be9-ad8b-ed4c436d391a', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 3, 3, 'For thus says Yahweh, "You were sold for nothing; and you shall be redeemed without money."'),
  ('925335bc-22eb-5b2e-a671-ed5ded1c22ec', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 4, 4, 'For thus says the Lord Yahweh, "My people went down at the first into Egypt to live there: and the Assyrian has oppressed them without cause.'),
  ('b306c853-1211-5c4b-af62-5c23528ffacf', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 5, 5, '"Now therefore, what do I here," says Yahweh, "seeing that my people are taken away for nothing? those who rule over them mock," says Yahweh, "and my name continually all the day is blasphemed.'),
  ('c9959141-08a7-583c-a61f-80ccfe61b31b', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 6, 6, 'Therefore my people shall know my name: therefore [they shall know] in that day that I am he who does speak; behold, it is I."'),
  ('4dedfd4a-39bd-50e8-a5a6-d445c73891ff', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 7, 7, 'How beautiful on the mountains are the feet of him who brings good news, who publishes peace, who brings good news of good, who publishes salvation, who says to Zion, "Your God reigns!"'),
  ('f7c84c4f-daa1-53c7-a8fb-c729c775de0e', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 8, 8, 'The voice of your watchmen! they lift up the voice, together do they sing; for they shall see eye to eye, when Yahweh returns to Zion.'),
  ('272861e8-796e-54e6-a151-0becfb37f251', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 9, 9, 'Break forth into joy, sing together, you waste places of Jerusalem; for Yahweh has comforted his people, he has redeemed Jerusalem.'),
  ('509b80e8-1b75-5e48-a62b-c1c122432482', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 10, 10, 'Yahweh has made bare his holy arm in the eyes of all the nations; and all the ends of the earth have seen the salvation of our God.'),
  ('1d0f33cf-962c-5543-a5d0-8a9593551231', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 11, 11, 'Depart, depart, go out from there, touch no unclean thing! Go out of the midst of her! Cleanse yourselves, you who bear the vessels of Yahweh.'),
  ('1ca9f34a-3e54-5955-a944-7ccf7b1b2c2d', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 12, 12, 'For you shall not go out in haste, neither shall you go by flight: for Yahweh will go before you; and the God of Israel will be your rear guard.'),
  ('b9eb4fe6-a118-5fe1-afbc-563ad1856112', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 13, 13, 'Behold, my servant shall deal wisely, he shall be exalted and lifted up, and shall be very high.'),
  ('af1f8799-de0e-524c-a566-904e397998c3', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 14, 14, 'Like as many were astonished at you (his appearance was marred more than any man, and his form more than the sons of men),'),
  ('36416e3f-bd49-5c1d-aacf-15017bd30f54', '802d4493-876c-590f-a5ea-715a8f51fe25', NULL, 15, 15, 'so shall he sprinkle many nations; kings shall shut their mouths at him: for that which had not been told them shall they see; and that which they had not heard shall they understand.'),
  ('41c3faa3-82ef-5967-a906-941f1407530a', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 1, 1, 'Who has believed our message? To whom has the arm of Yahweh been revealed?'),
  ('71a2e3b6-dd3e-5874-a152-2b883dd7adda', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 2, 2, 'For he grew up before him as a tender plant, and as a root out of dry ground. He has no form nor comeliness. When we see him, there is no beauty that we should desire him.'),
  ('fee1babe-5390-5a13-a7da-53fef69f259b', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 3, 3, 'He was despised, and rejected by men; a man of suffering, and acquainted with disease. He was despised as one from whom men hide their face; and we didn''t respect him.'),
  ('650bda56-a17c-5469-a68a-203d73f14c5c', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 4, 4, 'Surely he has borne our sickness, and carried our suffering; yet we considered him plagued, struck by God, and afflicted.'),
  ('e5c2bd28-bf6d-5abb-a45a-0e4d82b7713b', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 5, 5, 'But he was pierced for our transgressions. He was crushed for our iniquities. The punishment that brought our peace was on him; and by his wounds we are healed.'),
  ('fa789c3b-6288-5cbb-a05b-df887d3def1c', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 6, 6, 'All we like sheep have gone astray. Everyone has turned to his own way; and Yahweh has laid on him the iniquity of us all.'),
  ('8df25b5c-3968-5fe4-a505-bc45c3d3f772', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 7, 7, 'He was oppressed, yet when he was afflicted he didn''t open his mouth. As a lamb that is led to the slaughter, and as a sheep that before its shearers is mute, so he didn''t open his mouth.'),
  ('43523090-89c4-54f4-a3cc-b04fe573d804', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 8, 8, 'He was taken away by oppression and judgment; and as for his generation, who considered that he was cut off out of the land of the living and stricken for the disobedience of my people?'),
  ('f665733d-110d-5e77-ab46-584e44208bdd', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 9, 9, 'They made his grave with the wicked, and with a rich man in his death; although he had done no violence, neither was any deceit in his mouth.'),
  ('420e5ef2-c8a4-52de-a66f-183d4f741305', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 10, 10, 'Yet it pleased Yahweh to bruise him. He has caused him to suffer. When you make his soul an offering for sin, he shall see his seed. He shall prolong his days, and the pleasure of Yahweh shall prosper in his hand.'),
  ('8192af5b-18e0-50b1-a81d-63764cfca787', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 11, 11, 'After the suffering of his soul, he will see the light and be satisfied. My righteous servant will justify many by the knowledge of himself; and he will bear their iniquities.'),
  ('71c7e064-8906-57ec-ae94-cdf56b9f8f41', '58f12971-22b6-594f-a4fc-7d1c007e5e18', NULL, 12, 12, 'Therefore will I divide him a portion with the great, and he shall divide the spoil with the strong; because he poured out his soul to death, and was numbered with the transgressors; yet he bore the sin of many, and made intercession for the transgressors.'),
  ('6ffd9b74-e2cf-576f-a98f-40afd0d45309', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 1, 1, '"Sing, barren, you who didn''t bear; break forth into singing, and cry aloud, you who did not travail with child: for more are the children of the desolate than the children of the married wife," says Yahweh.'),
  ('fefdf098-4b7d-50ab-aea5-8ef36da8e42d', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 2, 2, '"Enlarge the place of your tent, and let them stretch forth the curtains of your habitations; don''t spare: lengthen your cords, and strengthen your stakes.'),
  ('1b0f30ae-65d9-557c-abb8-55c4d70c285b', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 3, 3, 'For you shall spread out on the right hand and on the left; and your seed shall possess the nations, and make the desolate cities to be inhabited.'),
  ('9a2016fc-4ac1-5de7-a4eb-3bf767ae6412', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 4, 4, '"Don''t be afraid; for you shall not be ashamed: neither be confounded; for you shall not be disappointed: for you shall forget the shame of your youth; and the reproach of your widowhood you shall remember no more.'),
  ('3662c165-0e04-56d7-ab11-52392d758c29', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 5, 5, 'For your Maker is your husband; Yahweh of Armies is his name: and the Holy One of Israel is your Redeemer; the God of the whole earth shall he be called.'),
  ('813dffd3-75df-52b2-a064-5229a0b9f1e5', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 6, 6, 'For Yahweh has called you as a wife forsaken and grieved in spirit, even a wife of youth, when she is cast off," says your God.'),
  ('394869bc-69b9-5ef3-a0c6-56ac1966fad3', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 7, 7, '"For a small moment have I forsaken you; but with great mercies will I gather you.'),
  ('46ee4cfa-1b1a-596d-a350-014531ad1086', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 8, 8, 'In overflowing wrath I hid my face from you for a moment; but with everlasting loving kindness will I have mercy on you," says Yahweh your Redeemer.'),
  ('b146843a-0355-5b01-afb1-e591a7f042ed', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 9, 9, '"For this is like the waters of Noah to me; for as I have sworn that the waters of Noah shall no more go over the earth, so have I sworn that I will not be angry with you, nor rebuke you.'),
  ('70a40b42-639f-52d0-a456-a20a9be182d6', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 10, 10, 'For the mountains may depart, and the hills be removed; but my loving kindness shall not depart from you, neither shall my covenant of peace be removed," says Yahweh who has mercy on you.'),
  ('1ae2653a-11d9-571b-a5af-c60730ad7cfb', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 11, 11, '"You afflicted, tossed with storms, and not comforted, behold, I will set your stones in beautiful colors, and lay your foundations with sapphires.'),
  ('c060ca3d-f1dd-5f15-a11e-69b83a2b7b80', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 12, 12, 'I will make your pinnacles of rubies, and your gates of sparkling jewels, and all your walls of precious stones.'),
  ('ae90d3dc-b687-53d6-a3ec-77fe3bb917c0', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 13, 13, 'All your children shall be taught of Yahweh; and great shall be the peace of your children.'),
  ('2c82c58e-55c1-57d9-af68-53be1bf4ea1c', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 14, 14, 'In righteousness you shall be established: you shall be far from oppression, for you shall not be afraid; and from terror, for it shall not come near you.'),
  ('fc0640c2-58c2-5cf8-a682-d18cfb49450c', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 15, 15, 'Behold, they may gather together, but not by me: whoever shall gather together against you shall fall because of you.'),
  ('ffd30023-dd80-5a86-a234-b793eb4ad64f', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 16, 16, '"Behold, I have created the smith who blows the fire of coals, and brings forth a weapon for his work; and I have created the waster to destroy.'),
  ('4d1aefa1-077a-593a-acc8-71c392496240', 'd06d7a1e-e674-54ee-a117-0376a0e54235', NULL, 17, 17, 'No weapon that is formed against you will prevail; and you will condemn every tongue that rises against you in judgment. This is the heritage of the servants of Yahweh, and their righteousness which is of me," says Yahweh.'),
  ('4a5ff36b-fb77-5d65-a022-9545a123e40c', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 1, 1, '"Come, everyone who thirsts, to the waters! Come, he who has no money, buy, and eat! Yes, come, buy wine and milk without money and without price.'),
  ('171e240b-d024-5621-adbf-f1cf530b4894', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 2, 2, 'Why do you spend money for that which is not bread? and your labor for that which doesn''t satisfy? listen diligently to me, and eat you that which is good, and let your soul delight itself in fatness.'),
  ('ecf3748e-6c79-5950-ab0a-d12ef222167e', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 3, 3, 'Turn your ear, and come to me; hear, and your soul shall live: and I will make an everlasting covenant with you, even the sure mercies of David.'),
  ('812a7620-e9cb-59e3-aa97-6f197c10dd44', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 4, 4, 'Behold, I have given him for a witness to the peoples, a leader and commander to the peoples.'),
  ('8669f807-d586-5db9-a5c4-cbb8a6c960f9', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 5, 5, 'Behold, you shall call a nation that you don''t know; and a nation that didn''t know you shall run to you, because of Yahweh your God, and for the Holy One of Israel; for he has glorified you."'),
  ('b676b99f-1260-5a48-a53e-c10a8ba12ee6', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 6, 6, 'Seek Yahweh while he may be found; call you on him while he is near:'),
  ('025814ca-ddd2-5ad6-a208-14061863377c', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 7, 7, 'let the wicked forsake his way, and the unrighteous man his thoughts; and let him return to Yahweh, and he will have mercy on him; and to our God, for he will abundantly pardon.'),
  ('2533c435-4870-5eb6-a0e4-cccdd1545116', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 8, 8, '"For my thoughts are not your thoughts, neither are your ways my ways," says Yahweh.'),
  ('818aa0e6-5a08-54a6-a282-c29f55765fd2', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 9, 9, '"For as the heavens are higher than the earth, so are my ways higher than your ways, and my thoughts than your thoughts.'),
  ('1c056638-7c97-5549-a1ad-d08c7885ae93', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 10, 10, 'For as the rain comes down and the snow from the sky, and doesn''t return there, but waters the earth, and makes it bring forth and bud, and gives seed to the sower and bread to the eater;'),
  ('504d5d1d-3114-58e0-a479-aef65f142d1e', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 11, 11, 'so shall my word be that goes forth out of my mouth: it shall not return to me void, but it shall accomplish that which I please, and it shall prosper in the thing I sent it to do.'),
  ('ba3ba29a-6a9d-5244-a2c9-39916c08a03f', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 12, 12, 'For you shall go out with joy, and be led forth with peace: the mountains and the hills shall break forth before you into singing; and all the trees of the fields shall clap their hands.'),
  ('469602d2-b9da-593e-a4bf-20071bb6b9f1', '4d98e967-21cf-5f3e-af69-0b6ae5487fb5', NULL, 13, 13, 'Instead of the thorn shall come up the fir tree; and instead of the brier shall come up the myrtle tree: and it shall be to Yahweh for a name, for an everlasting sign that shall not be cut off."'),
  ('e0bd6906-a804-5e9b-a360-858e7907d4c0', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 1, 1, 'Thus says Yahweh, "Keep justice, and do righteousness; for my salvation is near to come, and my righteousness to be revealed.'),
  ('a32a0693-d94b-5432-abe2-397e80865f26', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 2, 2, 'Blessed is the man who does this, and the son of man who holds it fast; who keeps the Sabbath from profaning it, and keeps his hand from doing any evil."'),
  ('a23de3a9-f15e-5d9d-a463-bdb8e40cba6a', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 3, 3, 'Neither let the foreigner, who has joined himself to Yahweh, speak, saying, "Yahweh will surely separate me from his people;" neither let the eunuch say, "Behold, I am a dry tree."'),
  ('db062bd4-3ca4-53e8-abf2-14b6fec287a9', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 4, 4, 'For thus says Yahweh, "To the eunuchs who keep my Sabbaths, and choose the things that please me, and hold fast my covenant:'),
  ('e4f81d8a-8164-52ca-ac7e-d3309c66acea', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 5, 5, 'to them I will give in my house and within my walls a memorial and a name better than of sons and of daughters; I will give them an everlasting name, that shall not be cut off.'),
  ('f9f232a2-8f52-51d2-a520-6b363b697039', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 6, 6, 'Also the foreigners who join themselves to Yahweh, to minister to him, and to love the name of Yahweh, to be his servants, everyone who keeps the Sabbath from profaning it, and holds fast my covenant;'),
  ('f6653a52-a95a-5b7b-ab4f-04cd1605e343', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 7, 7, 'even them will I bring to my holy mountain, and make them joyful in my house of prayer: their burnt offerings and their sacrifices shall be accepted on my altar; for my house shall be called a house of prayer for all peoples."'),
  ('e788ab06-08a7-571e-a9e9-fc13734d134e', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 8, 8, 'The Lord Yahweh, who gathers the outcasts of Israel, says, "Yet will I gather [others] to him, besides his own who are gathered."'),
  ('915c8d35-4b89-57c6-a073-324dfe0256d4', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 9, 9, 'All you animals of the field, come to devour, [yes], all you animals in the forest.'),
  ('0cb920e5-4459-53cb-a32a-903857e14fbd', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 10, 10, 'His watchmen are blind, they are all without knowledge; they are all mute dogs, they can''t bark; dreaming, lying down, loving to slumber.'),
  ('24f75ebb-ade5-53ba-a290-a46f9ffba3a5', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 11, 11, 'Yes, the dogs are greedy, they can never have enough; and these are shepherds who can''t understand: they have all turned to their own way, each one to his gain, from every quarter.'),
  ('7c12db17-e2f5-559c-a2e7-dcb90b7819db', '0d4b1a50-fcd5-59f5-ae57-5fb73ecef85a', NULL, 12, 12, '"Come," [say they], "I will get wine, and we will fill ourselves with strong drink; and tomorrow shall be as this day, [a day] great beyond measure."'),
  ('89ac21ce-0689-55fc-ae1a-65138e6ccf60', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 1, 1, 'The righteous perishes, and no man lays it to heart; and merciful men are taken away, none considering that the righteous is taken away from the evil [to come].'),
  ('0f929f36-86c7-5ca7-afc6-b58576ad56e7', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 2, 2, 'He enters into peace; they rest in their beds, each one who walks in his uprightness.'),
  ('fe3eda99-53f6-562b-a6fb-edb3422e9f46', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 3, 3, '"But draw near here, you sons of the sorceress, the seed of the adulterer and the prostitute.'),
  ('d9c2dec4-f891-5337-a5b3-579de70aee12', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 4, 4, 'Against whom do you sport yourselves? Against whom do you make a wide mouth, and stick out your tongue? Aren''t you children of disobedience, a seed of falsehood,'),
  ('e9c73845-a46b-575e-a939-875b0637060e', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 5, 5, 'you who inflame yourselves among the oaks, under every green tree; who kill the children in the valleys, under the clefts of the rocks?'),
  ('74185e87-4d9b-5ca3-a712-4a6ebab7ef41', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 6, 6, 'Among the smooth [stones] of the valley is your portion; they, they are your lot; you have even poured a drink offering to them. You have offered an offering. Shall I be appeased for these things?'),
  ('151bf98b-f3bd-5c34-a0e1-435c755a0ef8', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 7, 7, 'On a high and lofty mountain you have set your bed; there also you went up to offer sacrifice.'),
  ('6862916c-170f-578c-ade2-dffa5d055288', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 8, 8, 'Behind the doors and the posts you have set up your memorial: for you have uncovered to someone besides me, and have gone up; you have enlarged your bed, and made you a covenant with them: you loved their bed where you saw it.'),
  ('27e77db7-b98b-5f11-a83c-3d5eda864e74', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 9, 9, 'You went to the king with oil, and did increase your perfumes, and did send your ambassadors far off, and debased yourself even to Sheol.'),
  ('f4ec5318-ce13-5fbb-afb8-081187c3d3cb', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 10, 10, 'You were wearied with the length of your way; yet you didn''t say, ''It is in vain.'' You found a reviving of your strength; therefore you weren''t faint.'),
  ('7261a801-ff74-5124-a8df-b7d90543133c', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 11, 11, '"Of whom have you been afraid and in fear, that you lie, and have not remembered me, nor laid it to your heart? Haven''t I held my peace even of long time, and you don''t fear me?'),
  ('fe068d8d-b500-5ff6-a75e-bf330365b81d', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 12, 12, 'I will declare your righteousness; and as for your works, they shall not profit you.'),
  ('61a72444-5cb8-5519-a948-2d2b2b27b4b9', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 13, 13, 'When you cry, let those who you have gathered deliver you; but the wind shall take them, a breath shall carry them all away: but he who takes refuge in me shall possess the land, and shall inherit my holy mountain."'),
  ('78b4a2a7-b52f-5567-a09c-a5f542165fa0', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 14, 14, 'He will say, "Cast up, cast up, prepare the way, take up the stumbling-block out of the way of my people."'),
  ('8c1df570-bd43-5d64-a8c6-6b43899c186b', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 15, 15, 'For thus says the high and lofty One who inhabits eternity, whose name is Holy: "I dwell in the high and holy place, with him also who is of a contrite and humble spirit, to revive the spirit of the humble, and to revive the heart of the contrite.'),
  ('88e9cedb-d75d-5cc6-a762-323af7723fea', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 16, 16, 'For I will not contend forever, neither will I be always angry; for the spirit would faint before me, and the souls who I have made.'),
  ('163e36c3-eb1b-5fca-a8a2-1ab3ec6741ce', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 17, 17, 'For the iniquity of his covetousness was I angry, and struck him; I hid [my face] and was angry; and he went on backsliding in the way of his heart.'),
  ('41b5a980-fb4d-5159-ad97-923ed6c804d9', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 18, 18, 'I have seen his ways, and will heal him: I will lead him also, and restore comforts to him and to his mourners.'),
  ('2edb0a04-bc0c-5439-ab40-6381539b97de', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 19, 19, 'I create the fruit of the lips: Peace, peace, to him who is far off and to him who is near," says Yahweh; "and I will heal them."'),
  ('96e2cce4-cccd-53a4-a1e5-4e6ea5afee5a', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 20, 20, 'But the wicked are like the troubled sea; for it can''t rest, and its waters cast up mire and dirt.'),
  ('4c8e1436-3b7f-516d-adf4-6443e26da8ca', 'bbd40a88-8e31-5d14-a0ef-5064c8712379', NULL, 21, 21, '"There is no peace," says my God, "for the wicked."'),
  ('d406b381-5601-5f5a-a2df-1843423048b4', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 1, 1, '"Cry aloud, don''t spare, lift up your voice like a trumpet, and declare to my people their disobedience, and to the house of Jacob their sins.'),
  ('afeb4548-ec04-5403-ae54-da4c4058f287', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 2, 2, 'Yet they seek me daily, and delight to know my ways: as a nation that did righteousness, and didn''t forsake the ordinance of their God, they ask of me righteous judgments; they delight to draw near to God.'),
  ('49aa05f6-996e-58bf-a4f6-935e0e400ae1', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 3, 3, '''Why have we fasted,'' [say they], ''and you don''t see? [why] have we afflicted our soul, and you take no knowledge?'' "Behold, in the day of your fast you find pleasure, and exact all your labors.'),
  ('843a363a-2456-5973-ac4b-0e4bd1e1fb04', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 4, 4, 'Behold, you fast for strife and contention, and to strike with the fist of wickedness: you don''t fast this day so as to make your voice to be heard on high.'),
  ('46d49b22-2d39-5e90-a7b4-22978a39a548', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 5, 5, 'Is such the fast that I have chosen? the day for a man to afflict his soul? Is it to bow down his head as a rush, and to spread sackcloth and ashes under him? Will you call this a fast, and an acceptable day to Yahweh?'),
  ('6fcd5a2d-7763-5bc3-ae8d-16e6cbcdc3f5', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 6, 6, '"Isn''t this the fast that I have chosen: to release the bonds of wickedness, to undo the bands of the yoke, and to let the oppressed go free, and that you break every yoke?'),
  ('48f7829d-ac53-5bb3-ada1-2162c59e922a', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 7, 7, 'Isn''t it to distribute your bread to the hungry, and that you bring the poor who are cast out to your house? When you see the naked, that you cover him; and that you not hide yourself from your own flesh?'),
  ('031ff9e3-4234-55c7-aa95-1c5121bd3566', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 8, 8, 'Then your light shall break forth as the morning, and your healing shall spring forth speedily; and your righteousness shall go before you; the glory of Yahweh shall be your rear guard.'),
  ('9912e211-32d9-5b13-aeee-10105af33788', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 9, 9, 'Then you shall call, and Yahweh will answer; you shall cry, and he will say, ''Here I am.'' "If you take away from the midst of you the yoke, the putting forth of the finger, and speaking wickedly;'),
  ('ee94b2ea-8163-52ad-a670-910e17ebc7ae', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 10, 10, 'and if you draw out your soul to the hungry, and satisfy the afflicted soul: then your light shall rise in darkness, and your obscurity be as the noonday;'),
  ('1a550207-3092-58dd-af3e-caa345b4d31e', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 11, 11, 'and Yahweh will guide you continually, and satisfy your soul in dry places, and make strong your bones; and you shall be like a watered garden, and like a spring of water, whose waters don''t fail.'),
  ('634425f1-aa4b-59b7-afcf-3923caf7c952', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 12, 12, 'Those who shall be of you shall build the old waste places; you shall raise up the foundations of many generations; and you shall be called The repairer of the breach, The restorer of paths to dwell in.'),
  ('bc6937c9-7a0d-5a3d-a3d9-754112be1580', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 13, 13, '"If you turn away your foot from the Sabbath, from doing your pleasure on my holy day; and call the Sabbath a delight, [and] the holy of Yahweh honorable; and shall honor it, not doing your own ways, nor finding your own pleasure, nor speaking [your own] words:'),
  ('18d3a57c-cac8-5834-a5b4-6d03c3a040cf', '01af8dae-1862-5bed-ae7a-75b22120988a', NULL, 14, 14, 'then you shall delight yourself in Yahweh; and I will make you to ride on the high places of the earth; and I will feed you with the heritage of Jacob your father:" for the mouth of Yahweh has spoken it.'),
  ('e28da5ba-7d49-5f13-aaa7-58eba8bcfd94', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 1, 1, 'Behold, Yahweh''s hand is not shortened, that it can''t save; neither his ear heavy, that it can''t hear:'),
  ('55834a46-847b-55d5-a8bf-c20eb020072e', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 2, 2, 'but your iniquities have separated between you and your God, and your sins have hidden his face from you, so that he will not hear.'),
  ('fa882689-c3a9-5b36-a8a4-7642af610d31', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 3, 3, 'For your hands are defiled with blood, and your fingers with iniquity; your lips have spoken lies, your tongue mutters wickedness.'),
  ('8a025e87-a197-53ae-a07b-ebc28407639f', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 4, 4, 'None sues in righteousness, and none pleads in truth: they trust in vanity, and speak lies; they conceive mischief, and bring forth iniquity.'),
  ('27a79a11-9939-5a88-ab74-fe75e0f508db', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 5, 5, 'They hatch adders'' eggs, and weave the spider''s web: he who eats of their eggs dies; and that which is crushed breaks out into a viper.'),
  ('cc9cbf19-7b53-5e9b-ac83-1e4c95c3559a', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 6, 6, 'Their webs shall not become garments, neither shall they cover themselves with their works: their works are works of iniquity, and the act of violence is in their hands.'),
  ('e8d62aac-5be4-527f-ac58-8ef72bad5cf2', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 7, 7, 'Their feet run to evil, and they make haste to shed innocent blood: their thoughts are thoughts of iniquity; desolation and destruction are in their paths.'),
  ('85b3338d-3eb1-51a2-a12c-64ff8c651b1d', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 8, 8, 'The way of peace they don''t know; and there is no justice in their goings: they have made them crooked paths; whoever goes therein does not know peace.'),
  ('a863efa0-2eb2-56ef-a39f-c0ade791d961', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 9, 9, 'Therefore is justice far from us, neither does righteousness overtake us: we look for light, but, behold, darkness; for brightness, but we walk in obscurity.'),
  ('2de843c1-ccb8-5c6d-aa43-47b554edad95', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 10, 10, 'We grope for the wall like the blind; yes, we grope as those who have no eyes: we stumble at noonday as in the twilight; among those who are lusty we are as dead men.'),
  ('8484f836-fd75-5895-a8e2-4e4a9640ae5a', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 11, 11, 'We roar all like bears, and moan bitterly like doves: we look for justice, but there is none; for salvation, but it is far off from us.'),
  ('92be340a-e309-5728-a56a-c72eb812d974', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 12, 12, 'For our transgressions are multiplied before you, and our sins testify against us; for our transgressions are with us, and as for our iniquities, we know them:'),
  ('2212eb4a-f212-51d6-a2ff-d3eb3dc62d66', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 13, 13, 'transgressing and denying Yahweh, and turning away from following our God, speaking oppression and revolt, conceiving and uttering from the heart words of falsehood.'),
  ('cd6a5c3d-c5b1-5812-ae4c-9e4870515ec9', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 14, 14, 'Justice is turned away backward, and righteousness stands afar off; for truth is fallen in the street, and uprightness can''t enter.'),
  ('2f37b568-4a77-5903-a3e9-4d44bddbb76a', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 15, 15, 'Yes, truth is lacking; and he who departs from evil makes himself a prey. Yahweh saw it, and it displeased him that there was no justice.'),
  ('f4fe19e8-f2ff-55d5-add1-54f854e67243', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 16, 16, 'He saw that there was no man, and wondered that there was no intercessor: therefore his own arm brought salvation to him; and his righteousness, it upheld him.'),
  ('f33561a2-0fd1-5418-ad1e-9131ba4d7702', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 17, 17, 'He put on righteousness as a breastplate, and a helmet of salvation on his head; and he put on garments of vengeance for clothing, and was clad with zeal as a mantle.'),
  ('017e3b5b-fedb-5714-a5ef-a104c76de531', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 18, 18, 'According to their deeds, accordingly he will repay, wrath to his adversaries, recompense to his enemies; to the islands he will repay recompense.'),
  ('56f69144-59dd-5190-af31-62bf07b9eae0', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 19, 19, 'So shall they fear the name of Yahweh from the west, and his glory from the rising of the sun; for he will come as a rushing stream, which the breath of Yahweh drives.'),
  ('e832a3b1-8df1-5662-a228-e34a7d75c312', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 20, 20, '"A Redeemer will come to Zion, and to those who turn from disobedience in Jacob," says Yahweh.'),
  ('c81a14c0-4cac-5fc2-abfe-2f3b5bd271cc', '5c70b22b-bb43-5e55-a455-77d2f5f8bef8', NULL, 21, 21, '"As for me, this is my covenant with them," says Yahweh. "My Spirit who is on you, and my words which I have put in your mouth, shall not depart out of your mouth, nor out of the mouth of your seed, nor out of the mouth of your seed''s seed," says Yahweh, "from henceforth and forever."'),
  ('c2f298a2-3a1f-5937-ae8f-d00d3c720638', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 1, 1, '"Arise, shine; for your light is come, and the glory of Yahweh is risen on you.'),
  ('6f59e665-8859-5a38-ab5c-4d049345356b', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 2, 2, 'For, behold, darkness shall cover the earth, and gross darkness the peoples; but Yahweh will arise on you, and his glory shall be seen on you.'),
  ('ce4ed318-d154-54b3-ac46-f20805691a0a', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 3, 3, 'Nations shall come to your light, and kings to the brightness of your rising.'),
  ('f9c670d6-f905-57df-a2d1-636547c3908e', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 4, 4, '"Lift up your eyes all around, and see: they all gather themselves together, they come to you; your sons shall come from far, and your daughters shall be carried in the arms.'),
  ('15005c68-56ee-5e5c-afec-415b3dea4d40', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 5, 5, 'Then you shall see and be radiant, and your heart shall thrill and be enlarged; because the abundance of the sea shall be turned to you, the wealth of the nations shall come to you.'),
  ('816f72bf-bea2-51f6-a833-3a9667536a54', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 6, 6, 'The multitude of camels shall cover you, the dromedaries of Midian and Ephah; all they from Sheba shall come; they shall bring gold and frankincense, and shall proclaim the praises of Yahweh.'),
  ('02724206-b4f3-564c-a4a7-268b685121d8', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 7, 7, 'All the flocks of Kedar shall be gathered together to you, the rams of Nebaioth shall minister to you; they shall come up with acceptance on my altar; and I will glorify the house of my glory.'),
  ('d24c3ff0-66ac-5de2-ac88-00407a6486e8', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 8, 8, '"Who are these who fly as a cloud, and as the doves to their windows?'),
  ('7ac534f2-c198-5099-aa1f-bc4ee824ddf4', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 9, 9, 'Surely the islands shall wait for me, and the ships of Tarshish first, to bring your sons from far, their silver and their gold with them, for the name of Yahweh your God, and for the Holy One of Israel, because he has glorified you.'),
  ('c751ddad-ec95-5f53-a2c6-bf5d58519a04', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 10, 10, '"Foreigners shall build up your walls, and their kings shall minister to you: for in my wrath I struck you, but in my favor have I had mercy on you.'),
  ('da90ead8-c3fa-581b-ab79-98f1f895457a', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 11, 11, 'Your gates also shall be open continually; they shall not be shut day nor night; that men may bring to you the wealth of the nations, and their kings led captive.'),
  ('1be4d63c-f87b-5512-aff1-047d2aae8b0d', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 12, 12, 'For that nation and kingdom that will not serve you shall perish; yes, those nations shall be utterly wasted.'),
  ('bb872ac1-6c01-5f30-a0af-37341119a57f', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 13, 13, '"The glory of Lebanon shall come to you, the fir tree, the pine, and the box tree together, to beautify the place of my sanctuary; and I will make the place of my feet glorious.'),
  ('bd3fd90b-124f-56af-aed3-aa0c28def40e', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 14, 14, 'The sons of those who afflicted you shall come bending to you; and all those who despised you shall bow themselves down at the soles of your feet; and they shall call you The city of Yahweh, The Zion of the Holy One of Israel.'),
  ('33899601-5d38-51e1-a51c-15efd26773dd', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 15, 15, '"Whereas you have been forsaken and hated, so that no man passed through you, I will make you an eternal excellency, a joy of many generations.'),
  ('78d0f2c4-2621-5f7d-a76d-b651a639b617', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 16, 16, 'You shall also drink the milk of the nations, and shall nurse from royal breasts; and you shall know that I, Yahweh, am your Savior, and your Redeemer, the Mighty One of Jacob.'),
  ('55f27612-031a-5cd6-a384-baa9f0b4c7b3', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 17, 17, 'For brass I will bring gold, and for iron I will bring silver, and for wood brass, and for stones iron. I will also make your officers peace, and righteousness your ruler.'),
  ('1f2bb86c-9fff-5d15-a421-9470a5f477cf', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 18, 18, 'Violence shall no more be heard in your land, desolation nor destruction within your borders; but you shall call your walls Salvation, and your gates Praise.'),
  ('ad529bae-f267-5e5f-a0bf-13e7747787b5', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 19, 19, 'The sun shall be no more your light by day; neither for brightness shall the moon give light to you: but Yahweh will be to you an everlasting light, and your God your glory.'),
  ('fcc4d823-6a1b-56e1-ac2b-48e8fef3faac', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 20, 20, 'Your sun shall no more go down, neither shall your moon withdraw itself; for Yahweh will be your everlasting light, and the days of your mourning shall be ended.'),
  ('c5e0eb08-515a-5805-a6ab-8443a759c92d', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 21, 21, 'Your people also shall be all righteous; they shall inherit the land forever, the branch of my planting, the work of my hands, that I may be glorified.'),
  ('8b33a714-20d6-507a-aa2e-afe7f9c53334', 'ebb99b37-3a2a-5cd5-a7ed-8bebb8dd5014', NULL, 22, 22, 'The little one shall become a thousand, and the small one a strong nation; I, Yahweh, will hasten it in its time."'),
  ('6e1f02db-551a-5ed9-a54f-40e5d0cc9298', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 1, 1, 'The Spirit of the Lord Yahweh is on me; because Yahweh has anointed me to preach good news to the humble. He has sent me to bind up the brokenhearted, to proclaim liberty to the captives, and release to those who are bound;'),
  ('029b0e81-766f-5345-ac79-3f45b1369a1a', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 2, 2, 'to proclaim the year of Yahweh''s favor, and the day of vengeance of our God; to comfort all who mourn;'),
  ('57ba5aae-cc6c-5e8d-a8d7-565a0f1c7695', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 3, 3, 'to appoint to those who mourn in Zion, to give to them a garland for ashes, the oil of joy for mourning, the garment of praise for the spirit of heaviness; that they may be called trees of righteousness, the planting of Yahweh, that he may be glorified.'),
  ('f347ad57-5e4c-5834-a38b-aacc5276f563', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 4, 4, 'They shall build the old wastes, they shall raise up the former desolations, and they shall repair the waste cities, the desolations of many generations.'),
  ('9e30b51e-59e0-5898-ac87-42c0edd4b247', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 5, 5, 'Strangers shall stand and feed your flocks, and foreigners shall be your plowmen and your vinedressers.'),
  ('60fb7f7b-96a9-5bd3-a021-2ea719268fa3', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 6, 6, 'But you shall be named the priests of Yahweh; men will call you the ministers of our God: you will eat the wealth of the nations, and you will boast in their glory.'),
  ('d83f3aee-d80d-5247-a797-9252864f0779', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 7, 7, 'Instead of your shame [you shall have] double; and instead of dishonor they shall rejoice in their portion: therefore in their land they shall possess double; everlasting joy shall be to them.'),
  ('1ac3f3f8-66cd-5666-a8bf-a7f8ab3c9764', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 8, 8, '"For I, Yahweh, love justice, I hate robbery with iniquity; and I will give them their recompense in truth, and I will make an everlasting covenant with them.'),
  ('8b38cb7e-9d22-5980-aa08-28d7a225ccde', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 9, 9, 'Their seed shall be known among the nations, and their offspring among the peoples; all who see them shall acknowledge them, that they are the seed which Yahweh has blessed."'),
  ('ca56fe9c-a01b-5cc5-aca0-778efc7319a5', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 10, 10, 'I will greatly rejoice in Yahweh, my soul shall be joyful in my God; for he has clothed me with the garments of salvation, he has covered me with the robe of righteousness, as a bridegroom decks himself with a garland, and as a bride adorns herself with her jewels.'),
  ('a599f9b3-8cd5-5252-a248-72edd44fbcb0', '8216a4c5-0d6f-5ed3-aaf9-7c609cdaa3af', NULL, 11, 11, 'For as the earth brings forth its bud, and as the garden causes the things that are sown in it to spring forth; so the Lord Yahweh will cause righteousness and praise to spring forth before all the nations.'),
  ('eae4679c-0d2f-5a9a-a279-b94e4e7dd632', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 1, 1, 'For Zion''s sake will I not hold my peace, and for Jerusalem''s sake I will not rest, until her righteousness go forth as brightness, and her salvation as a lamp that burns.'),
  ('a664f339-d64e-519c-ac57-660280de8f57', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 2, 2, 'The nations shall see your righteousness, and all kings your glory, and you shall be called by a new name, which the mouth of Yahweh shall name.'),
  ('7a99fdee-74fa-54dd-a7cf-1ba7b0f8af2b', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 3, 3, 'You shall also be a crown of beauty in the hand of Yahweh, and a royal diadem in the hand of your God.'),
  ('1846035a-335c-5130-ad13-9297713f0d68', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 4, 4, 'You shall no more be termed Forsaken; neither shall your land any more be termed Desolate: but you shall be called Hephzibah, and your land Beulah; for Yahweh delights in you, and your land shall be married.'),
  ('26832804-f2e2-55e6-a421-d956d2f4eb71', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 5, 5, 'For as a young man marries a virgin, so your sons shall marry you; and as the bridegroom rejoices over the bride, so your God will rejoice over you.'),
  ('ebe8a83c-0ebe-588d-afd1-fc1d146f10b6', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 6, 6, 'I have set watchmen on your walls, Jerusalem; they shall never hold their peace day nor night: you who call on Yahweh, take no rest,')
